window.ANSWER_TERMS = {"ATP":{"match":"adenosinetrifosfaat|adenosine trifosfaat|adenosine-trifosfaat|ATP","title":"ATP (adenosinetrifosfaat)","short":"ATP is de energiemunt van de cel: bij afsplitsing van de derde fosfaatgroep komt energie vrij die transport, contractie en biosynthese aandrijft.","definition":"<p><strong>ATP</strong> (adenosinetrifosfaat) bestaat uit adenine, ribose en drie fosfaatgroepen. Hydrolyse van de eindstandige fosfaatbinding (ATP → ADP + P<sub>i</sub>) levert ongeveer 30 kJ/mol — genoeg om ongunstige reacties te koppelen aan een gunstige: spiercontractie, de Na⁺/K⁺-ATPase, en de opbouw van eiwitten, vetten en DNA.</p><p>Het meeste ATP komt uit de <em>oxidatieve fosforylering</em> in het mitochondrion: de elektronentransportketen pompt protonen naar de intermembraanruimte, en ATP-synthase laat die protonengradiënt terugstromen en maakt daarmee ATP (chemiosmose). Glycolyse en de citroenzuurcyclus leveren daarnaast rechtstreeks een kleine hoeveelheid.</p><p>De cel slaat ATP nauwelijks op — de voorraad gaat in seconden — dus productie en verbruik zijn strak gekoppeld: veel ADP versnelt de verbranding, overmaat ATP remt die af.</p>","image_url":"","wiki_titles":["Adenosine triphosphate","ATP synthase"]},"paracriene signalering":{"title":"Paracriene signalering","short":"Een cel scheidt een signaalstof af die alleen op nabijgelegen cellen inwerkt.","definition":"<p>Bij <b>paracriene signalering</b> werkt het afgegeven signaalmolecuul lokaal in op cellen in de directe omgeving.</p><p>De stof wordt snel afgebroken of opgenomen, zodat het effect beperkt blijft tot de buurt. Voorbeeld: histamine bij ontsteking.</p>","image_url":"","wiki_title":"Paracrine signaling","match":"paracriene signalering|paracrien|paracriene secretie|paracriene celsignalering"},"glycoproteine":{"title":"Glycoproteïne","short":"Eiwit met aangehechte suikerketens; veel membraan- en secretie-eiwitten zijn geglycosyleerd.","definition":"<p>Een <b>glycoproteïne</b> is een eiwit waaraan tijdens de rijping in ER en Golgi suikerketens zijn gekoppeld (glycosylering).</p><p>Ze zitten veel in de celmembraan en in secreten en spelen een rol bij herkenning, adhesie en bescherming.</p>","image_url":"","wiki_title":"Glycoprotein","match":"glycoproteïne|glycoproteine|glycoproteïnen|glycoproteinen|glycoproteinen"},"cholesterol":{"title":"Cholesterol","short":"Vetachtige stof die de celmembraan stevigheid en de juiste vloeibaarheid geeft en grondstof is voor steroïden.","definition":"<p><b>Cholesterol</b> is een steroïd dat tussen de fosfolipiden van de celmembraan zit en de membraanvloeibaarheid stabiliseert.</p><p>Het is bovendien de grondstof voor steroïdhormonen, vitamine D en galzouten.</p>","image_url":"","wiki_title":"Cholesterol","match":"cholesterol"},"endocytose":{"title":"Endocytose","short":"Opname van stoffen door de cel via inknopping van de membraan tot een blaasje.","definition":"<p>Bij <b>endocytose</b> stulpt de celmembraan naar binnen en snoert een blaasje af met daarin opgenomen materiaal.</p><p>Varianten zijn fagocytose (grote deeltjes), pinocytose (vloeistof) en receptorgemedieerde endocytose (specifieke moleculen).</p>","image_url":"","wiki_title":"Endocytosis","match":"endocytose"},"necrose":{"title":"Necrose","short":"Ongecontroleerde celdood door schade, waarbij de cel opzwelt, openbarst en een ontstekingsreactie uitlokt.","definition":"<p><b>Necrose</b> is celdood door acute schade (zuurstoftekort, toxinen, trauma). De cel zwelt op en de membraan scheurt.</p><p>De vrijkomende celinhoud lokt een ontstekingsreactie uit — anders dan bij de 'nette' apoptose.</p>","image_url":"","wiki_title":"Necrosis","match":"necrose"},"nadh":{"title":"NADH","short":"Elektronendrager die de citroenzuurcyclus 'oplaadt' en zijn elektronen aan de elektronentransportketen levert.","definition":"<p><b>NADH</b> is de gereduceerde vorm van NAD⁺. Het ontstaat als tijdens glycolyse en citroenzuurcyclus elektronen worden opgenomen.</p><p>In het mitochondrion staat NADH die elektronen weer af aan de elektronentransportketen, wat ATP oplevert.</p>","image_url":"","wiki_title":"Nicotinamide adenine dinucleotide","match":"nadh"},"fosforylering":{"title":"Fosforylering","short":"Toevoeging van een fosfaatgroep aan een eiwit; een veelgebruikte aan/uit-schakelaar van eiwitactiviteit.","definition":"<p><b>Fosforylering</b> is het koppelen van een fosfaatgroep aan een eiwit door een kinase. Een fosfatase haalt hem er weer af.</p><p>Zo schakelen cellen eiwitten razendsnel aan of uit — de basis van veel signaaltransductie.</p>","image_url":"","wiki_title":"Phosphorylation","match":"fosforylering|fosforylatie"},"fibroblast":{"title":"Fibroblast","short":"De belangrijkste bindweefselcel; produceert collageen, elastine en de overige extracellulaire matrix.","definition":"<p>De <b>fibroblast</b> is de meest voorkomende cel in bindweefsel en de dermis. Hij maakt de vezels (collageen, elastine) en de grondsubstantie aan.</p><p>Bij wondgenezing migreren fibroblasten naar de wond, vormen nieuw matrixmateriaal en kunnen als myofibroblast de wond samentrekken.</p>","image_url":"","wiki_title":"Fibroblast","match":"fibroblast|fibroblasten"},"monocyt":{"title":"Monocyt","short":"Grootste witte bloedcel; verlaat het bloed en rijpt in de weefsels uit tot macrofaag of dendritische cel.","definition":"<p>De <b>monocyt</b> is de grootste circulerende leukocyt, met een niervormige kern. Hij circuleert enkele dagen en migreert dan de weefsels in.</p><p>Daar differentieert hij tot macrofaag of dendritische cel, die pathogenen fagocyteren en antigenen presenteren.</p>","image_url":"","wiki_title":"Monocyte","match":"monocyt|monocyten"},"macrofaag":{"title":"Macrofaag","short":"Grote fagocyt in de weefsels die pathogenen en celresten opruimt en antigenen presenteert.","definition":"<p>De <b>macrofaag</b> ontstaat uit een monocyt die het weefsel is binnengegaan. Hij fagocyteert bacteriën, dode cellen en afval.</p><p>Als antigeenpresenterende cel activeert hij ook T-cellen en scheidt hij ontstekingsmediatoren uit. In de huid heten verwante cellen histiocyten.</p>","image_url":"","wiki_title":"Macrophage","match":"macrofaag|macrofagen"},"lymfocyt":{"title":"Lymfocyt","short":"Witte bloedcel van de specifieke afweer; omvat de B-cellen (antistoffen) en T-cellen.","definition":"<p>De <b>lymfocyt</b> is de sleutelcel van het adaptieve (specifieke) immuunsysteem. B-lymfocyten maken antistoffen; T-lymfocyten doden geïnfecteerde cellen of sturen de afweer aan.</p><p>Lymfocyten circuleren tussen bloed, lymfe en lymfoïde organen.</p>","image_url":"","wiki_title":"Lymphocyte","match":"lymfocyt|lymfocyten"},"milt":{"title":"Milt","short":"Lymfoïd orgaan dat oude bloedcellen afbreekt en bloedgedragen ziekteverwekkers filtert.","definition":"<p>De <b>milt</b> filtert het bloed: de rode pulpa ruimt versleten erytrocyten op, de witte pulpa herbergt lymfocyten voor de afweer tegen bloedgedragen pathogenen.</p><p>Ook dient de milt als bloedreservoir.</p>","image_url":"","wiki_title":"Spleen","match":"milt"},"beenmerg":{"title":"Beenmerg","short":"Weefsel in de holten van botten waar alle bloedcellen worden gevormd (hematopoëse).","definition":"<p>Het <b>beenmerg</b> vult de holten van botten. In het rode beenmerg vindt de hematopoëse plaats: de vorming van rode en witte bloedcellen en bloedplaatjes uit stamcellen.</p><p>Het is tevens de plaats waar B-lymfocyten uitrijpen.</p>","image_url":"","wiki_title":"Bone marrow","match":"beenmerg|het beenmerg"},"lymfeklier":{"title":"Lymfeklier","short":"Filterstation in de lymfebaan waar antigenen worden gepresenteerd en de afweerreactie op gang komt.","definition":"<p>De <b>lymfeklier</b> filtert de lymfe en is een ontmoetingsplaats voor antigeenpresenterende cellen en lymfocyten.</p><p>Hier worden T- en B-cellen geactiveerd; bij infectie zwellen lymfeklieren op doordat de lymfocyten zich vermenigvuldigen.</p>","image_url":"","wiki_title":"Lymph node","match":"lymfeklier|lymfeklieren|lymfklier|lymfklieren"},"collageen":{"title":"Collageen","short":"Sterkste structuureiwit van het lichaam; hoofdbestanddeel van bindweefsel, dermis, pezen en bot.","definition":"<p><b>Collageen</b> is het meest voorkomende eiwit in het lichaam en vormt sterke, drievoudig gewonden vezels.</p><p>In de dermis geeft het de huid trekvastheid; fibroblasten maken het aan. Voor de aanmaak is vitamine C nodig (hydroxylering van proline).</p>","image_url":"","wiki_title":"Collagen","match":"collageen"},"elastine":{"title":"Elastine","short":"Rekbaar bindweefseleiwit dat huid, longen en bloedvaten na uitrekking hun vorm laat hervinden.","definition":"<p><b>Elastine</b> vormt elastische vezels die kunnen uitrekken en daarna weer terugveren.</p><p>Het geeft de huid, longen en slagaderwanden hun elasticiteit. Afname van elastine draagt bij aan huidveroudering en rimpels.</p>","image_url":"","wiki_title":"Elastin","match":"elastine"},"plaque":{"title":"Plaque","short":"Verheven, plateauvormige huidafwijking groter dan ~1 cm, vaak door samenvloeien van papels.","definition":"<p>Een <b>plaque</b> is een verheven, afgeplatte laesie groter dan ongeveer 1 cm — breder dan hoog.</p><p>Ze ontstaat vaak door het samenvloeien van papels en is typisch voor psoriasis.</p>","image_url":"","wiki_title":"Skin condition","match":"plaque|plaques"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"vesikel":{"title":"Vesikel","short":"Klein, met helder vocht gevuld blaasje in de huid (< ~1 cm).","definition":"<p>Een <b>vesikel</b> (vesicula) is een klein blaasje gevuld met helder vocht, kleiner dan ongeveer 1 cm.</p><p>Vesikels komen voor bij o.a. herpes, waterpokken en acuut eczeem. Een groter blaasje heet een bulla.</p>","image_url":"","wiki_title":"Blister","match":"vesikel|vesikels|vesicula|vesiculae"},"urtica":{"title":"Urtica","short":"Vluchtige, jeukende, verheven zwelling van de huid — een 'galbult' of kwaddel.","definition":"<p>Een <b>urtica</b> (kwaddel, galbult) is een verheven, bleekroze zwelling door vochtophoping in de dermis, meestal sterk jeukend.</p><p>Ze ontstaat door histamine-afgifte (netelroos/urticaria) en verdwijnt doorgaans binnen 24 uur weer.</p>","image_url":"","wiki_title":"Hives","match":"urtica|urticae"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"atrofie":{"title":"Atrofie","short":"Verdunning of afname van weefsel; bij de huid een dunnere, kwetsbaardere epidermis en/of dermis.","definition":"<p><b>Atrofie</b> is het slinken van een weefsel of orgaan doordat de cellen krimpen of in aantal afnemen.</p><p>Huidatrofie (bijv. na langdurig sterk corticosteroïdgebruik of door veroudering) geeft een dunne, doorschijnende, kwetsbare huid.</p>","image_url":"","wiki_title":"Atrophy","match":"atrofie"},"autosomaal dominant":{"title":"Autosomaal dominant","short":"Overervingspatroon waarbij één afwijkend gen (op een niet-geslachtschromosoom) al ziekte geeft.","definition":"<p>Bij <b>autosomaal dominante</b> overerving volstaat één gemuteerd allel op een autosoom om de aandoening tot uiting te laten komen.</p><p>Aangedane ouders geven het gemiddeld aan de helft van hun kinderen door; de aandoening komt in elke generatie voor, ongeacht geslacht.</p>","image_url":"","wiki_title":"Dominance (genetics)","match":"autosomaal dominant"},"puntmutatie":{"title":"Puntmutatie","short":"Verandering van één enkele DNA-base.","definition":"<p>Een <b>puntmutatie</b> is de vervanging, invoeging of verwijdering van één enkele base in het DNA.</p><p>Afhankelijk van het effect op het codon spreekt men van een stille, missense of nonsense mutatie.</p>","image_url":"","wiki_title":"Point mutation","match":"puntmutatie"},"tuberculose":{"title":"Tuberculose","short":"Tuberculose is een infectie met Mycobacterium tuberculosis, meestal in de longen, met langdurig hoesten, nachtzweten, gewichtsverlies en granulomen.","definition":"<p><strong>Tuberculose</strong> wordt veroorzaakt door <em>Mycobacterium tuberculosis</em> en verspreidt zich via aerosolen. Na infectie wordt de bacterie meestal ingekapseld in granulomen (latente tbc); bij verminderde afweer kan actieve ziekte ontstaan.</p><p>Longtuberculose geeft langdurig hoesten (soms met bloed), koorts, nachtzweten en gewichtsverlies; typisch zijn holtevorming in de longtoppen en granulomen met centrale <em>verkazing</em>. Behandeling met een combinatie van tuberculostatica gedurende minstens 6 maanden.</p>","image_url":"","wiki_title":"Tuberculosis","match":"tuberculose|tbc|tb","option_only":true},"endocarditis":{"title":"Endocarditis","short":"Endocarditis is een infectie van het endocard, meestal van de hartkleppen, met vegetaties, koorts en een nieuw hartgeruis.","definition":"<p>Bij <strong>infectieuze endocarditis</strong> nestelen bacteriën (vaak <em>S. aureus</em>, streptokokken of enterokokken) zich op de hartkleppen en vormen vegetaties van bloedplaatjes, fibrine en micro-organismen.</p><p>Risicofactoren zijn klepafwijkingen, kunstkleppen en intraveneus drugsgebruik. Symptomen: koorts, een nieuw souffle en embolische verschijnselen (splinterbloedingen, Janewaylaesies, Oslernoduli, Rothvlekken). Diagnose via herhaalde bloedkweken en echocardiografie (Duke-criteria).</p>","image_url":"","wiki_title":"Infective endocarditis","match":"endocarditis|infectieuze endocarditis|bacteriële endocarditis","option_only":true},"metoprolol":{"title":"Metoprolol","short":"Metoprolol is een cardioselectieve bètablokker (β1) die hartfrequentie en contractiekracht verlaagt; gebruikt bij hypertensie, angina pectoris en hartfalen.","definition":"<p><strong>Metoprolol</strong> is een <em>β1-selectieve</em> bètablokker. Door blokkade van β1-receptoren in het hart dalen hartfrequentie, contractiliteit en geleidingssnelheid in de AV-knoop; in de nier remt het de reninesecretie.</p><p>Indicaties: hypertensie, angina pectoris, na een myocardinfarct, hartfalen en ritmestoornissen (frequentiecontrole). Bijwerkingen: bradycardie, vermoeidheid, koude extremiteiten. Bij hoge doses verdwijnt de selectiviteit en kan bronchoconstrictie optreden.</p>","image_url":"","wiki_title":"Metoprolol","match":"metoprolol","option_only":true},"bisoprolol":{"title":"Bisoprolol","short":"Bisoprolol is een sterk β1-selectieve bètablokker, gebruikt bij hypertensie, angina pectoris en hartfalen.","definition":"<p><strong>Bisoprolol</strong> is een <em>cardioselectieve</em> bètablokker met een hoge affiniteit voor β1-receptoren in het hart. Het verlaagt hartfrequentie, contractiekracht en zuurstofverbruik van het myocard.</p><p>Het wordt eenmaal daags gegeven bij hypertensie, stabiele angina pectoris, ritmestoornissen en hartfalen met verminderde ejectiefractie. Bijwerkingen zijn bradycardie, vermoeidheid en koude handen en voeten.</p>","image_url":"","wiki_title":"Bisoprolol","match":"bisoprolol","option_only":true},"hydrochloorthiazide":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"hydrochloorthiazide|hctz|thiazide|thiazidediureticum|thiazide diureticum|hydrochloortiazide","option_only":true},"acetylsalicylzuur":{"title":"Acetylsalicylzuur","short":"Acetylsalicylzuur (aspirine) remt onomkeerbaar het enzym cyclo-oxygenase; in lage dosis remt het de bloedplaatjesaggregatie.","definition":"<p><strong>Acetylsalicylzuur</strong> acetyleert en remt <em>onomkeerbaar</em> het enzym cyclo-oxygenase (COX-1 en COX-2). Daardoor worden minder prostaglandinen en tromboxaan A<sub>2</sub> gevormd.</p><p>In lage dosis (80–100 mg) remt het via tromboxaan de bloedplaatjesaggregatie voor de hele levensduur van het plaatje (±7–10 dagen); dit wordt gebruikt ter preventie van hart- en vaatziekten. In hoge dosis werkt het pijnstillend, koortsverlagend en ontstekingsremmend. Bijwerkingen: maagulcera, bloedingen en bij kinderen het syndroom van Reye.</p>","image_url":"","wiki_title":"Aspirin","match":"acetylsalicylzuur|aspirine|ascal|asa|carbasalaatcalcium","option_only":true},"urokinase":{"title":"Urokinase","short":"Urokinase is een plasminogeenactivator: het zet plasminogeen om in plasmine, dat fibrine afbreekt (fibrinolyse).","definition":"<p><strong>Urokinase</strong> (urokinase-type plasminogeenactivator, uPA) is een serineprotease dat <em>plasminogeen</em> omzet in het actieve <em>plasmine</em>. Plasmine breekt fibrine af en lost zo bloedstolsels op.</p><p>Het wordt o.a. in de nier gemaakt. Als geneesmiddel is het een trombolyticum, net als alteplase (tPA) en streptokinase; daarnaast speelt uPA een rol bij weefselremodellering en tumorinvasie.</p>","image_url":"","wiki_title":"Urokinase","match":"urokinase|upa","option_only":true},"glucose":{"title":"Glucose","short":"Glucose is een monosacharide (C₆H₁₂O₆) en de belangrijkste brandstof van het lichaam; de bloedspiegel wordt strak geregeld door insuline en glucagon.","definition":"<p><strong>Glucose</strong> is een hexose en de centrale brandstof van het metabolisme. Cellen breken het af via de glycolyse en daarna (aeroob) via de citroenzuurcyclus en oxidatieve fosforylering tot CO<sub>2</sub> en water, met vorming van ATP.</p><p>Het lichaam slaat glucose op als <em>glycogeen</em> in lever en spier. De bloedglucose (normaal nuchter ±4–6 mmol/L) wordt verlaagd door insuline en verhoogd door glucagon, adrenaline en cortisol. Het brein is sterk afhankelijk van glucose.</p>","image_url":"","wiki_title":"Glucose","match":"glucose|druivensuiker|bloedglucose","option_only":true},"magnesium":{"title":"Magnesium","short":"Magnesium is een belangrijk intracellulair kation, cofactor van ATP-afhankelijke enzymen en nodig voor stabiele zenuw- en spierprikkelbaarheid.","definition":"<p><strong>Magnesium</strong> (Mg<sup>2+</sup>) zit vooral in bot en intracellulair. Het is cofactor van honderden enzymen, met name die met ATP werken, en stabiliseert de membraanpotentiaal.</p><p>Hypomagnesiëmie (o.a. door diuretica, PPI's, alcohol of diarree) geeft spierkrampen, tetanie, ritmestoornissen en kan hypokaliëmie en hypocalciëmie onderhouden (PTH-secretie daalt). Magnesiumsulfaat wordt gebruikt bij (pre-)eclampsie en torsade de pointes.</p>","image_url":"","wiki_title":"Magnesium in biology","match":"magnesium|mg2+|magnesiumsulfaat","option_only":true},"alcohol":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"alcohol|ethanol|alcoholgebruik|overmatig alcoholgebruik|alcoholmisbruik","option_only":true},"endotheelcellen":{"title":"Endotheelcellen","short":"Endotheelcellen bekleden als één dunne laag de binnenkant van alle bloed- en lymfevaten en regelen vaattonus, stolling en doorlaatbaarheid.","definition":"<p><strong>Endotheel</strong> is een enkellaags plaveiselepitheel dat de binnenwand (tunica intima) van bloed- en lymfevaten en het hart bekleedt.</p><p>Endotheelcellen zijn actief: ze maken vaatverwijders (NO, prostacycline) en -vernauwers (endotheline), houden het bloed vloeibaar (antistollingsfactoren) maar kunnen bij beschadiging de stolling activeren (von Willebrandfactor), en laten leukocyten via adhesiemoleculen het weefsel in tijdens ontsteking.</p>","image_url":"","wiki_title":"Endothelium","match":"endotheelcellen|endotheel|endotheelcel","option_only":true},"gladde spiercellen":{"title":"Gladde spiercellen","short":"Gladde spiercellen zijn spoelvormige, onwillekeurig aangestuurde spiercellen zonder dwarsstreping, in de wand van vaten en holle organen.","definition":"<p><strong>Gladde spiercellen</strong> zijn spoelvormige cellen met één centraal gelegen kern. Actine en myosine liggen niet in sarcomeren, daarom ontbreekt de dwarsstreping. Contractie wordt via calcium-calmoduline en myosine-lichteketenkinase gereguleerd.</p><p>Ze komen voor in de wand van bloedvaten, luchtwegen, maag-darmkanaal, blaas en uterus en worden aangestuurd door het autonome zenuwstelsel, hormonen en lokale factoren. Ze kunnen langdurig samentrekken met weinig energieverbruik.</p>","image_url":"","wiki_title":"Smooth muscle","match":"gladde spiercellen|glad spierweefsel|gladde spier|gladde spiercel","option_only":true},"hypertensie":{"title":"Hypertensie","short":"Hypertensie is een blijvend verhoogde bloeddruk (≥140/90 mmHg op het spreekuur); een belangrijke risicofactor voor hart- en vaatziekten.","definition":"<p>Bij <strong>hypertensie</strong> is de bloeddruk herhaaldelijk verhoogd: op het spreekuur ≥140/90 mmHg. Meestal is er geen aanwijsbare oorzaak (<em>primaire/essentiële</em> hypertensie); bij een minderheid is er een secundaire oorzaak, zoals nierziekte, nierarteriestenose, hyperaldosteronisme of feochromocytoom.</p><p>Hypertensie geeft meestal geen klachten, maar beschadigt op termijn vaten en organen: linkerventrikelhypertrofie, hartfalen, CVA, nierschade en retinopathie. Behandeling: leefstijl (zout, gewicht, beweging, alcohol) en medicatie (o.a. diuretica, ACE-remmers/ARB's, calciumantagonisten).</p>","image_url":"","wiki_title":"Hypertension","match":"hypertensie|hoge bloeddruk|arteriële hypertensie","option_only":true},"myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"myocardinfarct|hartinfarct|acuut myocardinfarct|ami","option_only":true},"mitralisklepstenose":{"title":"Mitralisklepstenose","short":"Bij mitralisstenose is de klep tussen linkeratrium en linkerventrikel vernauwd, meestal door reuma; het linkeratrium raakt overbelast, met boezemfibrilleren en longstuwing.","definition":"<p>Bij een <strong>mitralisklepstenose</strong> opent de mitralisklep onvoldoende. De belangrijkste oorzaak wereldwijd is <em>acuut reuma</em> in het verleden; bij ouderen ook verkalking.</p><p>De druk in het linkeratrium stijgt, het atrium verwijdt (risico op <em>boezemfibrilleren</em> en trombo-embolie) en de druk wordt doorgegeven naar de longvenen: longstuwing, kortademigheid en uiteindelijk pulmonale hypertensie. Bij auscultatie: een luide eerste toon, openingssnap en een laagfrequent diastolisch geruis.</p>","image_url":"","wiki_title":"Mitral valve stenosis","match":"mitralisklepstenose|mitralisstenose","option_only":true},"ventriculaire vullingsfase":{"title":"Ventriculaire vullingsfase","short":"De vullingsfase is het deel van de diastole waarin de AV-kleppen open zijn en bloed vanuit de atria de ventrikels instroomt.","definition":"<p>Tijdens de <strong>ventriculaire vullingsfase</strong> is de druk in de ventrikel lager dan in het atrium; de mitralis- en tricuspidalisklep staan open en de aorta- en pulmonalisklep zijn dicht.</p><p>De vulling verloopt in drie stappen: snelle passieve vulling direct na opening van de AV-kleppen, daarna langzame vulling (diastase), en ten slotte de <em>atriale contractie</em>, die vooral bij een hoge hartfrequentie of stijve ventrikel een belangrijk deel bijdraagt.</p>","image_url":"","wiki_title":"Cardiac cycle","match":"ventriculaire vullingsfase|vullingsfase|ventrikelvulling|diastolische vulling","option_only":true},"isovolumetrische relaxatiefase":{"title":"Isovolumetrische relaxatiefase","short":"In de isovolumetrische relaxatie ontspant de ventrikel terwijl alle kleppen gesloten zijn: de druk daalt snel, het volume blijft gelijk.","definition":"<p>De <strong>isovolumetrische relaxatiefase</strong> is het begin van de diastole. Het myocard ontspant terwijl zowel de semilunaire kleppen als de AV-kleppen gesloten zijn, zodat de ventrikeldruk snel daalt bij een gelijkblijvend volume (het eindsystolisch volume). Zodra de ventrikeldruk onder de atriumdruk zakt, openen de AV-kleppen en begint de vulling.</p>","image_url":"","wiki_title":"Cardiac cycle","match":"isovolumetrische relaxatiefase|isovolumetrische relaxatie|isovolumische relaxatie","option_only":true},"ejectiefase":{"title":"Ejectiefase","short":"In de ejectiefase is de ventrikeldruk hoger dan de druk in aorta/a. pulmonalis: de semilunaire kleppen staan open en het slagvolume wordt uitgepompt.","definition":"<p>De <strong>ejectiefase</strong> volgt op de isovolumetrische contractie. Zodra de druk in de linkerventrikel hoger wordt dan in de aorta (en rechts dan in de a. pulmonalis), openen de semilunaire kleppen en wordt bloed uitgedreven.</p><p>Eerst gaat dat snel, daarna langzamer. Tijdens deze fase daalt het ventrikelvolume van het einddiastolisch naar het eindsystolisch volume; het verschil is het slagvolume. De fase eindigt met het sluiten van de semilunaire kleppen (tweede harttoon).</p>","image_url":"","wiki_title":"Cardiac cycle","match":"ejectiefase|ejectie|uitdrijvingsfase|ventriculaire ejectie","option_only":true},"diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus|diabetes|suikerziekte|diabetes mellitus type 2|diabetes mellitus type 1|diabetes mellitus 2","option_only":true},"obesitas":{"title":"Obesitas","short":"Obesitas is ernstig overgewicht (BMI ≥30 kg/m²) met verhoogd risico op diabetes type 2, hart- en vaatziekten, artrose en bepaalde kankers.","definition":"<p>Bij <strong>obesitas</strong> is er een overmaat aan lichaamsvet, gedefinieerd als een <em>BMI ≥30 kg/m²</em>. Vooral vet in de buik (grote middelomtrek, visceraal vet) is metabool ongunstig.</p><p>Obesitas verhoogt het risico op insulineresistentie en diabetes type 2, hypertensie, dyslipidemie, hart- en vaatziekten, slaapapneu, leververvetting, artrose en verschillende vormen van kanker. Oorzaken zijn een combinatie van leefstijl, omgeving, genetische aanleg en soms medicatie of hormonale ziekten.</p>","image_url":"","wiki_title":"Obesity","match":"obesitas|ernstig overgewicht|adipositas","option_only":true},"systemische lupus erythematosus":{"title":"Systemische lupus erythematosus (SLE)","short":"SLE is een systemische auto-immuunziekte met antinucleaire antistoffen en immuuncomplexen; gewrichten, huid, nieren en bloed kunnen aangedaan zijn.","definition":"<p><strong>Systemische lupus erythematosus</strong> is een chronische auto-immuunziekte die vooral jonge vrouwen treft. Er worden antistoffen gevormd tegen kerncomponenten (ANA, anti-dsDNA, anti-Sm), die met antigenen <em>immuuncomplexen</em> vormen die neerslaan in weefsels (type III-reactie) en complement verbruiken.</p><p>Kenmerken: artralgie/artritis, vlindervormig erytheem in het gezicht, fotosensitiviteit, serositis, nefritis, cytopenieën en neurologische verschijnselen. Behandeling met o.a. hydroxychloroquine, corticosteroïden en immunosuppressiva.</p>","image_url":"","wiki_title":"Systemic lupus erythematosus","match":"systemische lupus erythematosus|sle|lupus|systemic lupus erythematosus","option_only":true},"henoch-schönlein vasculitis":{"title":"IgA-vasculitis (Henoch-Schönlein)","short":"IgA-vasculitis is een vasculitis van kleine vaten met IgA-neerslagen, vooral bij kinderen: palpabele purpura op de benen, buikpijn, artritis en nierbetrokkenheid.","definition":"<p><strong>IgA-vasculitis</strong> (vroeger Henoch-Schönlein purpura) is de meest voorkomende vasculitis bij kinderen, vaak na een bovenste luchtweginfectie. IgA-bevattende immuuncomplexen slaan neer in de wand van kleine vaten.</p><p>Kenmerkende tetrade: <em>palpabele purpura</em> op billen en benen (bij normale bloedplaatjes), artralgie/artritis, koliekachtige buikpijn (soms invaginatie) en nierbetrokkenheid (hematurie, IgA-nefropathie-achtig beeld). Meestal zelflimiterend; nierfunctie vervolgen.</p>","image_url":"","wiki_title":"IgA vasculitis","match":"henoch-schönlein vasculitis|henoch-schönlein purpura|henoch schönlein|iga-vasculitis|purpura van henoch-schönlein|de ziekte van henoch schönlein","option_only":true},"de ziekte van von willebrand":{"title":"Ziekte van Von Willebrand","short":"De ziekte van Von Willebrand is de meest voorkomende erfelijke bloedingsziekte: een tekort of defect van de von Willebrandfactor, met slijmvliesbloedingen.","definition":"<p>Bij de <strong>ziekte van Von Willebrand</strong> is de von Willebrandfactor (vWF) verminderd of afwijkend. vWF verbindt bloedplaatjes met het beschadigde subendotheel en beschermt factor VIII tegen afbraak.</p><p>Het is de meest voorkomende erfelijke stollingsstoornis (meestal autosomaal dominant). Er zijn vooral <em>slijmvliesbloedingen</em>: neusbloedingen, tandvleesbloedingen, hevige menstruaties en nabloeden na ingrepen. De bloedingstijd is verlengd; de APTT kan verlengd zijn door een lager factor VIII.</p>","image_url":"","wiki_title":"Von Willebrand disease","match":"de ziekte van von willebrand|ziekte van von willebrand|von willebrand|von willebrandziekte","option_only":true},"hemofilie a":{"title":"Hemofilie A","short":"Hemofilie A is een X-gebonden erfelijk tekort aan stollingsfactor VIII, met gewrichts- en spierbloedingen, vooral bij jongens.","definition":"<p><strong>Hemofilie A</strong> is een geslachtsgebonden recessieve aandoening (X-chromosoom) met een tekort aan <em>factor VIII</em>; hemofilie B is een tekort aan factor IX. Vooral jongens/mannen zijn aangedaan; vrouwen zijn meestal draagster.</p><p>Omdat de secundaire hemostase (fibrinevorming) tekortschiet, ontstaan diepe bloedingen: in gewrichten (hemartros), spieren en na trauma of ingrepen. De APTT is verlengd, PT en bloedplaatjes zijn normaal. Behandeling met factor VIII-concentraat of emicizumab.</p>","image_url":"","wiki_title":"Haemophilia A","match":"hemofilie a|haemofilie a|hemophilia a","option_only":true},"auto-immuun hemolytische anemie":{"title":"Auto-immuun hemolytische anemie","short":"Bij AIHA maakt het lichaam antistoffen tegen de eigen rode bloedcellen, die daardoor worden afgebroken; de directe antiglobulinetest (Coombs) is positief.","definition":"<p>Bij <strong>auto-immuun hemolytische anemie</strong> binden auto-antistoffen aan erytrocyten, die vervolgens vooral in de milt worden afgebroken (type II-overgevoeligheid). Bij <em>warme</em> AIHA gaat het om IgG; bij <em>koude</em> AIHA om IgM met complementactivatie.</p><p>Laboratorium: anemie met verhoogde reticulocyten, verhoogd LDH en ongeconjugeerd bilirubine, verlaagd haptoglobine, sferocyten en een positieve directe antiglobulinetest (Coombs). Oorzaken: idiopathisch, lymfoproliferatieve ziekten, SLE, infecties (Mycoplasma, EBV) of geneesmiddelen.</p>","image_url":"","wiki_title":"Autoimmune hemolytic anemia","match":"auto-immuun hemolytische anemie|aiha|autoimmuun hemolytische anemie|auto-immuunhemolytische anemie","option_only":true},"acuut ernstig bloedverlies":{"title":"Acuut ernstig bloedverlies","short":"Bij acuut ernstig bloedverlies daalt het circulerend volume; het lichaam reageert met tachycardie en vaatvernauwing, en bij groot verlies ontstaat hypovolemische shock.","definition":"<p>Bij <strong>acuut bloedverlies</strong> verliest het lichaam in korte tijd veel bloedvolume. De baroreceptorreflex activeert het sympathische zenuwstelsel: tachycardie, vasoconstrictie (bleke, koude huid) en verhoogde contractiliteit; het RAAS en ADH houden zout en water vast.</p><p>In de eerste uren is het <em>hemoglobine nog normaal</em>, omdat bloed met cellen én plasma tegelijk verloren gaat; pas na verdunning met weefselvocht (en infusie) daalt het Hb. Bij groot verlies (&gt;30–40%) ontstaat hypovolemische shock met hypotensie en orgaanhypoperfusie.</p>","image_url":"","wiki_title":"","match":"acuut ernstig bloedverlies|acuut bloedverlies|hemorragische shock","option_only":true},"koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"koorts|febris|pyrexie|hoge koorts","option_only":true},"lever":{"title":"Lever","short":"De lever is de grootste klier van het lichaam: hij regelt stofwisseling van suikers, vetten en eiwitten, maakt gal en eiwitten (o.a. albumine, stollingsfactoren) en ontgift stoffen.","definition":"<p>De <strong>lever</strong> ligt rechtsboven in de buik en krijgt bloed uit de a. hepatica en (voor ±75%) uit de <em>v. portae</em>, met voedingsstoffen uit de darm.</p><p>Functies: opslag en afgifte van glucose (glycogeen, gluconeogenese), vet- en cholesterolmetabolisme, aanmaak van plasma-eiwitten (albumine, stollingsfactoren), ureumvorming, galproductie, afbraak van bilirubine en ontgifting van geneesmiddelen en alcohol. Functionele eenheden zijn de leverlobjes met hepatocyten rond sinusoïden.</p>","image_url":"","wiki_title":"Liver","match":"lever|hepar","option_only":true},"maag":{"title":"Maag","short":"De maag slaat voedsel tijdelijk op, mengt het met maagzuur en pepsine en geeft het geleidelijk af aan het duodenum.","definition":"<p>De <strong>maag</strong> bestaat uit cardia, fundus, corpus, antrum en pylorus. Het slijmvlies bevat klieren met <em>pariëtale cellen</em> (zoutzuur en intrinsieke factor), <em>hoofdcellen</em> (pepsinogeen), slijmcellen en endocriene cellen (o.a. G-cellen met gastrine in het antrum).</p><p>De maag doodt micro-organismen, start de eiwitvertering en mengt voedsel tot chymus. Intrinsieke factor is nodig voor opname van vitamine B12 in het terminale ileum.</p>","image_url":"","wiki_title":"Stomach","match":"maag|gaster|ventriculus","option_only":true},"pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"pancreas|alvleesklier","option_only":true},"galblaas":{"title":"Galblaas","short":"De galblaas slaat gal uit de lever op en dikt die in; na een vetrijke maaltijd trekt hij samen onder invloed van cholecystokinine.","definition":"<p>De <strong>galblaas</strong> ligt aan de onderzijde van de lever en is via de ductus cysticus verbonden met de galwegen. Ze slaat de gal die de lever continu maakt op en concentreert die door water en zout terug te resorberen.</p><p>Na een (vetrijke) maaltijd geeft het duodenum <em>cholecystokinine</em> af: de galblaas trekt samen en de sfincter van Oddi ontspant, zodat gal in het duodenum komt voor de vetvertering. Galstenen kunnen koliek, cholecystitis of een choledocholithiasis geven.</p>","image_url":"","wiki_title":"Gallbladder","match":"galblaas|vesica biliaris|vesica fellea","option_only":true},"angiogenese":{"title":"Angiogenese","short":"Angiogenese is de vorming van nieuwe bloedvaten uit bestaande vaten, gestimuleerd door o.a. VEGF; belangrijk bij wondgenezing en tumorgroei.","definition":"<p>Bij <strong>angiogenese</strong> spruiten nieuwe capillairen uit bestaande vaten. Endotheelcellen breken de basaalmembraan af, migreren, prolifereren en vormen nieuwe buisjes, gevolgd door rekrutering van pericyten.</p><p>Het belangrijkste stimulerende signaal is <em>VEGF</em>, dat o.a. bij hypoxie wordt gemaakt. Angiogenese is essentieel bij embryonale ontwikkeling, wondgenezing (granulatieweefsel) en de menstruele cyclus, maar ook bij tumorgroei en diabetische retinopathie; VEGF-remmers worden daarom bij kanker en maculadegeneratie gebruikt.</p>","image_url":"","wiki_title":"Angiogenesis","match":"angiogenese|neovascularisatie|angiogenesis","option_only":true},"t-cellen":{"title":"T-cellen","short":"T-cellen zijn lymfocyten die in de thymus rijpen en antigeen herkennen dat via MHC wordt gepresenteerd; CD4-cellen helpen, CD8-cellen doden geïnfecteerde cellen.","definition":"<p><strong>T-cellen</strong> ontstaan in het beenmerg en rijpen in de <em>thymus</em>, waar positieve en negatieve selectie plaatsvindt. Hun T-celreceptor herkent alleen peptiden die door MHC-moleculen worden gepresenteerd.</p><p><em>CD4⁺ T-helpercellen</em> herkennen MHC-II en sturen de afweer met cytokines (Th1, Th2, Th17, Tfh); <em>CD8⁺ cytotoxische T-cellen</em> herkennen MHC-I en doden geïnfecteerde of tumorcellen; regulatoire T-cellen remmen de afweer. Ze vormen de cellulaire adaptieve immuniteit.</p>","image_url":"","wiki_title":"T cell","match":"t-cellen|t cellen|t-lymfocyten|t-cel|t-lymfocyt|t cel","option_only":true},"samenvatten":{"title":"Samenvatten (gesprekstechniek)","short":"Samenvatten is een gesprekstechniek waarbij de arts de kern van wat de patiënt heeft verteld kort in eigen woorden teruggeeft, om te checken en te structureren.","definition":"<p>Bij <strong>samenvatten</strong> vat de arts meerdere uitspraken of een heel gespreksdeel van de patiënt kort samen. Het doel is te controleren of de informatie goed begrepen is, overzicht te geven en het gesprek te structureren, bijvoorbeeld als afsluiting van een fase voordat een nieuw onderwerp begint.</p><p>Samenvatten gaat over de inhoud van een groter deel van het gesprek; het verschilt daarin van parafraseren, dat één uitspraak teruggeeft.</p>","image_url":"","wiki_title":"","match":"samenvatten|samenvatting geven","option_only":true},"calcium":{"title":"Calcium","short":"Calcium is nodig voor botten, spiercontractie, zenuwgeleiding en stolling; de bloedspiegel wordt geregeld door PTH, vitamine D en calcitonine.","definition":"<p>Het meeste <strong>calcium</strong> zit in botten als hydroxyapatiet. In het bloed is ongeveer de helft eiwitgebonden (vooral aan albumine) en de rest vrij geïoniseerd, de biologisch actieve vorm. Calcium is tweede boodschapper in cellen en essentieel voor spiercontractie, neurotransmitterafgifte en stolling. Afwijkingen geven bijv. tetanie (hypocalciëmie) of dorst, obstipatie en verwardheid (hypercalciëmie).</p>","image_url":"","wiki_title":"Calcium in biology","match":"calcium|ca2+|calciumion","option_only":true},"natrium":{"title":"Natrium","short":"Natrium is het belangrijkste kation buiten de cel; het bepaalt grotendeels het extracellulaire volume en de osmolaliteit.","definition":"<p><strong>Natrium</strong> wordt door de Na⁺/K⁺-ATPase buiten de cel gehouden, waardoor een gradiënt ontstaat die nodig is voor actiepotentialen en secundair actief transport. De hoeveelheid natrium in het lichaam bepaalt het extracellulaire volume (via RAAS en natriuretische peptiden); de natriumconcentratie weerspiegelt vooral de waterbalans (via ADH en dorst).</p>","image_url":"","wiki_title":"Sodium in biology","match":"natrium|na+|natriumion","option_only":true},"kalium":{"title":"Kalium","short":"Kalium is het belangrijkste kation in de cel; de spiegel in het bloed is cruciaal voor de membraanpotentiaal van hart en spieren.","definition":"<p>Ongeveer 98% van het <strong>kalium</strong> zit intracellulair. De extracellulaire concentratie (3,5–5 mmol/L) bepaalt de rustmembraanpotentiaal. Insuline, bèta-2-agonisten en alkalose verschuiven kalium de cel in; aldosteron bevordert de uitscheiding in de nier. Zowel te hoge als te lage waarden kunnen gevaarlijke hartritmestoornissen geven.</p>","image_url":"","wiki_title":"Potassium in biology","match":"kalium|k+|kaliumion","option_only":true},"creatinine":{"title":"Creatinine","short":"Creatinine is een afbraakproduct van creatinefosfaat uit spieren; de bloedwaarde wordt gebruikt om de nierfunctie te schatten.","definition":"<p><strong>Creatinine</strong> ontstaat in een vrij constant tempo uit creatine in spieren en wordt vooral door glomerulaire filtratie uitgescheiden. Daarom stijgt de serumwaarde als de nierfunctie (GFR) daalt; op basis van creatinine, leeftijd en geslacht wordt de eGFR berekend. Spiermassa beïnvloedt de waarde: bij weinig spiermassa kan een normaal creatinine een verminderde nierfunctie maskeren.</p>","image_url":"","wiki_title":"Creatinine","match":"creatinine|kreatinine|serumcreatinine","option_only":true},"triglyceriden":{"title":"Triglyceriden","short":"Triglyceriden zijn vetten opgebouwd uit glycerol met drie vetzuren; ze zijn de belangrijkste energieopslag in vetweefsel.","definition":"<p><strong>Triglyceriden</strong> worden uit de voeding via chylomicronen en uit de lever via VLDL door het bloed vervoerd. Lipoproteïnelipase in de capillairen splitst ze, zodat vetzuren in spier- en vetweefsel worden opgenomen. Een verhoogd triglyceridengehalte komt voor bij obesitas, diabetes, alcoholgebruik en erfelijke vetstofwisselingsstoornissen; zeer hoge waarden geven risico op pancreatitis.</p>","image_url":"","wiki_title":"Triglyceride","match":"triglyceriden|triglyceride|triacylglycerol","option_only":true},"lisinopril":{"title":"Lisinopril","short":"Lisinopril is een ACE-remmer die de vorming van angiotensine II remt; gebruikt bij hypertensie en hartfalen.","definition":"<p><strong>Lisinopril</strong> remt het angiotensine-converterend enzym. Daardoor ontstaat minder angiotensine II (minder vasoconstrictie en aldosteron) en wordt minder bradykinine afgebroken. Het verlaagt de bloeddruk en beschermt hart en nieren. Bijwerkingen: prikkelhoest (bradykinine), hyperkaliëmie, stijging van creatinine en zelden angio-oedeem.</p>","image_url":"","wiki_title":"Lisinopril","match":"lisinopril","option_only":true},"ace remmer":{"title":"ACE-remmer","short":"ACE-remmers remmen de omzetting van angiotensine I naar angiotensine II; ze verlagen de bloeddruk en beschermen hart en nieren.","definition":"<p><strong>ACE-remmers</strong> (bijv. lisinopril, enalapril, perindopril) remmen het angiotensine-converterend enzym. Daardoor dalen vasoconstrictie en aldosteronafgifte, en stijgt bradykinine. Ze worden gebruikt bij hypertensie, hartfalen, na een myocardinfarct en bij diabetische nefropathie. Bijwerkingen: prikkelhoest, hyperkaliëmie, creatininestijging en angio-oedeem; niet geven in de zwangerschap.</p>","image_url":"","wiki_title":"ACE inhibitor","match":"ace remmer|ace-remmer|ace-remmers|ace remmers","option_only":true},"irbesartan":{"title":"Irbesartan","short":"Irbesartan is een angiotensine II-receptorblokker (ARB) bij hypertensie en diabetische nierziekte.","definition":"<p><strong>Irbesartan</strong> blokkeert de AT1-receptor voor angiotensine II en verlaagt zo de bloeddruk en de aldosteronafgifte. Het wordt gebruikt bij hypertensie en vertraagt de achteruitgang bij diabetische nefropathie. Bijwerkingen en contra-indicaties zijn vergelijkbaar met die van andere ARB's.</p>","image_url":"","wiki_title":"Irbesartan","match":"irbesartan","option_only":true},"nifedipine":{"title":"Nifedipine","short":"Nifedipine is een dihydropyridine-calciumantagonist die vooral de bloedvaten verwijdt.","definition":"<p><strong>Nifedipine</strong> blokkeert L-type calciumkanalen in vasculaire gladde spier, wat arteriële vaatverwijding geeft. Het heeft weinig effect op het hart. Het wordt gebruikt bij hypertensie, angina pectoris, het fenomeen van Raynaud en als weeënremmer. Bijwerkingen: enkeloedeem, hoofdpijn, flushing en reflextachycardie.</p>","image_url":"","wiki_title":"Nifedipine","match":"nifedipine","option_only":true},"verapamil":{"title":"Verapamil","short":"Verapamil is een calciumantagonist die vooral op het hart werkt: het remt de AV-geleiding en verlaagt de hartfrequentie.","definition":"<p><strong>Verapamil</strong> (een fenylalkylamine) blokkeert L-type calciumkanalen in hart en vaten. Het vertraagt de geleiding in de AV-knoop en vermindert de contractiekracht. Indicaties: supraventriculaire tachycardieën, frequentiecontrole bij boezemfibrilleren, angina pectoris en hypertensie. Niet combineren met bètablokkers (risico op bradycardie en AV-blok); obstipatie is een bekende bijwerking.</p>","image_url":"","wiki_title":"Verapamil","match":"verapamil","option_only":true},"doxazosine":{"title":"Doxazosine","short":"Doxazosine is een α1-blokker die vaten en de gladde spier van blaashals en prostaat ontspant.","definition":"<p><strong>Doxazosine</strong> blokkeert α1-adrenerge receptoren, waardoor arteriolen verwijden en de bloeddruk daalt. Ook ontspant het de gladde spier in de prostaat en blaashals, wat de plasstraal verbetert bij benigne prostaathyperplasie. Bekende bijwerking is orthostatische hypotensie, vooral bij de eerste dosis.</p>","image_url":"","wiki_title":"Doxazosin","match":"doxazosine","option_only":true},"simvastatine":{"title":"Simvastatine","short":"Simvastatine is een statine: een HMG-CoA-reductaseremmer die het LDL-cholesterol verlaagt.","definition":"<p><strong>Simvastatine</strong> remt HMG-CoA-reductase, het snelheidsbepalende enzym van de cholesterolsynthese in de lever. De lever maakt daardoor meer LDL-receptoren aan en haalt meer LDL uit het bloed. Statines verlagen het risico op hart- en vaatziekten. Bijwerkingen: spierklachten (zelden rabdomyolyse) en leverenzymstijging; simvastatine heeft veel interacties via CYP3A4.</p>","image_url":"","wiki_title":"Simvastatin","match":"simvastatine|statine|statines","option_only":true},"clopidogrel":{"title":"Clopidogrel","short":"Clopidogrel is een plaatjesremmer die de ADP-receptor P2Y12 op bloedplaatjes onomkeerbaar blokkeert.","definition":"<p><strong>Clopidogrel</strong> is een prodrug die via CYP2C19 in de lever wordt geactiveerd. De actieve metaboliet blokkeert de P2Y12-receptor, zodat ADP de plaatjes niet meer kan activeren. Het wordt gebruikt na een acuut coronair syndroom en stentplaatsing (vaak samen met acetylsalicylzuur) en bij herseninfarct en perifeer vaatlijden. Bijwerking: bloedingen.</p>","image_url":"","wiki_title":"Clopidogrel","match":"clopidogrel","option_only":true},"fenprocoumon":{"title":"Fenprocoumon","short":"Fenprocoumon is een langwerkende cumarine (vitamine K-antagonist) voor antistolling; de dosering wordt gestuurd op de INR.","definition":"<p><strong>Fenprocoumon</strong> remt het enzym vitamine K-epoxidereductase, waardoor de lever minder functionele factoren II, VII, IX en X maakt. Het werkt traag en heeft een lange halfwaardetijd. De dosering wordt via de trombosedienst op geleide van de INR ingesteld. Er zijn veel interacties met voeding en geneesmiddelen; antidotum is vitamine K (en bij ernstige bloeding stollingsfactorconcentraat).</p>","image_url":"","wiki_title":"Phenprocoumon","match":"fenprocoumon|marcoumar","option_only":true},"acenocoumarol":{"title":"Acenocoumarol","short":"Acenocoumarol is een kortwerkende cumarine (vitamine K-antagonist) voor antistolling, gedoseerd op geleide van de INR.","definition":"<p><strong>Acenocoumarol</strong> werkt net als fenprocoumon door remming van de vitamine K-cyclus, maar heeft een kortere halfwaardetijd. Het wordt gebruikt bij o.a. boezemfibrilleren, trombose en kunstkleppen. Controle via de INR is nodig; veel geneesmiddelen (zoals antibiotica) en wisselende vitamine K-inname beïnvloeden het effect.</p>","image_url":"","wiki_title":"Acenocoumarol","match":"acenocoumarol|sintrom","option_only":true},"neuropathie":{"title":"Neuropathie","short":"Neuropathie is een aandoening van perifere zenuwen, met gevoelsstoornissen, krachtsverlies en/of verlaagde reflexen.","definition":"<p>Een <strong>neuropathie</strong> kan één zenuw treffen (mononeuropathie, bijv. carpaletunnelsyndroom), meerdere zenuwen asymmetrisch (mononeuritis multiplex) of symmetrisch veel zenuwen tegelijk (polyneuropathie, typisch beginnend in de voeten). Oorzaken zijn o.a. diabetes, alcohol, vitamine B12-tekort, medicatie (chemotherapie), auto-immuniteit en erfelijke aandoeningen.</p>","image_url":"","wiki_title":"Peripheral neuropathy","match":"neuropathie|perifere neuropathie","option_only":true},"herseninfarct":{"title":"Herseninfarct","short":"Een herseninfarct ontstaat door afsluiting van een hersenarterie, waardoor hersenweefsel afsterft; het geeft plotselinge focale uitval.","definition":"<p>Een <strong>herseninfarct</strong> wordt veroorzaakt door trombose (bijv. bij atherosclerose of kleine-vatenziekte) of embolie (vaak uit het hart bij boezemfibrilleren of uit de carotis). Klachten ontstaan plotseling, afhankelijk van het vaatgebied: halfzijdige verlamming, gevoelsstoornis, afasie, gezichtsvelduitval. Acute behandeling binnen het tijdvenster: intraveneuze trombolyse en/of trombectomie.</p>","image_url":"","wiki_title":"Ischemic stroke","match":"herseninfarct|ischemisch cva|stroke (herseninfarct)|ischemisch herseninfarct","option_only":true},"longembolie":{"title":"Longembolie","short":"Bij een longembolie sluit een stolsel (meestal uit de beenvenen) een longslagader af, met acute benauwdheid en pijn bij het ademen.","definition":"<p>Een <strong>longembolie</strong> ontstaat meestal door een trombus uit de diepe venen van been of bekken. Risicofactoren volgen de trias van Virchow: stase (immobilisatie), hypercoagulabiliteit (kanker, oestrogenen, zwangerschap, erfelijke trombofilie) en vaatwandschade (operatie, trauma). Klachten: plotselinge dyspneu, pleuritische pijn, tachycardie, soms hemoptoë of collaps. Diagnostiek met een beslisregel, D-dimeer en CT-angiografie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Pulmonary embolism","match":"longembolie|pulmonale embolie|longembolieën","option_only":true},"pulmonale hypertensie":{"title":"Pulmonale hypertensie","short":"Pulmonale hypertensie is een verhoogde druk in de longslagaders, die op termijn rechtszijdig hartfalen veroorzaakt.","definition":"<p>Bij <strong>pulmonale hypertensie</strong> is de gemiddelde druk in de a. pulmonalis verhoogd (&gt;20 mmHg in rust bij hartkatheterisatie). Oorzaken: linkszijdige hartziekte (meest voorkomend), longziekten met hypoxie, chronische longembolieën, en zeldzamer pulmonale arteriële hypertensie. Klachten zijn kortademigheid en vermoeidheid bij inspanning; later ontstaan oedeem en tekenen van rechtsfalen.</p>","image_url":"","wiki_title":"Pulmonary hypertension","match":"pulmonale hypertensie","option_only":true},"longcarcinoom":{"title":"Longcarcinoom","short":"Longkanker is een kwaadaardige tumor uitgaande van het epitheel van de luchtwegen; roken is de belangrijkste oorzaak.","definition":"<p>Het <strong>longcarcinoom</strong> wordt ingedeeld in niet-kleincellig (o.a. adenocarcinoom en plaveiselcelcarcinoom) en kleincellig longcarcinoom. Klachten zijn o.a. aanhoudende hoest, hemoptoë, kortademigheid, gewichtsverlies en recidiverende pneumonieën; vaak wordt het pas laat ontdekt. Paraneoplastische syndromen (zoals SIADH, hypercalciëmie, Lambert-Eaton) komen voor.</p>","image_url":"","wiki_title":"Lung cancer","match":"longcarcinoom|longkanker|bronchuscarcinoom","option_only":true},"paroxysmaal atriumfibrilleren":{"title":"Paroxysmaal atriumfibrilleren","short":"Bij paroxysmaal atriumfibrilleren treden aanvallen van boezemfibrilleren op die binnen 7 dagen vanzelf stoppen.","definition":"<p>Bij <strong>atriumfibrilleren</strong> is de elektrische activiteit van de boezems chaotisch; de kamers slaan onregelmatig en vaak snel. In de paroxysmale vorm duren episodes korter dan een week en eindigen ze spontaan. Er is een verhoogd risico op trombo-embolie (vooral herseninfarct) vanuit het linkerhartoor; afhankelijk van de CHA₂DS₂-VASc-score wordt antistolling gegeven.</p>","image_url":"","wiki_title":"Atrial fibrillation","match":"paroxysmaal atriumfibrilleren|paroxysmaal boezemfibrilleren|atriumfibrilleren|boezemfibrilleren","option_only":true},"aortaklepstenose":{"title":"Aortaklepstenose","short":"Bij aortaklepstenose opent de aortaklep onvoldoende, waardoor de linkerventrikel tegen verhoogde weerstand moet pompen.","definition":"<p><strong>Aortaklepstenose</strong> ontstaat meestal door degeneratieve verkalking op oudere leeftijd of bij een aangeboren bicuspide klep. De linkerventrikel hypertrofieert. Bij auscultatie is er een systolisch ejectiegeruis aan de basis, vaak uitstralend naar de carotiden. Klachten (angina, syncope bij inspanning, hartfalen) wijzen op een ernstige stenose; behandeling is klepvervanging (chirurgisch of TAVI).</p>","image_url":"","wiki_title":"Aortic stenosis","match":"aortaklepstenose|aortastenose","option_only":true},"ventrikelseptum defect":{"title":"Ventrikelseptumdefect (VSD)","short":"Een VSD is een aangeboren opening in het septum tussen de linker- en rechterventrikel, met een links-rechtsshunt.","definition":"<p>Bij een <strong>ventrikelseptumdefect</strong> stroomt bloed in de systole van links naar rechts, wat een luid holosystolisch geruis links parasternaal geeft. Kleine (vaak musculaire) defecten sluiten vaak spontaan. Grote defecten geven volumebelasting van de longcirculatie en hartfalen op jonge leeftijd; zonder sluiting kan pulmonale hypertensie (Eisenmenger) ontstaan.</p>","image_url":"","wiki_title":"Ventricular septal defect","match":"ventrikelseptum defect|ventrikelseptumdefect|vsd","option_only":true},"open foramen ovale":{"title":"Open foramen ovale (PFO)","short":"Een open foramen ovale is een niet volledig gesloten verbinding tussen de boezems, een restant van de foetale circulatie.","definition":"<p>Het <strong>foramen ovale</strong> laat in de foetale circulatie bloed van het rechter- naar het linkeratrium stromen. Na de geboorte stijgt de druk links en sluit het functioneel; bij ongeveer een kwart van de volwassenen blijft het anatomisch open. Meestal geeft dat geen klachten, maar het kan een paradoxale embolie (veneuze stolsel naar de systeemcirculatie) mogelijk maken.</p>","image_url":"","wiki_title":"Patent foramen ovale","match":"open foramen ovale|patent foramen ovale|pfo","option_only":true},"hypotensie":{"title":"Hypotensie","short":"Hypotensie is een lage bloeddruk; klinisch relevant als ze leidt tot klachten of onvoldoende doorbloeding van organen.","definition":"<p><strong>Hypotensie</strong> kan constitutioneel en onschuldig zijn. Pathologische hypotensie ontstaat bij ondervulling (bloedverlies, dehydratie), vaatverwijding (sepsis, anafylaxie, medicatie), verminderde pompfunctie (cardiogeen) of obstructie (tamponnade, longembolie). Orthostatische hypotensie treedt op bij opstaan. Een daling van de doorbloeding geeft duizeligheid, verwardheid, oligurie en uiteindelijk shock.</p>","image_url":"","wiki_title":"Hypotension","match":"hypotensie|lage bloeddruk","option_only":true},"orthostatische hypotensie":{"title":"Orthostatische hypotensie","short":"Orthostatische hypotensie is een bloeddrukdaling bij het opstaan door onvoldoende compensatie van het autonome zenuwstelsel.","definition":"<p>Bij <strong>orthostatische hypotensie</strong> daalt de systolische bloeddruk met ≥20 mmHg (of de diastolische met ≥10 mmHg) binnen 3 minuten na overeind komen. Normaal zorgt de baroreflex voor vasoconstrictie en een hogere hartfrequentie. Oorzaken zijn o.a. ondervulling, medicatie (antihypertensiva, diuretica, antidepressiva) en autonome neuropathie. Klachten: duizeligheid, wazig zien en wegraking bij opstaan.</p>","image_url":"","wiki_title":"Orthostatic hypotension","match":"orthostatische hypotensie","option_only":true},"pericarditis":{"title":"Pericarditis","short":"Pericarditis is een ontsteking van het hartzakje, met scherpe, houdingsafhankelijke pijn op de borst.","definition":"<p><strong>Pericarditis</strong> wordt meestal veroorzaakt door een virus, maar ook door bacteriën, auto-immuunziekten, nierfalen, tumoren of na een hartinfarct of hartoperatie. Typisch zijn scherpe pijn die verergert bij plat liggen en diep inademen, een pericardwrijven en diffuse ST-elevatie op het ECG. Bij veel vocht in het hartzakje kan een harttamponnade ontstaan.</p>","image_url":"","wiki_title":"Pericarditis","match":"pericarditis|hartzakontsteking","option_only":true},"sepsis":{"title":"Sepsis","short":"Sepsis is een levensbedreigende orgaandisfunctie door een ontregelde afweerreactie op een infectie.","definition":"<p>Bij <strong>sepsis</strong> leidt de reactie van het lichaam op een infectie tot schade aan de eigen organen: hypotensie, verwardheid, snelle ademhaling, nierfalen, stollingsstoornissen en een verhoogd lactaat. Septische shock is sepsis met hypotensie die vasopressoren vereist. Snelle herkenning (bijv. qSOFA), bloedkweken, antibiotica binnen een uur en vochtresuscitatie zijn essentieel.</p>","image_url":"","wiki_title":"Sepsis","match":"sepsis|bloedvergiftiging","option_only":true},"acute postinfectieuze glomerulonefritis":{"title":"Acute postinfectieuze glomerulonefritis","short":"Een glomerulonefritis die 1–3 weken na een (streptokokken)infectie ontstaat, door neerslag van immuuncomplexen in de glomeruli.","definition":"<p>Bij <strong>acute postinfectieuze glomerulonefritis</strong> ontstaat vooral bij kinderen, enkele weken na een keel- of huidinfectie met groep A-streptokokken, een nefritisch beeld: colakleurige urine, oedeem rond de ogen en hypertensie. Het complement (C3) is verlaagd. Het nierbiopt toont subepitheliale ‘humps’. Bij kinderen herstelt het meestal volledig.</p>","image_url":"","wiki_title":"Poststreptococcal glomerulonephritis","match":"acute postinfectieuze glomerulonefritis|poststreptokokken glomerulonefritis|poststreptokokkenglomerulonefritis","option_only":true},"nierinsufficiëntie":{"title":"Nierinsufficiëntie (nierfalen)","short":"Bij nierinsufficiëntie schiet de nierfunctie tekort, met ophoping van afvalstoffen en verstoring van water-, zout- en zuurhuishouding.","definition":"<p><strong>Acuut nierfalen</strong> ontstaat binnen uren tot dagen en wordt ingedeeld in prerenaal (ondervulling), renaal (bijv. acute tubulusnecrose, glomerulonefritis) en postrenaal (obstructie). <strong>Chronische nierschade</strong> is een eGFR &lt; 60 of nierschade langer dan 3 maanden, meestal door diabetes en hypertensie. Gevolgen zijn o.a. hyperkaliëmie, metabole acidose, anemie (minder EPO), botziekte en hypertensie.</p>","image_url":"","wiki_title":"Kidney failure","match":"nierinsufficiëntie|nierfalen|nierinsufficientie|chronische nierschade","option_only":true},"proteïnurie":{"title":"Proteïnurie","short":"Proteïnurie is verhoogd eiwitverlies in de urine, een teken van nierschade.","definition":"<p>Normaal laat de glomerulaire filter nauwelijks eiwit door, en wordt het kleine beetje gefilterd eiwit in de proximale tubulus teruggeresorbeerd. <strong>Proteïnurie</strong> ontstaat bij glomerulaire schade (bijv. diabetes, glomerulonefritis), tubulaire schade of overloop (bijv. lichte ketens bij myeloom). Bij &gt;3,5 g/dag spreekt men van nefrotische proteïnurie. Albuminurie is een vroege marker van diabetische nefropathie en vaatschade.</p>","image_url":"","wiki_title":"Proteinuria","match":"proteïnurie|eiwituitscheiding|albuminurie","option_only":true},"hypernatriëmie":{"title":"Hypernatriëmie","short":"Hypernatriëmie is een te hoog natrium in het bloed, meestal door een tekort aan water ten opzichte van zout.","definition":"<p><strong>Hypernatriëmie</strong> (&gt;145 mmol/L) ontstaat vooral als iemand onvoldoende kan drinken (ouderen, zuigelingen, verminderd bewustzijn) of water verliest via koorts, diarree of diabetes insipidus. Cellen in het brein krimpen, met sufheid, verwardheid en insulten. Correctie moet langzaam om hersenoedeem te voorkomen.</p>","image_url":"","wiki_title":"Hypernatremia","match":"hypernatriëmie|hypernatriemie","option_only":true},"hypoglycemie":{"title":"Hypoglykemie","short":"Hypoglykemie is een te lage bloedglucose, met klachten zoals trillen, zweten, honger en bij ernstige vormen verwardheid en bewustzijnsverlies.","definition":"<p>Een <strong>hypoglykemie</strong> (meestal &lt;4 mmol/L bij diabetes) komt vooral voor bij gebruik van insuline of sulfonylureumderivaten, bij te weinig eten, inspanning of alcohol. Eerst ontstaan adrenerge klachten (trillen, zweten, hartkloppingen, honger), daarna neuroglycopene klachten (verwardheid, gedragsverandering, insulten, coma). Behandeling: snelle suikers of glucose intraveneus, of glucagon.</p>","image_url":"","wiki_title":"Hypoglycemia","match":"hypoglycemie|hypoglykemie","option_only":true},"hyperthyreoïdie":{"title":"Hyperthyreoïdie","short":"Hyperthyreoïdie is een te snelle schildklierwerking, met hartkloppingen, gewichtsverlies, warmte-intolerantie en onrust.","definition":"<p><strong>Hyperthyreoïdie</strong> wordt o.a. veroorzaakt door de ziekte van Graves, een toxisch multinodulair struma, een toxisch adenoom of een (tijdelijke) thyreoïditis. Klachten: hartkloppingen of boezemfibrilleren, gewichtsverlies ondanks goede eetlust, zweten, tremor, onrust, slecht slapen en diarree. Diagnose: laag TSH met verhoogd vrij T4.</p>","image_url":"","wiki_title":"Hyperthyroidism","match":"hyperthyreoïdie|hyperthyreoidie|hyperthyreoïdie|overactieve schildklier","option_only":true},"familiaire hypertriglyceridemie":{"title":"Familiaire hypertriglyceridemie","short":"Familiaire hypertriglyceridemie is een erfelijke stoornis met een verhoogde VLDL-productie en hoge triglyceriden.","definition":"<p>Bij <strong>familiaire hypertriglyceridemie</strong> maakt de lever te veel triglyceriderijke VLDL. Het LDL-cholesterol is meestal niet verhoogd. Overgewicht, alcohol en diabetes verergeren de afwijking. Bij zeer hoge waarden ontstaat risico op acute pancreatitis.</p>","image_url":"","wiki_title":"Hypertriglyceridemia","match":"familiaire hypertriglyceridemie","option_only":true},"familiaire gecombineerde hyperlipidemie":{"title":"Familiaire gecombineerde hyperlipidemie","short":"Bij familiaire gecombineerde hyperlipidemie zijn zowel LDL-cholesterol als triglyceriden verhoogd, met een wisselend patroon binnen families.","definition":"<p><strong>Familiaire gecombineerde hyperlipidemie</strong> is de meest voorkomende erfelijke vetstofwisselingsstoornis. De lever maakt te veel apoB-bevattende lipoproteïnen. Familieleden kunnen verschillende patronen hebben (hoog cholesterol, hoge triglyceriden of beide). Het risico op vroegtijdige hart- en vaatziekten is verhoogd.</p>","image_url":"","wiki_title":"Familial combined hyperlipidemia","match":"familiaire gecombineerde hyperlipidemie|fch","option_only":true},"chylomicronemie":{"title":"Chylomicronemie","short":"Chylomicronemie is ophoping van chylomicronen in het nuchtere bloed, met zeer hoge triglyceriden en risico op pancreatitis.","definition":"<p>Normaal worden <strong>chylomicronen</strong> (die vetten uit de darm vervoeren) binnen uren afgebroken door lipoproteïnelipase. Bij een erfelijk tekort aan dit enzym of zijn cofactor apoC-II, of bij een combinatie van aanleg en secundaire factoren, blijven ze aanwezig. Het plasma ziet er melkachtig uit. Klachten zijn recidiverende pancreatitis, eruptieve xanthomen en lipaemia retinalis.</p>","image_url":"","wiki_title":"Chylomicronemia","match":"chylomicronemie|chylomicronemiesyndroom","option_only":true},"leukocytose":{"title":"Leukocytose","short":"Leukocytose is een verhoogd aantal witte bloedcellen, meestal door infectie of ontsteking.","definition":"<p>Bij <strong>leukocytose</strong> is het aantal leukocyten boven ongeveer 10 × 10⁹/L. Een neutrofiele leukocytose met linksverschuiving past bij bacteriële infectie; ook stress, corticosteroïden, roken, trauma en necrose kunnen het verhogen. Sterk verhoogde waarden met onrijpe cellen in het bloed wijzen op leukemie of een leukemoïde reactie.</p>","image_url":"","wiki_title":"Leukocytosis","match":"leukocytose","option_only":true},"trombopenie":{"title":"Trombocytopenie","short":"Trombocytopenie is een te laag aantal bloedplaatjes, met een verhoogde neiging tot bloedingen.","definition":"<p>Bij <strong>trombocytopenie</strong> (&lt;150 × 10⁹/L) ontstaan pas bij lage waarden (&lt;20–50) spontane huid- en slijmvliesbloedingen zoals petechiën en neusbloedingen. Oorzaken: verminderde aanmaak (beenmergziekte, chemotherapie, B12-tekort), versterkte afbraak (ITP, HIT, DIS, TTP), sequestratie in een vergrote milt of verdunning. Een pseudotrombopenie door klontering in EDTA-buizen moet worden uitgesloten.</p>","image_url":"","wiki_title":"Thrombocytopenia","match":"trombopenie|trombocytopenie","option_only":true},"autoimmuuntrombocytopenie (aitp)":{"title":"Immuuntrombocytopenie (ITP)","short":"Bij ITP breken auto-antistoffen tegen bloedplaatjes deze af, met een geïsoleerde trombocytopenie.","definition":"<p>Bij <strong>immuuntrombocytopenie</strong> worden plaatjes met antistoffen beladen en in de milt afgebroken; ook de aanmaak wordt geremd. Bij kinderen volgt het vaak op een virale infectie en herstelt het meestal spontaan; bij volwassenen is het vaker chronisch. Het is een diagnose na uitsluiting van andere oorzaken. Behandeling bij bloedingen of zeer lage waarden: corticosteroïden, immunoglobulinen, TPO-agonisten.</p>","image_url":"","wiki_title":"Immune thrombocytopenic purpura","match":"autoimmuuntrombocytopenie (aitp)|itp|aitp|immuuntrombocytopenie|idiopathische trombocytopenische purpura","option_only":true},"heparine-geïnduceerde trombopenie (hit)":{"title":"Heparine-geïnduceerde trombocytopenie (HIT)","short":"HIT is een immuunreactie op heparine waarbij antistoffen bloedplaatjes activeren, met trombocytopenie en juist trombose.","definition":"<p>Bij <strong>HIT</strong> vormen antistoffen complexen met heparine en plaatjesfactor 4. Deze activeren bloedplaatjes, waardoor het plaatjesgetal daalt (meestal 5–10 dagen na start) en er paradoxaal veneuze en arteriële trombose ontstaat. Heparine moet direct worden gestopt en vervangen door een niet-heparine antistollingsmiddel.</p>","image_url":"","wiki_title":"Heparin-induced thrombocytopenia","match":"heparine-geïnduceerde trombopenie (hit)|heparine-geïnduceerde trombocytopenie","option_only":true},"ijzergebreksanemie":{"title":"IJzergebreksanemie","short":"IJzergebreksanemie is bloedarmoede door een tekort aan ijzer, met kleine, bleke rode bloedcellen.","definition":"<p><strong>IJzergebreksanemie</strong> geeft een microcytaire, hypochrome anemie met een laag ferritine. Oorzaken zijn bloedverlies (menstruatie, maag-darmkanaal), te weinig inname, verhoogde behoefte (groei, zwangerschap) of verminderde opname (coeliakie, maagresectie). Bij mannen en vrouwen na de menopauze moet een bron van bloedverlies in de tractus digestivus worden uitgesloten.</p>","image_url":"","wiki_title":"Iron-deficiency anemia","match":"ijzergebreksanemie|ijzergebrek","option_only":true},"factor v leiden mutatie":{"title":"Factor V Leiden","short":"Factor V Leiden is een erfelijke mutatie waardoor factor V ongevoelig is voor afbraak door geactiveerd proteïne C, met een verhoogd tromboserisico.","definition":"<p>Bij <strong>factor V Leiden</strong> (een puntmutatie in het F5-gen) kan geactiveerd proteïne C factor Va niet goed inactiveren (APC-resistentie). Het is de meest voorkomende erfelijke trombofilie bij mensen van Europese afkomst. Het verhoogt het risico op veneuze trombose, vooral in combinatie met orale anticonceptie, zwangerschap of immobilisatie.</p>","image_url":"","wiki_title":"Factor V Leiden","match":"factor v leiden mutatie|factor v leiden|fvl","option_only":true},"lupus anticoagulans":{"title":"Lupus anticoagulans","short":"Lupus anticoagulans is een antifosfolipide-antistof die in het lab de stolling verlengt, maar in het lichaam juist trombose bevordert.","definition":"<p><strong>Lupus anticoagulans</strong> wordt aangetoond met stollingstests (bijv. een verlengde APTT die niet corrigeert bij menging). Samen met anti-cardiolipine en anti-β2-glycoproteïne I vormt het de basis van het antifosfolipidensyndroom: veneuze en arteriële trombose en zwangerschapscomplicaties (herhaalde miskramen). Het komt voor met of zonder SLE.</p>","image_url":"","wiki_title":"Lupus anticoagulant","match":"lupus anticoagulans","option_only":true},"hemofilie c":{"title":"Hemofilie C (factor XI-deficiëntie)","short":"Hemofilie C is een erfelijk tekort aan stollingsfactor XI, met meestal milde bloedingsneiging na operaties of trauma.","definition":"<p><strong>Factor XI-deficiëntie</strong> erft autosomaal (recessief) over en treft daardoor mannen en vrouwen; het komt relatief vaak voor bij Asjkenazische joden. De APTT is verlengd. Spontane bloedingen zijn zeldzaam; vooral na ingrepen in weefsels met veel fibrinolyse (mond, neus, urinewegen) kan nabloeding optreden.</p>","image_url":"","wiki_title":"Factor XI deficiency","match":"hemofilie c|factor xi-deficiëntie|factor xi deficiëntie","option_only":true},"factor xiii deficiëntie":{"title":"Factor XIII-deficiëntie","short":"Bij factor XIII-deficiëntie wordt het fibrinestolsel niet goed verknoopt, met nabloedingen terwijl PT en APTT normaal zijn.","definition":"<p><strong>Factor XIII</strong> verknoopt fibrinemonomeren tot een stabiel stolsel. Bij een (zeldzaam, autosomaal recessief) tekort zijn de standaard stollingstests normaal, maar ontstaan nabloedingen, bloedingen uit de navelstreng bij pasgeborenen, slechte wondgenezing en hersenbloedingen. Diagnose met een specifieke factor XIII-bepaling.</p>","image_url":"","wiki_title":"Factor XIII deficiency","match":"factor xiii deficiëntie|factor xiii-deficiëntie","option_only":true},"de ziekte van glanzmann":{"title":"Trombasthenie van Glanzmann","short":"Bij de ziekte van Glanzmann ontbreekt de GPIIb/IIIa-receptor op bloedplaatjes, waardoor ze niet aan elkaar kunnen binden.","definition":"<p>De <strong>trombasthenie van Glanzmann</strong> is een zeldzame, autosomaal recessieve plaatjesfunctiestoornis. Zonder functioneel GPIIb/IIIa kunnen plaatjes geen fibrinogeenbruggen vormen en dus niet aggregeren. Het plaatjesgetal is normaal, maar er zijn slijmvliesbloedingen en een verlengde bloedingstijd. Dezelfde receptor is het doelwit van GPIIb/IIIa-remmers.</p>","image_url":"","wiki_title":"Glanzmann's thrombasthenia","match":"de ziekte van glanzmann|ziekte van glanzmann|trombasthenie van glanzmann","option_only":true},"reumatoïde artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoïde artritis|reumatoide artritis|reumatoïde arthritis","option_only":true},"polymyalgia reumatica":{"title":"Polymyalgia reumatica","short":"Polymyalgia reumatica is een ontstekingsziekte bij ouderen met pijn en stijfheid in schouder- en heupgordel.","definition":"<p><strong>Polymyalgia reumatica</strong> treft vooral mensen boven de 50, vaker vrouwen. Kenmerkend zijn ochtendstijfheid en pijn in nek, schouders en heupen, met moeite om op te staan of de armen te heffen, en een sterk verhoogde BSE/CRP. Er is geen echte spierzwakte. De ziekte reageert snel op lage dosis prednison en gaat soms samen met reuscelarteriitis.</p>","image_url":"","wiki_title":"Polymyalgia rheumatica","match":"polymyalgia reumatica|polymyalgia rheumatica|pmr","option_only":true},"arteritis temporalis":{"title":"Arteriitis temporalis (reuscelarteriitis)","short":"Arteriitis temporalis is een granulomateuze vasculitis van grote en middelgrote arteriën bij ouderen, met risico op blindheid.","definition":"<p>Bij <strong>reuscelarteriitis</strong> zijn vooral takken van de a. carotis externa (zoals de a. temporalis) en soms de aorta en haar takken ontstoken. Klachten: nieuwe hoofdpijn, gevoelige slaapslagader, kauwclaudicatie, visusstoornissen en algemene malaise, met een sterk verhoogde BSE/CRP. Bij verdenking direct hoge dosis prednison om blindheid te voorkomen; diagnose met echo of biopt.</p>","image_url":"","wiki_title":"Giant cell arteritis","match":"arteritis temporalis|arteriitis temporalis|reuscelarteriitis|giant cell arteritis","option_only":true},"pariarteriitis nodosa":{"title":"Polyarteriitis nodosa","short":"Polyarteriitis nodosa is een necrotiserende vasculitis van middelgrote arteriën, zonder ANCA en zonder glomerulonefritis.","definition":"<p>Bij <strong>polyarteriitis nodosa</strong> raken middelgrote spierarteriën ontstoken, met microaneurysmata en infarcten in o.a. nieren (hypertensie), darm (buikpijn), huid (livedo, ulcera) en zenuwen (mononeuritis multiplex). Een deel van de gevallen hangt samen met hepatitis B. De longen zijn meestal niet aangedaan.</p>","image_url":"","wiki_title":"Polyarteritis nodosa","match":"pariarteriitis nodosa|polyarteriitis nodosa|periarteriitis nodosa","option_only":true},"anti-ss-a":{"title":"Anti-SSA (Ro)","short":"Anti-SSA (Ro) is een antinucleaire antistof die voorkomt bij het syndroom van Sjögren, SLE en subacute cutane lupus.","definition":"<p><strong>Anti-SSA/Ro</strong>-antistoffen zijn IgG en kunnen de placenta passeren. Bij zwangeren met deze antistoffen kan het kind een neonatale lupus krijgen, met huiduitslag en, belangrijk, een aangeboren volledig hartblok. Ze komen vaak samen voor met anti-SSB/La.</p>","image_url":"","wiki_title":"Anti-SSA/Ro autoantibodies","match":"anti-ss-a|anti-ssa|anti-ro","option_only":true},"anti-ss-b":{"title":"Anti-SSB (La)","short":"Anti-SSB (La) is een antinucleaire antistof die vooral voorkomt bij het syndroom van Sjögren en soms bij SLE.","definition":"<p><strong>Anti-SSB/La</strong>-antistoffen komen bijna altijd samen met anti-SSA voor. Ze zijn kenmerkend voor het syndroom van Sjögren, een auto-immuunziekte van de traan- en speekselklieren met droge ogen en droge mond. Ook zij kunnen bijdragen aan neonatale lupus.</p>","image_url":"","wiki_title":"Anti-SSB/La autoantibodies","match":"anti-ss-b|anti-ssb|anti-la","option_only":true},"methotrexaat":{"title":"Methotrexaat","short":"Methotrexaat is een foliumzuurantagonist; in lage dosis een basismiddel bij reumatoïde artritis en psoriasis, in hoge dosis een cytostaticum.","definition":"<p><strong>Methotrexaat</strong> remt dihydrofolaatreductase. In lage, wekelijkse dosering werkt het ontstekingsremmend (o.a. via adenosine) en is het een hoeksteen bij reumatoïde artritis, psoriasis en IBD; foliumzuur vermindert bijwerkingen. Bijwerkingen: beenmergsuppressie, levertoxiciteit, mucositis en pneumonitis. Het is teratogeen en wordt via de nier uitgescheiden.</p>","image_url":"","wiki_title":"Methotrexate","match":"methotrexaat|mtx|methotrexate","option_only":true},"nsaids":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"nsaids|nsaid|nsaid's|antiflogistica|ontstekingsremmers","option_only":true},"blindheid":{"title":"Blindheid","short":"Blindheid is ernstig verlies van het gezichtsvermogen.","definition":"<p>Wereldwijd zijn de belangrijkste oorzaken van <strong>blindheid</strong> cataract, onbehandelde refractieafwijkingen, glaucoom, maculadegeneratie en diabetische retinopathie; in ontwikkelingslanden ook trachoom en vitamine A-tekort. Een groot deel ervan is te voorkomen of te behandelen.</p>","image_url":"","wiki_title":"Blindness","match":"blindheid","option_only":true},"versterken en steunen":{"title":"Versterken en steunen","short":"Gesprekstechniek waarbij de arts de patiënt aanmoedigt en waardering uitspreekt voor wat goed gaat of wat de patiënt al doet.","definition":"<p>Bij <strong>versterken en steunen</strong> benoemt de arts de sterke kanten, inspanningen en eigen oplossingen van de patiënt (‘Knap dat u al zo lang volhoudt’). Dat vergroot het zelfvertrouwen en de motivatie. Het wordt o.a. gebruikt in motiverende gespreksvoering en bij het slechtnieuwsgesprek.</p>","image_url":"","wiki_title":"","match":"versterken en steunen","option_only":true},"erkennen en accepteren":{"title":"Erkennen en accepteren","short":"Gesprekstechniek waarbij de arts de beleving en emoties van de patiënt serieus neemt en laat merken dat die er mogen zijn.","definition":"<p>Bij <strong>erkennen</strong> laat de arts merken dat de gevoelens, zorgen of het standpunt van de patiënt begrijpelijk zijn, zonder het daarmee inhoudelijk eens te hoeven zijn. Dat voorkomt dat de patiënt zich onbegrepen voelt en zich gaat verdedigen. Het is een basisvaardigheid bij emoties, weerstand en slecht nieuws.</p>","image_url":"","wiki_title":"","match":"erkennen en accepteren|erkennen","option_only":true},"hier en nu":{"title":"Hier en nu (gesprekstechniek)","short":"Gesprekstechniek waarbij de arts benoemt wat er op dit moment in het gesprek gebeurt, om een vastgelopen gesprek weer op gang te brengen.","definition":"<p>Met een <strong>hier-en-nu</strong>-opmerking stapt de arts even uit de inhoud en bespreekt hij of zij het proces: ‘Ik merk dat we steeds over hetzelfde praten, hoe ervaart u dit gesprek?’ Dit heet ook metacommunicatie. Het helpt bij weerstand, irritatie of wanneer arts en patiënt langs elkaar heen praten.</p>","image_url":"","wiki_title":"","match":"hier en nu|hier-en-nu","option_only":true},"stiltes":{"title":"Stiltes (gesprekstechniek)","short":"Bewust stiltes laten vallen geeft de patiënt ruimte om na te denken, emoties te uiten of meer te vertellen.","definition":"<p>Een korte <strong>stilte</strong> na een vraag of na slecht nieuws laat de patiënt tijd om informatie te verwerken en zelf het woord te nemen. Veel artsen vullen stiltes te snel op. Stiltes zijn een vorm van non-verbaal aanmoedigen, naast knikken en oogcontact.</p>","image_url":"","wiki_title":"","match":"stiltes|stilte laten vallen","option_only":true},"positief her-etiketteren":{"title":"Positief her-etiketteren (reframen)","short":"Bij positief her-etiketteren geeft de arts gedrag of een uitspraak van de patiënt een andere, positievere betekenis.","definition":"<p>Bij <strong>positief her-etiketteren</strong> (reframing) wordt een negatief gelabeld gedrag in een ander licht gezet: ‘U noemt het zeuren, maar ik zie vooral iemand die goed voor zijn moeder wil zorgen.’ Het kan weerstand verminderen en nieuwe mogelijkheden openen.</p>","image_url":"","wiki_title":"","match":"positief her-etiketteren|positief heretiketteren|reframen","option_only":true},"gevoelsreflectie maken":{"title":"Gevoelsreflectie","short":"Bij een gevoelsreflectie benoemt de arts het gevoel dat hij of zij bij de patiënt waarneemt (‘U lijkt er erg van te schrikken’).","definition":"<p>Een <strong>gevoelsreflectie</strong> richt zich niet op de inhoud maar op de emotie achter de woorden of het gedrag van de patiënt. Door het gevoel te benoemen voelt de patiënt zich begrepen en krijgt hij of zij ruimte om erover te praten. Het verschilt van parafraseren, dat de inhoud teruggeeft.</p>","image_url":"","wiki_title":"","match":"gevoelsreflectie maken|een gevoelsreflectie maken|gevoelsreflectie|reflecteren van gevoelens","option_only":true},"personaliseren":{"title":"Personaliseren (gesprekstechniek)","short":"Personaliseren is een explorerende gespreksvaardigheid waarmee de arts het gesprek dichter bij de eigen ervaring van de patiënt brengt.","definition":"<p>Bij <b>personaliseren</b> wordt vaag of afstandelijk taalgebruik van de patiënt concreet en persoonlijk gemaakt, zodat duidelijk wordt wat een klacht voor deze patiënt betekent. Andere explorerende vaardigheden zijn concretiseren, doorvragen en reflecteren.</p>","image_url":"","wiki_title":"","match":"personaliseren","option_only":true},"trombolyse":{"title":"Trombolyse","short":"Trombolyse is het oplossen van een stolsel met een middel dat plasminogeen activeert, zoals alteplase.","definition":"<p>Bij <strong>trombolyse</strong> wordt een plasminogeenactivator (bijv. alteplase, tenecteplase) toegediend, waardoor plasmine ontstaat dat fibrine afbreekt. Het wordt gebruikt bij een acuut herseninfarct (binnen 4,5 uur), soms bij een massale longembolie en (als PCI niet snel kan) bij een STEMI. Het belangrijkste risico is een bloeding, waaronder een hersenbloeding.</p>","image_url":"","wiki_title":"Thrombolysis","match":"trombolyse|trombolytica|alteplase","option_only":true},"citalopram":{"title":"Citalopram","short":"Citalopram is een SSRI (selectieve serotonineheropnameremmer) die wordt gebruikt bij depressie en angststoornissen.","definition":"<p><strong>Citalopram</strong> remt de heropname van serotonine in de presynaptische zenuwcel. Het effect op de stemming begint na enkele weken. Bijwerkingen: misselijkheid, slaapproblemen, seksuele disfunctie, hyponatriëmie (vooral bij ouderen) en een dosisafhankelijke QT-verlenging. Combinatie met andere serotonerge middelen geeft risico op een serotoninesyndroom.</p>","image_url":"","wiki_title":"Citalopram","match":"citalopram|escitalopram","option_only":true},"beta-blokker":{"title":"Bètablokker","short":"Bètablokkers blokkeren bèta-adrenerge receptoren en verlagen hartfrequentie, contractiekracht en reninesecretie.","definition":"<p><strong>Bètablokkers</strong> worden gebruikt bij hypertensie, angina pectoris, na een hartinfarct, bij hartfalen, ritmestoornissen, tremor en migraineprofylaxe. Cardioselectieve middelen (metoprolol, bisoprolol) werken vooral op β1; niet-selectieve (propranolol) ook op β2, wat bronchospasme kan geven. Bijwerkingen: bradycardie, vermoeidheid, koude extremiteiten en het maskeren van hypoglykemieverschijnselen.</p>","image_url":"","wiki_title":"Beta blocker","match":"beta-blokker|bètablokker|betablokker|bètablokkers|beta-blokkers","option_only":true},"lisdiureticum":{"title":"Lisdiureticum","short":"Lisdiuretica remmen de NKCC2-cotransporter in de lis van Henle en zijn de krachtigste plasmiddelen.","definition":"<p><strong>Lisdiuretica</strong> zoals furosemide remmen de Na⁺/K⁺/2Cl⁻-cotransporter in het dikke opstijgende deel van de lis van Henle. Ze worden gebruikt bij oedeem door hartfalen, nierziekte of levercirrose en bij longoedeem. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, metabole alkalose, uitdroging en ototoxiciteit; anders dan thiaziden verhogen ze de calciumuitscheiding.</p>","image_url":"","wiki_title":"Loop diuretic","match":"lisdiureticum|lisdiuretica|furosemide|bumetanide","option_only":true},"syndroom van turner":{"title":"Syndroom van Turner","short":"Het syndroom van Turner (45,X) is een chromosoomafwijking bij meisjes met o.a. kleine lengte en ovariumfalen.","definition":"<p>Bij het <strong>syndroom van Turner</strong> ontbreekt (deels) één X-chromosoom. Kenmerken: kleine lengte, ovariële dysgenesie met uitblijven van de puberteit en onvruchtbaarheid, een brede nek (pterygium colli), lymfoedeem bij de geboorte, een coarctatio aortae of bicuspide aortaklep en nierafwijkingen. De intelligentie is meestal normaal. Behandeling met groeihormoon en oestrogenen.</p>","image_url":"","wiki_title":"Turner syndrome","match":"syndroom van turner|turnersyndroom|45,x","option_only":true},"syndroom van marfan":{"title":"Syndroom van Marfan","short":"Het syndroom van Marfan is een autosomaal dominante bindweefselziekte door mutaties in het fibrilline-1-gen.","definition":"<p>Bij het <strong>syndroom van Marfan</strong> zijn de microfibrillen van elastische vezels afwijkend en is TGF-β-signalering verhoogd. Kenmerken: lange, slanke gestalte met lange ledematen en vingers, hypermobiele gewrichten, borstkasafwijkingen, lensluxatie (meestal naar boven) en verwijding van de aortawortel met risico op dissectie. Behandeling o.a. met bètablokkers of ARB's en tijdige aortachirurgie.</p>","image_url":"","wiki_title":"Marfan syndrome","match":"syndroom van marfan|marfansyndroom|marfan syndroom","option_only":true},"de ziekte van bernard-soulier":{"title":"Syndroom van Bernard-Soulier","short":"Bij het syndroom van Bernard-Soulier ontbreekt de GPIb-receptor op bloedplaatjes, waardoor ze niet aan de von Willebrandfactor hechten.","definition":"<p>Het <strong>Bernard-Souliersyndroom</strong> is een zeldzame, autosomaal recessieve plaatjesfunctiestoornis. Zonder GPIb-IX-V kunnen plaatjes niet hechten aan vWF op het beschadigde subendotheel. Kenmerkend zijn grote plaatjes (macrotrombocyten), een licht verlaagd plaatjesgetal en slijmvliesbloedingen.</p>","image_url":"","wiki_title":"Bernard–Soulier syndrome","match":"de ziekte van bernard-soulier|ziekte van bernard-soulier|bernard-soulier syndroom","option_only":true},"rituximab":{"title":"Rituximab","short":"Rituximab is een monoklonaal antilichaam tegen CD20 op B-cellen; gebruikt bij lymfomen, CLL en auto-immuunziekten.","definition":"<p><strong>Rituximab</strong> bindt aan CD20 op rijpe B-cellen en vernietigt ze via complement en ADCC. Plasmacellen (CD20-negatief) blijven gespaard. Indicaties zijn B-cel-non-Hodgkinlymfomen, CLL, reumatoïde artritis en ANCA-vasculitis. Bijwerkingen: infusiereacties, infecties en reactivatie van hepatitis B.</p>","image_url":"","wiki_title":"Rituximab","match":"rituximab|anti-cd20","option_only":true},"hydroxychloroquine":{"title":"Hydroxychloroquine","short":"Hydroxychloroquine is een antimalariamiddel dat als mild immunomodulerend middel wordt gebruikt bij SLE en reumatoïde artritis.","definition":"<p><strong>Hydroxychloroquine</strong> remt o.a. de antigeenpresentatie en Toll-like-receptorsignalering door de pH in lysosomen te verhogen. Het is een basismiddel bij SLE (minder opvlammingen) en wordt gecombineerd bij reumatoïde artritis. Bij langdurig gebruik kan retinopathie ontstaan; daarom vindt oogheelkundige controle plaats.</p>","image_url":"","wiki_title":"Hydroxychloroquine","match":"hydroxychloroquine|plaquenil","option_only":true},"nitraten":{"title":"Nitraten","short":"Nitraten geven NO af en verwijden vooral de venen; ze verminderen de voorbelasting van het hart en verlichten angina pectoris.","definition":"<p><strong>Nitraten</strong> worden omgezet in stikstofmonoxide, dat via cGMP gladde spier ontspant. Door veneuze vaatverwijding dalen de vulling en het zuurstofverbruik van het hart; coronairen worden ook verwijd. Sublinguaal werken ze binnen minuten bij een angina-aanval. Bijwerkingen: hoofdpijn, flushing, hypotensie. Bij continu gebruik ontstaat tolerantie; niet combineren met PDE5-remmers.</p>","image_url":"","wiki_title":"Nitrate (medication)","match":"nitraten|nitroglycerine|isosorbidedinitraat|isosorbidemononitraat","option_only":true},"aldosteron-remmer":{"title":"Aldosteronantagonist","short":"Aldosteronantagonisten (spironolacton, eplerenon) blokkeren de mineralocorticoïdreceptor; ze zijn kaliumsparend en werken bij hartfalen en hyperaldosteronisme.","definition":"<p><strong>Spironolacton</strong> en <strong>eplerenon</strong> remmen het effect van aldosteron in de verzamelbuis, waardoor natrium wordt uitgescheiden en kalium wordt vastgehouden. Ze verlagen de sterfte bij hartfalen met verminderde ejectiefractie en worden gebruikt bij primair hyperaldosteronisme, ascites en therapieresistente hypertensie. Bijwerkingen: hyperkaliëmie en (vooral spironolacton) gynaecomastie.</p>","image_url":"","wiki_title":"Mineralocorticoid receptor antagonist","match":"aldosteron-remmer|aldosteronantagonist|spironolacton|eplerenon","option_only":true},"hypokaliëmie":{"title":"Hypokaliëmie","short":"Hypokaliëmie is een te laag kalium in het bloed, met spierzwakte, obstipatie en hartritmestoornissen als risico.","definition":"<p><strong>Hypokaliëmie</strong> ontstaat door verlies via nier (diuretica, hyperaldosteronisme, braken met metabole alkalose) of darm (diarree, laxantia), door verschuiving de cel in (insuline, β2-agonisten, alkalose) of zelden door te weinig inname. Op het ECG ziet men afgeplatte T-toppen en U-golven; het risico op aritmieën stijgt, vooral bij digoxinegebruik. Hypomagnesiëmie moet ook worden gecorrigeerd.</p>","image_url":"","wiki_title":"Hypokalemia","match":"hypokaliëmie|hypokaliemie","option_only":true},"tachycardie":{"title":"Tachycardie","short":"Tachycardie is een snelle hartslag, bij volwassenen boven 100 slagen per minuut.","definition":"<p>Een <strong>sinustachycardie</strong> is een fysiologische reactie op o.a. inspanning, koorts, pijn, angst, hypovolemie, anemie, hypoxie en hyperthyreoïdie. Pathologische tachycardieën zijn o.a. boezemfibrilleren, AVNRT en ventrikeltachycardie. Het ECG maakt het onderscheid.</p>","image_url":"","wiki_title":"Tachycardia","match":"tachycardie|sinustachycardie","option_only":true},"sinusbradycardie":{"title":"Sinusbradycardie","short":"Sinusbradycardie is een regelmatig hartritme vanuit de sinusknoop met een frequentie onder 50–60 per minuut.","definition":"<p>Een <strong>sinusbradycardie</strong> is normaal bij getrainde sporters en tijdens de slaap. Pathologische oorzaken zijn o.a. medicatie (bètablokkers, verapamil, digoxine), hypothyreoïdie, hypothermie, verhoogde vagustonus, verhoogde intracraniële druk (Cushing-reflex) en sinusknoopdysfunctie.</p>","image_url":"","wiki_title":"Sinus bradycardia","match":"sinusbradycardie","option_only":true},"atriumseptum defect":{"title":"Atriumseptumdefect (ASD)","short":"Een ASD is een aangeboren opening in het septum tussen de boezems, met een links-rechtsshunt.","definition":"<p>Bij een <strong>atriumseptumdefect</strong> (meestal type secundum) stroomt bloed van het linker- naar het rechteratrium, met volumebelasting van het rechterhart en de longcirculatie. Het geeft vaak pas op volwassen leeftijd klachten (vermoeidheid, kortademigheid, boezemfibrilleren). Kenmerkend is een vaste splijting van de tweede harttoon. Sluiting kan meestal via een katheter.</p>","image_url":"","wiki_title":"Atrial septal defect","match":"atriumseptum defect|atriumseptumdefect|asd","option_only":true},"persisterende ductus arteriosus":{"title":"Persisterende ductus arteriosus (PDA)","short":"Bij een PDA sluit de ductus arteriosus na de geboorte niet, waardoor bloed van de aorta naar de a. pulmonalis stroomt.","definition":"<p>De <strong>ductus arteriosus</strong> verbindt foetaal de a. pulmonalis met de aorta. Normaal sluit hij in de eerste dagen na de geboorte (door stijgende zuurstofspanning en dalende prostaglandinen). Bij prematuren en na rubella in de zwangerschap blijft hij vaker open. Er is een continu ‘machinegeruis’; sluiting met indomethacine/ibuprofen of via een katheter.</p>","image_url":"","wiki_title":"Patent ductus arteriosus","match":"persisterende ductus arteriosus|open ductus arteriosus|pda|ductus botalli","option_only":true},"transpositie van de grote vaten":{"title":"Transpositie van de grote arteriën","short":"Bij transpositie van de grote arteriën komt de aorta uit de rechterventrikel en de a. pulmonalis uit de linker, met twee gescheiden circulaties.","definition":"<p>Bij <strong>TGA</strong> is overleven na de geboorte alleen mogelijk via menging van bloed (foramen ovale, ductus arteriosus, VSD). De pasgeborene is direct na de geboorte ernstig cyanotisch. Prostaglandine houdt de ductus open en een ballonatrioseptostomie verbetert de menging, waarna een arteriële switchoperatie volgt.</p>","image_url":"","wiki_title":"Transposition of the great arteries","match":"transpositie van de grote vaten|transpositie van de grote arteriën|tga","option_only":true},"atherosclerose":{"title":"Atherosclerose","short":"Atherosclerose is een chronisch ontstekingsproces in de vaatwand waarbij plaques met vet, ontstekingscellen en bindweefsel ontstaan.","definition":"<p>Bij <strong>atherosclerose</strong> dringt LDL de intima binnen en wordt het geoxideerd; monocyten worden macrofagen en schuimcellen (fatty streak). Gladde spiercellen migreren en vormen een fibreuze kap over een lipidenkern. Scheuren van een plaque met trombose veroorzaakt een acuut coronair syndroom of herseninfarct. Risicofactoren: roken, hypertensie, LDL, diabetes, leeftijd en familiaire belasting.</p>","image_url":"","wiki_title":"Atherosclerosis","match":"atherosclerose|aderverkalking|arteriosclerose","option_only":true},"microscopische hematurie":{"title":"Microscopische hematurie","short":"Bij microscopische hematurie zijn rode bloedcellen alleen met de microscoop of een teststrook in de urine aantoonbaar.","definition":"<p><strong>Hematurie</strong> kan glomerulair zijn (dysmorfe erytrocyten, erytrocytencilinders, vaak met proteïnurie; bijv. IgA-nefropathie) of niet-glomerulair (stenen, infecties, tumoren van nier, ureter of blaas). Bij ouderen en rokers moet bij hematurie een urologische maligniteit worden uitgesloten.</p>","image_url":"","wiki_title":"Hematuria","match":"microscopische hematurie|hematurie","option_only":true},"hyperbilirubinemie":{"title":"Hyperbilirubinemie","short":"Hyperbilirubinemie is een verhoogd bilirubine in het bloed, zichtbaar als icterus.","definition":"<p>Een <strong>ongeconjugeerde</strong> hyperbilirubinemie ontstaat bij versterkte afbraak van rode bloedcellen (hemolyse), verminderde conjugatie (syndroom van Gilbert, neonatale icterus) of verminderde opname. Een <strong>geconjugeerde</strong> hyperbilirubinemie past bij leverziekte of galwegobstructie, met donkere urine en ontkleurde ontlasting.</p>","image_url":"","wiki_title":"Hyperbilirubinemia","match":"hyperbilirubinemie|hyperbilirubinaemie","option_only":true},"melaena":{"title":"Melaena","short":"Melaena is zwarte, teerachtige, stinkende ontlasting door een bloeding hoog in het maag-darmkanaal.","definition":"<p><strong>Melaena</strong> ontstaat als bloed uit slokdarm, maag of duodenum door maagzuur en bacteriën wordt omgezet. Belangrijke oorzaken zijn een ulcus pepticum en varices. Het ureum kan verhoogd zijn door eiwitresorptie. IJzerpreparaten en bismut kleuren de ontlasting ook zwart, maar niet teerachtig.</p>","image_url":"","wiki_title":"Melena","match":"melaena|melena|teerontlasting","option_only":true},"haematemesis":{"title":"Haematemesis","short":"Haematemesis is het braken van bloed, vers rood of als ‘koffiedik’, door een bloeding in slokdarm, maag of duodenum.","definition":"<p>Oorzaken van <strong>haematemesis</strong> zijn o.a. een ulcus pepticum, oesofagusvarices (bij portale hypertensie), een Mallory-Weiss-scheur na heftig braken, oesofagitis en tumoren. Koffiedikbraaksel wijst op bloed dat al met maagzuur in contact is geweest. Beoordeling van de circulatie en een spoedgastroscopie zijn nodig.</p>","image_url":"","wiki_title":"Hematemesis","match":"haematemesis|hematemesis|bloedbraken","option_only":true},"foliumzuur deficientie":{"title":"Foliumzuurdeficiëntie","short":"Een tekort aan foliumzuur geeft een macrocytaire (megaloblastaire) anemie en verhoogt in de zwangerschap het risico op een neuralebuisdefect.","definition":"<p>Een <strong>foliumzuurtekort</strong> ontstaat door weinig groenten in de voeding, alcoholisme, malabsorptie (coeliakie), verhoogde behoefte (zwangerschap, hemolyse) of medicatie (methotrexaat, trimethoprim, anti-epileptica). Anders dan bij B12-tekort zijn er geen neurologische afwijkingen en is het methylmalonzuur normaal; homocysteïne is bij beide verhoogd.</p>","image_url":"","wiki_title":"Folate deficiency","match":"foliumzuur deficientie|foliumzuurdeficiëntie|foliumzuurtekort","option_only":true},"leucocytose":{"title":"Leukocytose","short":"Leukocytose is een verhoogd aantal witte bloedcellen, meestal door infectie of ontsteking.","definition":"<p>Bij <strong>leukocytose</strong> is het aantal leukocyten boven ongeveer 10 × 10⁹/L. Een neutrofiele leukocytose met linksverschuiving past bij bacteriële infectie; ook stress, corticosteroïden, roken, trauma en necrose kunnen het verhogen. Sterk verhoogde waarden met onrijpe cellen in het bloed wijzen op leukemie of een leukemoïde reactie.</p>","image_url":"","wiki_title":"Leukocytosis","match":"leucocytose","option_only":true},"thiazidediuretica":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"thiazidediuretica","option_only":true},"valvulaire aortastenose":{"title":"Aortaklepstenose","short":"Bij aortaklepstenose opent de aortaklep onvoldoende, waardoor de linkerventrikel tegen verhoogde weerstand moet pompen.","definition":"<p><strong>Aortaklepstenose</strong> ontstaat meestal door degeneratieve verkalking op oudere leeftijd of bij een aangeboren bicuspide klep. De linkerventrikel hypertrofieert. Bij auscultatie is er een systolisch ejectiegeruis aan de basis, vaak uitstralend naar de carotiden. Klachten (angina, syncope bij inspanning, hartfalen) wijzen op een ernstige stenose; behandeling is klepvervanging (chirurgisch of TAVI).</p>","image_url":"","wiki_title":"Aortic stenosis","match":"valvulaire aortastenose","option_only":true},"diabetes type 2":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes type 2","option_only":true},"thiazide diureticum":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"thiazide diureticum","option_only":true},"hydrochloortiazide":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"hydrochloortiazide","option_only":true},"diabetes mellitus 2":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus 2","option_only":true},"alcoholmisbruik":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"alcoholmisbruik","option_only":true},"hoge koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"hoge koorts","option_only":true},"de ziekte van henoch schönlein":{"title":"IgA-vasculitis (Henoch-Schönlein)","short":"IgA-vasculitis is een vasculitis van kleine vaten met IgA-neerslagen, vooral bij kinderen: palpabele purpura op de benen, buikpijn, artritis en nierbetrokkenheid.","definition":"<p><strong>IgA-vasculitis</strong> (vroeger Henoch-Schönlein purpura) is de meest voorkomende vasculitis bij kinderen, vaak na een bovenste luchtweginfectie. IgA-bevattende immuuncomplexen slaan neer in de wand van kleine vaten.</p><p>Kenmerkende tetrade: <em>palpabele purpura</em> op billen en benen (bij normale bloedplaatjes), artralgie/artritis, koliekachtige buikpijn (soms invaginatie) en nierbetrokkenheid (hematurie, IgA-nefropathie-achtig beeld). Meestal zelflimiterend; nierfunctie vervolgen.</p>","image_url":"","wiki_title":"IgA vasculitis","match":"de ziekte van henoch schönlein","option_only":true},"sarcoïdose":{"title":"Sarcoïdose","short":"Sarcoïdose is een systemische aandoening van onbekende oorzaak met niet-verkazende granulomen, vooral in longen en lymfeklieren.","definition":"<p>Bij <strong>sarcoïdose</strong> zijn vaak de hilaire lymfeklieren en het longweefsel aangedaan; ook huid (erythema nodosum), ogen (uveïtis), hart en zenuwstelsel kunnen betrokken zijn. Het ACE en calcium kunnen verhoogd zijn. Het syndroom van Löfgren (koorts, erythema nodosum, hilaire klieren, enkelartritis) heeft een goede prognose.</p>","image_url":"","wiki_title":"Sarcoidosis","match":"sarcoïdose|sarcoidose|ziekte van besnier-boeck","option_only":true},"hartfalen":{"title":"Hartfalen","short":"Bij hartfalen kan het hart onvoldoende bloed rondpompen voor de behoefte van het lichaam, met kortademigheid, vermoeidheid en vochtophoping.","definition":"<p><strong>Hartfalen</strong> wordt ingedeeld naar ejectiefractie (verminderd, licht verminderd, behouden). Oorzaken zijn o.a. ischemie, hypertensie, klepziekten en cardiomyopathieën. Klachten: inspanningsdyspneu, orthopneu, oedeem, gewichtstoename. Diagnose met NT-proBNP en echocardiografie. Behandeling bij verminderde EF: ACE-remmer/ARNI, bètablokker, MRA, SGLT2-remmer en diuretica bij overvulling.</p>","image_url":"","wiki_title":"Heart failure","match":"hartfalen|decompensatio cordis|hartinsufficiëntie","option_only":true},"salbutamol vernevelen":{"title":"Salbutamol","short":"Salbutamol is een kortwerkende β2-agonist die binnen minuten de luchtwegen verwijdt; gebruikt bij astma- en COPD-aanvallen.","definition":"<p><strong>Salbutamol</strong> ontspant de gladde spier van de bronchi via β2-receptoren en cAMP. Het werkt binnen enkele minuten en ongeveer 4–6 uur. Het wordt via een dosisaerosol met voorzetkamer of als verneveling gegeven. Bijwerkingen: tremor, tachycardie en een daling van het kalium (het wordt daarom ook gebruikt bij hyperkaliëmie).</p>","image_url":"","wiki_title":"Salbutamol","match":"salbutamol vernevelen|salbutamol verneveling|salbutamol|saba|kortwerkende luchtwegverwijder","option_only":true},"nadroparine":{"title":"Nadroparine (LMWH)","short":"Nadroparine is een laagmoleculaire heparine die factor Xa remt via antitrombine; gebruikt ter preventie en behandeling van trombose.","definition":"<p><strong>LMWH's</strong> worden subcutaan toegediend, hebben een voorspelbare werking en hoeven meestal niet te worden gemonitord. Ze worden gebruikt bij trombose, ter tromboseprofylaxe (bijv. na operaties of bij immobilisatie) en in de zwangerschap. Ze worden via de nier geklaard; bij nierfalen is dosisaanpassing nodig. Bijwerkingen: bloedingen en (zeldzamer dan bij ongefractioneerde heparine) HIT.</p>","image_url":"","wiki_title":"Nadroparin","match":"nadroparine|laagmoleculaire gewichtsheparine|laagmoleculair heparine|lmwh|fraxiparine|dalteparine","option_only":true},"ongefractioneerde heparine":{"title":"Ongefractioneerde heparine","short":"Ongefractioneerde heparine versterkt antitrombine en remt zo trombine en factor Xa; intraveneus en kort werkend.","definition":"<p><strong>Ongefractioneerde heparine</strong> wordt vooral intraveneus gegeven en gemonitord met de APTT. Voordelen zijn de korte werkingsduur en de volledige antagonering met protamine, wat het geschikt maakt bij bijv. nierfalen, operaties en hartkatheterisaties. Het risico op HIT is groter dan bij LMWH.</p>","image_url":"","wiki_title":"Heparin","match":"ongefractioneerde heparine|heparine","option_only":true},"eclampsie":{"title":"Eclampsie","short":"Eclampsie is het optreden van epileptische aanvallen bij een vrouw met pre-eclampsie, tijdens de zwangerschap of kort erna.","definition":"<p><strong>Eclampsie</strong> is een levensbedreigende complicatie van pre-eclampsie (hypertensie met proteïnurie of orgaanschade na 20 weken). Waarschuwingssignalen zijn hoofdpijn, visusstoornissen, pijn in de bovenbuik en hyperreflexie. Behandeling: magnesiumsulfaat (ook ter preventie), bloeddrukverlaging en zo snel mogelijk de bevalling.</p>","image_url":"","wiki_title":"Eclampsia","match":"eclampsie","option_only":true},"proteïne c tekort":{"title":"Proteïne C-deficiëntie","short":"Een tekort aan proteïne C geeft een verhoogd risico op veneuze trombose, omdat factor Va en VIIIa minder worden geremd.","definition":"<p><strong>Proteïne C</strong> is een vitamine K-afhankelijk natuurlijk antistollingseiwit dat (geactiveerd door trombomoduline-trombine, met proteïne S als cofactor) factor Va en VIIIa afbreekt. Een erfelijk tekort is een trombofilie. Bij start van cumarines daalt proteïne C snel, wat zelden een huidnecrose kan geven; daarom wordt in het begin heparine bijgegeven.</p>","image_url":"","wiki_title":"Protein C deficiency","match":"proteïne c tekort|proteïne c-deficiëntie|proteine c tekort","option_only":true},"hemofilie b":{"title":"Hemofilie B","short":"Hemofilie B is een X-gebonden erfelijk tekort aan stollingsfactor IX, met een vergelijkbaar beeld als hemofilie A.","definition":"<p>Bij <strong>hemofilie B</strong> (ziekte van Christmas) ontstaan diepe bloedingen in gewrichten en spieren en nabloedingen na ingrepen. De APTT is verlengd. Behandeling met factor IX-concentraat; recent is ook gentherapie beschikbaar.</p>","image_url":"","wiki_title":"Haemophilia B","match":"hemofilie b|factor ix-deficiëntie","option_only":true},"acuut reuma (engels: rheumatic fever)":{"title":"Acuut reuma","short":"Acuut reuma is een ontstekingsziekte enkele weken na een keelinfectie met groep A-streptokokken, door kruisreactie van antistoffen.","definition":"<p><strong>Acuut reuma</strong> geeft volgens de Jones-criteria o.a. carditis, een migrerende polyartritis, chorea van Sydenham, erythema marginatum en subcutane noduli. De carditis kan leiden tot chronische reumatische klepziekte, vooral van de mitralisklep. Het is in Nederland zeldzaam geworden, maar wereldwijd nog een belangrijke oorzaak van hartziekte.</p>","image_url":"","wiki_title":"Rheumatic fever","match":"acuut reuma (engels: rheumatic fever)|acuut reuma|rheumatic fever","option_only":true},"de ziekte van still":{"title":"Ziekte van Still","short":"De ziekte van Still is een systemische auto-inflammatoire ziekte met piekende koorts, artritis en een vluchtige zalmroze huiduitslag.","definition":"<p>De <strong>ziekte van Still</strong> (systemische juveniele idiopathische artritis bij kinderen, adult-onset Still bij volwassenen) geeft dagelijkse koortspieken, artritis, een vluchtige zalmkleurige rash, lymfadenopathie en splenomegalie, met een sterk verhoogd ferritine. Een gevreesde complicatie is het macrofaagactivatiesyndroom.</p>","image_url":"","wiki_title":"Adult-onset Still's disease","match":"de ziekte van still|ziekte van still","option_only":true},"angiotensine receptorblokkers (arb's)":{"title":"Angiotensine II-receptorblokkers (ARB's)","short":"ARB's blokkeren de AT1-receptor voor angiotensine II; ze verlagen de bloeddruk en beschermen hart en nieren.","definition":"<p><strong>ARB's</strong> (losartan, valsartan, irbesartan) worden gebruikt bij hypertensie, hartfalen en diabetische nefropathie. Ze geven geen bradykininehoest zoals ACE-remmers. Bijwerkingen: hyperkaliëmie en nierfunctieverslechtering; gecontra-indiceerd in de zwangerschap.</p>","image_url":"","wiki_title":"Angiotensin II receptor blocker","match":"angiotensine receptorblokkers (arb's)|arb|arb's|angiotensine-ii-receptorblokker|sartanen","option_only":true},"valsartan":{"title":"Valsartan","short":"Valsartan is een angiotensine II-receptorblokker, gebruikt bij hypertensie en hartfalen (ook in combinatie met sacubitril).","definition":"<p><strong>Valsartan</strong> blokkeert de AT1-receptor. Bij hartfalen met verminderde ejectiefractie wordt het gecombineerd met de neprilysineremmer sacubitril (ARNI), wat de sterfte verder vermindert. Bijwerkingen zijn hyperkaliëmie, hypotensie en nierfunctieverslechtering.</p>","image_url":"","wiki_title":"Valsartan","match":"valsartan","option_only":true},"amlodipine":{"title":"Amlodipine","short":"Amlodipine is een langwerkende dihydropyridine-calciumantagonist die de arteriën verwijdt; gebruikt bij hypertensie en angina.","definition":"<p><strong>Dihydropyridines</strong> (amlodipine, nifedipine) blokkeren L-type calciumkanalen vooral in vasculaire gladde spier en hebben weinig effect op het hart. Bijwerkingen zijn enkeloedeem (door precapillaire vaatverwijding), hoofdpijn, flushing en tandvleeshyperplasie. Non-dihydropyridines (verapamil, diltiazem) werken juist meer op hart en AV-knoop.</p>","image_url":"","wiki_title":"Amlodipine","match":"amlodipine|dihydropyridine calciumantagonisten|dihydropyridine","option_only":true},"non-dihydropyridine calciumantagonisten":{"title":"Non-dihydropyridine-calciumantagonisten","short":"Non-dihydropyridines (verapamil, diltiazem) remmen calciumkanalen in hart en AV-knoop en verlagen de hartfrequentie.","definition":"<p>Deze middelen vertragen de geleiding in de AV-knoop en verminderen de contractiekracht. Ze worden gebruikt voor frequentiecontrole bij boezemfibrilleren, bij supraventriculaire tachycardieën en angina pectoris. Ze zijn gecontra-indiceerd bij hartfalen met verminderde ejectiefractie en worden niet gecombineerd met bètablokkers.</p>","image_url":"","wiki_title":"Calcium channel blocker","match":"non-dihydropyridine calciumantagonisten|diltiazem","option_only":true},"hydralazine":{"title":"Hydralazine","short":"Hydralazine is een directe arteriële vaatverwijder, o.a. gebruikt bij hypertensie in de zwangerschap.","definition":"<p><strong>Hydralazine</strong> ontspant arteriolaire gladde spier. Het geeft een reflextachycardie en vochtretentie, en wordt daarom vaak gecombineerd. Het wordt gebruikt bij ernstige hypertensie in de zwangerschap en (met nitraten) bij hartfalen. Langdurig gebruik kan een geneesmiddel-geïnduceerde lupus geven, vooral bij langzame acetyleerders.</p>","image_url":"","wiki_title":"Hydralazine","match":"hydralazine","option_only":true},"moxonidine":{"title":"Moxonidine","short":"Moxonidine is een centraal werkend antihypertensivum dat de sympathische activiteit vermindert.","definition":"<p><strong>Moxonidine</strong> stimuleert imidazolinereceptoren (en α2-receptoren) in de hersenstam, waardoor het sympathische zenuwstelsel minder actief wordt en de bloeddruk daalt. Het wordt gebruikt als aanvullend middel. Bijwerkingen zijn een droge mond, sufheid en bij abrupt stoppen een rebound-hypertensie (sterker bij clonidine).</p>","image_url":"","wiki_title":"Moxonidine","match":"moxonidine|clonidine","option_only":true},"urapidil":{"title":"Urapidil","short":"Urapidil is een intraveneus antihypertensivum (α1-blokker met centrale werking), gebruikt bij hypertensieve crises.","definition":"<p><strong>Urapidil</strong> blokkeert perifere α1-receptoren en stimuleert centrale 5-HT1A-receptoren. Daardoor daalt de bloeddruk zonder veel reflextachycardie. Het wordt intraveneus gebruikt bij een hypertensieve spoedsituatie.</p>","image_url":"","wiki_title":"Urapidil","match":"urapidil","option_only":true},"aliskiren":{"title":"Aliskiren","short":"Aliskiren is een directe renineremmer die de bloeddruk verlaagt door het RAAS aan het begin te remmen.","definition":"<p><strong>Aliskiren</strong> remt de omzetting van angiotensinogeen in angiotensine I. Het wordt weinig gebruikt, omdat het geen voordeel liet zien boven ACE-remmers en ARB's en in combinatie daarmee juist meer bijwerkingen gaf (hyperkaliëmie, nierfunctieverslechtering).</p>","image_url":"","wiki_title":"Aliskiren","match":"aliskiren","option_only":true},"dipyridamol":{"title":"Dipyridamol","short":"Dipyridamol is een plaatjesremmer die de afbraak van cAMP remt en de opname van adenosine vermindert.","definition":"<p><strong>Dipyridamol</strong> werd vooral in combinatie met acetylsalicylzuur gebruikt ter secundaire preventie na een TIA of herseninfarct. Het verwijdt ook vaten, wat hoofdpijn kan geven en bij farmacologische stresstests van het hart wordt benut.</p>","image_url":"","wiki_title":"Dipyridamole","match":"dipyridamol","option_only":true},"streptokinase":{"title":"Streptokinase","short":"Streptokinase is een eiwit van streptokokken dat plasminogeen activeert en zo stolsels oplost (trombolyse).","definition":"<p><strong>Streptokinase</strong> vormt een complex met plasminogeen dat ander plasminogeen in plasmine omzet. Het is goedkoop, maar omdat het een vreemd eiwit is kunnen antistoffen ontstaan (allergische reacties, minder effect bij herhaling). In westerse landen is het grotendeels vervangen door weefselplasminogeenactivatoren.</p>","image_url":"","wiki_title":"Streptokinase","match":"streptokinase","option_only":true},"plasminogeen activator inhibitor 1":{"title":"Plasminogeenactivatorremmer-1 (PAI-1)","short":"PAI-1 remt de plasminogeenactivatoren tPA en uPA en remt zo de afbraak van stolsels (fibrinolyse).","definition":"<p><strong>PAI-1</strong> wordt gemaakt door endotheel, lever en vetweefsel. Verhoogde spiegels (bij obesitas, insulineresistentie, ontsteking) remmen de fibrinolyse en worden in verband gebracht met een verhoogd risico op trombose en hart- en vaatziekten.</p>","image_url":"","wiki_title":"Plasminogen activator inhibitor-1","match":"plasminogeen activator inhibitor 1|pai-1","option_only":true},"fibrinogeen":{"title":"Fibrinogeen","short":"Fibrinogeen is het stollingseiwit dat door trombine wordt omgezet in fibrine, de draden van het stolsel.","definition":"<p><strong>Fibrinogeen</strong> wordt in de lever gemaakt en is ook een acutefase-eiwit. Het verbindt bloedplaatjes via de GPIIb/IIIa-receptor. Een laag fibrinogeen past bij verbruik (diffuse intravasale stolling, massaal bloedverlies) of verminderde aanmaak (leverfalen). Een hoog fibrinogeen draagt bij aan een verhoogde BSE.</p>","image_url":"","wiki_title":"Fibrinogen","match":"fibrinogeen|factor i","option_only":true},"diffuse intravasale stolling (dis)":{"title":"Diffuse intravasale stolling (DIS)","short":"Bij DIS wordt de stolling in het hele lichaam ontregeld geactiveerd, met microtrombi én bloedingen door verbruik van stollingsfactoren en plaatjes.","definition":"<p><strong>DIS</strong> ontstaat bij o.a. sepsis, trauma, obstetrische complicaties (placentaloslating, vruchtwaterembolie), acute promyelocytenleukemie en uitgebreide tumoren. Kenmerken: daling van plaatjes en fibrinogeen, verlengde PT/APTT en sterk verhoogde D-dimeer, met orgaanschade en bloedingen. Behandeling van de oorzaak staat centraal.</p>","image_url":"","wiki_title":"Disseminated intravascular coagulation","match":"diffuse intravasale stolling (dis)|diffuse intravasale stolling|dis|dic","option_only":true},"protrombinemutatie":{"title":"Protrombinemutatie (factor II G20210A)","short":"De protrombinemutatie verhoogt de protrombinespiegel en daarmee het risico op veneuze trombose.","definition":"<p>De <strong>protrombine-G20210A-mutatie</strong> ligt in het niet-coderende deel van het gen en leidt tot meer aanmaak van protrombine. Na factor V Leiden is het de meest voorkomende erfelijke trombofilie bij mensen van Europese afkomst.</p>","image_url":"","wiki_title":"Prothrombin G20210A","match":"protrombinemutatie|protrombine g20210a|factor ii mutatie","option_only":true},"4-factorenconcentraat":{"title":"Vierfactorenconcentraat (protrombinecomplex)","short":"Vierfactorenconcentraat bevat stollingsfactoren II, VII, IX en X en heft snel het effect van cumarines op.","definition":"<p><strong>Protrombinecomplexconcentraat</strong> wordt gegeven bij een ernstige bloeding of een spoedingreep bij een patiënt die cumarines gebruikt, samen met vitamine K (dat trager werkt). Het werkt binnen minuten. Ook bij sommige directe orale anticoagulantia wordt het als behandeling van bloedingen ingezet.</p>","image_url":"","wiki_title":"Prothrombin complex concentrate","match":"4-factorenconcentraat|vierfactorenconcentraat|toediening vier-factorenconcentraat|protrombinecomplexconcentraat|pcc","option_only":true},"chronische veneuze insufficiëntie":{"title":"Chronische veneuze insufficiëntie","short":"Bij chronische veneuze insufficiëntie werkt de veneuze terugstroom uit de benen slecht, met oedeem, huidverkleuring en uiteindelijk ulcera.","definition":"<p>Door lekkende kleppen of een doorgemaakte trombose (posttrombotisch syndroom) stijgt de veneuze druk in de benen. Gevolgen: varices, oedeem, hyperpigmentatie (hemosiderine), eczeem, lipodermatosclerose, atrophie blanche en een ulcus cruris venosum, typisch rond de mediale enkel. Behandeling met compressietherapie.</p>","image_url":"","wiki_title":"Chronic venous insufficiency","match":"chronische veneuze insufficiëntie|veneuze insufficiëntie","option_only":true},"dilaterende cardiomyopathie (dcm)":{"title":"Gedilateerde cardiomyopathie","short":"Bij gedilateerde cardiomyopathie is de linkerventrikel verwijd en pompt hij slecht, met hartfalen en ritmestoornissen.","definition":"<p>Oorzaken van <strong>gedilateerde cardiomyopathie</strong> zijn erfelijk (o.a. titine- en lamine-mutaties), myocarditis, alcohol, chemotherapie (antracyclines), tachycardie en zwangerschap (peripartum). Het geeft hartfalen met een verminderde ejectiefractie, ventriculaire aritmieën en trombo-embolie.</p>","image_url":"","wiki_title":"Dilated cardiomyopathy","match":"dilaterende cardiomyopathie (dcm)|gedilateerde cardiomyopathie|dilaterende cardiomyopathie|dcm","option_only":true},"diabetes insipidus":{"title":"Diabetes insipidus","short":"Bij diabetes insipidus scheiden de nieren grote hoeveelheden verdunde urine uit door een tekort aan of ongevoeligheid voor ADH.","definition":"<p>Bij <strong>centrale</strong> diabetes insipidus maakt de hypothalamus/neurohypofyse te weinig ADH (bijv. na trauma, operatie of door een tumor); bij <strong>nefrogene</strong> diabetes insipidus reageert de nier niet op ADH (bijv. door lithium, hypercalciëmie of erfelijk). Klachten: polyurie en dorst; zonder voldoende drinken ontstaat hypernatriëmie. Een dorstproef met desmopressine maakt het onderscheid.</p>","image_url":"","wiki_title":"Diabetes insipidus","match":"diabetes insipidus","option_only":true},"aortadissectie, type a":{"title":"Aortadissectie","short":"Bij een aortadissectie scheurt de binnenwand van de aorta, waardoor bloed tussen de wandlagen stroomt; type A betreft de aorta ascendens en is een chirurgisch spoedgeval.","definition":"<p>Een <strong>aortadissectie</strong> geeft plotselinge, zeer hevige, scheurende pijn in borst of rug, soms met een bloeddrukverschil tussen de armen, een nieuw diastolisch geruis of neurologische uitval. Risicofactoren: hypertensie, bindweefselziekten (Marfan), bicuspide klep en cocaïne. Type A (aorta ascendens) vereist een spoedoperatie; type B wordt vaak eerst medicamenteus behandeld.</p>","image_url":"","wiki_title":"Aortic dissection","match":"aortadissectie, type a|aortadissectie|dissectie thoracale aorta|dissectie van de aorta","option_only":true},"pulsus paradoxus":{"title":"Pulsus paradoxus","short":"Pulsus paradoxus is een overmatige daling (>10 mmHg) van de systolische bloeddruk tijdens inademing.","definition":"<p>Normaal daalt de systolische druk bij inademing iets. Bij een <strong>pulsus paradoxus</strong> is die daling groter, doordat bij een harttamponnade (of ernstig astma/COPD) de vulling van het rechterhart bij inademing het linkerhart verdrukt. Het is een klassiek teken van harttamponnade.</p>","image_url":"","wiki_title":"Pulsus paradoxus","match":"pulsus paradoxus","option_only":true},"pulsus alternans":{"title":"Pulsus alternans","short":"Bij pulsus alternans wisselen sterke en zwakke polsslagen elkaar af bij een regelmatig ritme; een teken van ernstig linkerhartfalen.","definition":"<p>Een <strong>pulsus alternans</strong> ontstaat door een afwisselende contractiekracht van een ernstig verzwakte linkerventrikel. Het wijst op een slechte pompfunctie en een ongunstige prognose.</p>","image_url":"","wiki_title":"Pulsus alternans","match":"pulsus alternans","option_only":true},"capillairen":{"title":"Capillairen","short":"Capillairen zijn de kleinste bloedvaten, met een wand van één laag endotheel, waar de uitwisseling tussen bloed en weefsel plaatsvindt.","definition":"<p>Er zijn <strong>continue</strong> capillairen (o.a. spier, huid, brein: bloed-hersenbarrière), <strong>gefenestreerde</strong> capillairen (nier, darm, endocriene klieren) en <strong>sinusoïdale</strong> capillairen (lever, milt, beenmerg). Volgens Starling bepalen hydrostatische en colloïd-osmotische druk de vochtverplaatsing over de wand.</p>","image_url":"","wiki_title":"Capillary","match":"capillairen|haarvaten|capillair","option_only":true},"chylomicronen":{"title":"Chylomicronen","short":"Chylomicronen zijn grote lipoproteïnen die vetten uit de voeding via de lymfe naar het bloed vervoeren.","definition":"<p><strong>Chylomicronen</strong> worden in enterocyten gemaakt uit triglyceriden, cholesterol en apoB-48 en via de lymfe (ductus thoracicus) afgegeven. Lipoproteïnelipase splitst hun triglyceriden; de resten (remnants) worden door de lever opgenomen. Na een vetrijke maaltijd kan het plasma daardoor melkachtig zijn.</p>","image_url":"","wiki_title":"Chylomicron","match":"chylomicronen|chylomicron","option_only":true},"atriaal septumdefect":{"title":"Atriumseptumdefect (ASD)","short":"Een ASD is een aangeboren opening in het septum tussen de boezems, met een links-rechtsshunt.","definition":"<p>Bij een <strong>atriumseptumdefect</strong> (meestal type secundum) stroomt bloed van het linker- naar het rechteratrium, met volumebelasting van het rechterhart en de longcirculatie. Het geeft vaak pas op volwassen leeftijd klachten (vermoeidheid, kortademigheid, boezemfibrilleren). Kenmerkend is een vaste splijting van de tweede harttoon. Sluiting kan meestal via een katheter.</p>","image_url":"","wiki_title":"Atrial septal defect","match":"atriaal septumdefect","option_only":true},"ventriculair septumdefect":{"title":"Ventrikelseptumdefect (VSD)","short":"Een VSD is een aangeboren opening in het septum tussen de linker- en rechterventrikel, met een links-rechtsshunt.","definition":"<p>Bij een <strong>ventrikelseptumdefect</strong> stroomt bloed in de systole van links naar rechts, wat een luid holosystolisch geruis links parasternaal geeft. Kleine (vaak musculaire) defecten sluiten vaak spontaan. Grote defecten geven volumebelasting van de longcirculatie en hartfalen op jonge leeftijd; zonder sluiting kan pulmonale hypertensie (Eisenmenger) ontstaan.</p>","image_url":"","wiki_title":"Ventricular septal defect","match":"ventriculair septumdefect","option_only":true},"de ziekte van kawasaki":{"title":"Ziekte van Kawasaki","short":"De ziekte van Kawasaki is een vasculitis bij jonge kinderen met langdurige koorts; de belangrijkste complicatie zijn coronaire aneurysmata.","definition":"<p>De <strong>ziekte van Kawasaki</strong> treft vooral kinderen onder de 5 jaar. Kenmerken: koorts van minstens vijf dagen met conjunctivitis zonder pus, veranderingen van lippen en mondslijmvlies (aardbeientong), huiduitslag, roodheid en zwelling van handen en voeten (later vervellen) en een vergrote halsklier. Behandeling met intraveneuze immunoglobulinen en acetylsalicylzuur verkleint de kans op coronaire aneurysmata.</p>","image_url":"","wiki_title":"Kawasaki disease","match":"de ziekte van kawasaki","option_only":true},"polyarteritis nodosa (pan)":{"title":"Polyarteriitis nodosa","short":"Polyarteriitis nodosa is een necrotiserende vasculitis van middelgrote arteriën, zonder ANCA en zonder glomerulonefritis.","definition":"<p>Bij <strong>polyarteriitis nodosa</strong> raken middelgrote spierarteriën ontstoken, met microaneurysmata en infarcten in o.a. nieren (hypertensie), darm (buikpijn), huid (livedo, ulcera) en zenuwen (mononeuritis multiplex). Een deel van de gevallen hangt samen met hepatitis B. De longen zijn meestal niet aangedaan.</p>","image_url":"","wiki_title":"Polyarteritis nodosa","match":"polyarteritis nodosa (pan)","option_only":true},"een myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"een myocardinfarct","option_only":true},"doorgemaakt mi":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"doorgemaakt mi","option_only":true},"myocardinfarcering":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"myocardinfarcering","option_only":true},"lis-diureticum":{"title":"Lisdiureticum","short":"Lisdiuretica remmen de NKCC2-cotransporter in de lis van Henle en zijn de krachtigste plasmiddelen.","definition":"<p><strong>Lisdiuretica</strong> zoals furosemide remmen de Na⁺/K⁺/2Cl⁻-cotransporter in het dikke opstijgende deel van de lis van Henle. Ze worden gebruikt bij oedeem door hartfalen, nierziekte of levercirrose en bij longoedeem. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, metabole alkalose, uitdroging en ototoxiciteit; anders dan thiaziden verhogen ze de calciumuitscheiding.</p>","image_url":"","wiki_title":"Loop diuretic","match":"lis-diureticum","option_only":true},"een lisdiureticum":{"title":"Lisdiureticum","short":"Lisdiuretica remmen de NKCC2-cotransporter in de lis van Henle en zijn de krachtigste plasmiddelen.","definition":"<p><strong>Lisdiuretica</strong> zoals furosemide remmen de Na⁺/K⁺/2Cl⁻-cotransporter in het dikke opstijgende deel van de lis van Henle. Ze worden gebruikt bij oedeem door hartfalen, nierziekte of levercirrose en bij longoedeem. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, metabole alkalose, uitdroging en ototoxiciteit; anders dan thiaziden verhogen ze de calciumuitscheiding.</p>","image_url":"","wiki_title":"Loop diuretic","match":"een lisdiureticum","option_only":true},"een thiazidediureticum":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"een thiazidediureticum","option_only":true},"betablocker":{"title":"Bètablokker","short":"Bètablokkers blokkeren bèta-adrenerge receptoren en verlagen hartfrequentie, contractiekracht en reninesecretie.","definition":"<p><strong>Bètablokkers</strong> worden gebruikt bij hypertensie, angina pectoris, na een hartinfarct, bij hartfalen, ritmestoornissen, tremor en migraineprofylaxe. Cardioselectieve middelen (metoprolol, bisoprolol) werken vooral op β1; niet-selectieve (propranolol) ook op β2, wat bronchospasme kan geven. Bijwerkingen: bradycardie, vermoeidheid, koude extremiteiten en het maskeren van hypoglykemieverschijnselen.</p>","image_url":"","wiki_title":"Beta blocker","match":"betablocker","option_only":true},"aldosteronantagonisten":{"title":"Aldosteronantagonist","short":"Aldosteronantagonisten (spironolacton, eplerenon) blokkeren de mineralocorticoïdreceptor; ze zijn kaliumsparend en werken bij hartfalen en hyperaldosteronisme.","definition":"<p><strong>Spironolacton</strong> en <strong>eplerenon</strong> remmen het effect van aldosteron in de verzamelbuis, waardoor natrium wordt uitgescheiden en kalium wordt vastgehouden. Ze verlagen de sterfte bij hartfalen met verminderde ejectiefractie en worden gebruikt bij primair hyperaldosteronisme, ascites en therapieresistente hypertensie. Bijwerkingen: hyperkaliëmie en (vooral spironolacton) gynaecomastie.</p>","image_url":"","wiki_title":"Mineralocorticoid receptor antagonist","match":"aldosteronantagonisten","option_only":true},"aldosteron-antagonist":{"title":"Aldosteronantagonist","short":"Aldosteronantagonisten (spironolacton, eplerenon) blokkeren de mineralocorticoïdreceptor; ze zijn kaliumsparend en werken bij hartfalen en hyperaldosteronisme.","definition":"<p><strong>Spironolacton</strong> en <strong>eplerenon</strong> remmen het effect van aldosteron in de verzamelbuis, waardoor natrium wordt uitgescheiden en kalium wordt vastgehouden. Ze verlagen de sterfte bij hartfalen met verminderde ejectiefractie en worden gebruikt bij primair hyperaldosteronisme, ascites en therapieresistente hypertensie. Bijwerkingen: hyperkaliëmie en (vooral spironolacton) gynaecomastie.</p>","image_url":"","wiki_title":"Mineralocorticoid receptor antagonist","match":"aldosteron-antagonist","option_only":true},"nitraat":{"title":"Nitraten","short":"Nitraten geven NO af en verwijden vooral de venen; ze verminderen de voorbelasting van het hart en verlichten angina pectoris.","definition":"<p><strong>Nitraten</strong> worden omgezet in stikstofmonoxide, dat via cGMP gladde spier ontspant. Door veneuze vaatverwijding dalen de vulling en het zuurstofverbruik van het hart; coronairen worden ook verwijd. Sublinguaal werken ze binnen minuten bij een angina-aanval. Bijwerkingen: hoofdpijn, flushing, hypotensie. Bij continu gebruik ontstaat tolerantie; niet combineren met PDE5-remmers.</p>","image_url":"","wiki_title":"Nitrate (medication)","match":"nitraat","option_only":true},"nitraten (nicorandil)":{"title":"Nitraten","short":"Nitraten geven NO af en verwijden vooral de venen; ze verminderen de voorbelasting van het hart en verlichten angina pectoris.","definition":"<p><strong>Nitraten</strong> worden omgezet in stikstofmonoxide, dat via cGMP gladde spier ontspant. Door veneuze vaatverwijding dalen de vulling en het zuurstofverbruik van het hart; coronairen worden ook verwijd. Sublinguaal werken ze binnen minuten bij een angina-aanval. Bijwerkingen: hoofdpijn, flushing, hypotensie. Bij continu gebruik ontstaat tolerantie; niet combineren met PDE5-remmers.</p>","image_url":"","wiki_title":"Nitrate (medication)","match":"nitraten (nicorandil)","option_only":true},"een statine":{"title":"Simvastatine","short":"Simvastatine is een statine: een HMG-CoA-reductaseremmer die het LDL-cholesterol verlaagt.","definition":"<p><strong>Simvastatine</strong> remt HMG-CoA-reductase, het snelheidsbepalende enzym van de cholesterolsynthese in de lever. De lever maakt daardoor meer LDL-receptoren aan en haalt meer LDL uit het bloed. Statines verlagen het risico op hart- en vaatziekten. Bijwerkingen: spierklachten (zelden rabdomyolyse) en leverenzymstijging; simvastatine heeft veel interacties via CYP3A4.</p>","image_url":"","wiki_title":"Simvastatin","match":"een statine","option_only":true},"atorvastatine":{"title":"Simvastatine","short":"Simvastatine is een statine: een HMG-CoA-reductaseremmer die het LDL-cholesterol verlaagt.","definition":"<p><strong>Simvastatine</strong> remt HMG-CoA-reductase, het snelheidsbepalende enzym van de cholesterolsynthese in de lever. De lever maakt daardoor meer LDL-receptoren aan en haalt meer LDL uit het bloed. Statines verlagen het risico op hart- en vaatziekten. Bijwerkingen: spierklachten (zelden rabdomyolyse) en leverenzymstijging; simvastatine heeft veel interacties via CYP3A4.</p>","image_url":"","wiki_title":"Simvastatin","match":"atorvastatine","option_only":true},"diep-veneuze trombose rechts":{"title":"Trombosebeen (diepveneuze trombose)","short":"Een trombosebeen is een stolsel in een diepe vene van het been, met een dik, pijnlijk, warm been.","definition":"<p>Bij een <strong>diepveneuze trombose</strong> ontstaat een stolsel in de diepe venen, meestal in de kuit of bovenbeen. Risicofactoren volgen de trias van Virchow: stase, hypercoagulabiliteit en vaatwandschade (bijv. operatie, immobilisatie, kanker, zwangerschap, oestrogenen). Diagnostiek met een beslisregel (Wells), D-dimeer en compressie-echografie. De belangrijkste complicatie is een longembolie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Deep vein thrombosis","match":"diep-veneuze trombose rechts","option_only":true},"tromboembolie":{"title":"Longembolie","short":"Bij een longembolie sluit een stolsel (meestal uit de beenvenen) een longslagader af, met acute benauwdheid en pijn bij het ademen.","definition":"<p>Een <strong>longembolie</strong> ontstaat meestal door een trombus uit de diepe venen van been of bekken. Risicofactoren volgen de trias van Virchow: stase (immobilisatie), hypercoagulabiliteit (kanker, oestrogenen, zwangerschap, erfelijke trombofilie) en vaatwandschade (operatie, trauma). Klachten: plotselinge dyspneu, pleuritische pijn, tachycardie, soms hemoptoë of collaps. Diagnostiek met een beslisregel, D-dimeer en CT-angiografie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Pulmonary embolism","match":"tromboembolie","option_only":true},"trombo-embolie":{"title":"Longembolie","short":"Bij een longembolie sluit een stolsel (meestal uit de beenvenen) een longslagader af, met acute benauwdheid en pijn bij het ademen.","definition":"<p>Een <strong>longembolie</strong> ontstaat meestal door een trombus uit de diepe venen van been of bekken. Risicofactoren volgen de trias van Virchow: stase (immobilisatie), hypercoagulabiliteit (kanker, oestrogenen, zwangerschap, erfelijke trombofilie) en vaatwandschade (operatie, trauma). Klachten: plotselinge dyspneu, pleuritische pijn, tachycardie, soms hemoptoë of collaps. Diagnostiek met een beslisregel, D-dimeer en CT-angiografie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Pulmonary embolism","match":"trombo-embolie","option_only":true},"reumatoide artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoide artritis","option_only":true},"factor v-leiden mutatie":{"title":"Factor V Leiden","short":"Factor V Leiden is een erfelijke mutatie waardoor factor V ongevoelig is voor afbraak door geactiveerd proteïne C, met een verhoogd tromboserisico.","definition":"<p>Bij <strong>factor V Leiden</strong> (een puntmutatie in het F5-gen) kan geactiveerd proteïne C factor Va niet goed inactiveren (APC-resistentie). Het is de meest voorkomende erfelijke trombofilie bij mensen van Europese afkomst. Het verhoogt het risico op veneuze trombose, vooral in combinatie met orale anticonceptie, zwangerschap of immobilisatie.</p>","image_url":"","wiki_title":"Factor V Leiden","match":"factor v-leiden mutatie","option_only":true},"antifosfolipidensyndroom (aps)":{"title":"Lupus anticoagulans","short":"Lupus anticoagulans is een antifosfolipide-antistof die in het lab de stolling verlengt, maar in het lichaam juist trombose bevordert.","definition":"<p><strong>Lupus anticoagulans</strong> wordt aangetoond met stollingstests (bijv. een verlengde APTT die niet corrigeert bij menging). Samen met anti-cardiolipine en anti-β2-glycoproteïne I vormt het de basis van het antifosfolipidensyndroom: veneuze en arteriële trombose en zwangerschapscomplicaties (herhaalde miskramen). Het komt voor met of zonder SLE.</p>","image_url":"","wiki_title":"Lupus anticoagulant","match":"antifosfolipidensyndroom (aps)","option_only":true},"anti-fosfolipidensyndroom":{"title":"Lupus anticoagulans","short":"Lupus anticoagulans is een antifosfolipide-antistof die in het lab de stolling verlengt, maar in het lichaam juist trombose bevordert.","definition":"<p><strong>Lupus anticoagulans</strong> wordt aangetoond met stollingstests (bijv. een verlengde APTT die niet corrigeert bij menging). Samen met anti-cardiolipine en anti-β2-glycoproteïne I vormt het de basis van het antifosfolipidensyndroom: veneuze en arteriële trombose en zwangerschapscomplicaties (herhaalde miskramen). Het komt voor met of zonder SLE.</p>","image_url":"","wiki_title":"Lupus anticoagulant","match":"anti-fosfolipidensyndroom","option_only":true},"aanwezigheid van antifosfolipiden":{"title":"Lupus anticoagulans","short":"Lupus anticoagulans is een antifosfolipide-antistof die in het lab de stolling verlengt, maar in het lichaam juist trombose bevordert.","definition":"<p><strong>Lupus anticoagulans</strong> wordt aangetoond met stollingstests (bijv. een verlengde APTT die niet corrigeert bij menging). Samen met anti-cardiolipine en anti-β2-glycoproteïne I vormt het de basis van het antifosfolipidensyndroom: veneuze en arteriële trombose en zwangerschapscomplicaties (herhaalde miskramen). Het komt voor met of zonder SLE.</p>","image_url":"","wiki_title":"Lupus anticoagulant","match":"aanwezigheid van antifosfolipiden","option_only":true},"overdosering acenocoumarol":{"title":"Acenocoumarol","short":"Acenocoumarol is een kortwerkende cumarine (vitamine K-antagonist) voor antistolling, gedoseerd op geleide van de INR.","definition":"<p><strong>Acenocoumarol</strong> werkt net als fenprocoumon door remming van de vitamine K-cyclus, maar heeft een kortere halfwaardetijd. Het wordt gebruikt bij o.a. boezemfibrilleren, trombose en kunstkleppen. Controle via de INR is nodig; veel geneesmiddelen (zoals antibiotica) en wisselende vitamine K-inname beïnvloeden het effect.</p>","image_url":"","wiki_title":"Acenocoumarol","match":"overdosering acenocoumarol","option_only":true},"vitamine k-antagonisten":{"title":"Fenprocoumon","short":"Fenprocoumon is een langwerkende cumarine (vitamine K-antagonist) voor antistolling; de dosering wordt gestuurd op de INR.","definition":"<p><strong>Fenprocoumon</strong> remt het enzym vitamine K-epoxidereductase, waardoor de lever minder functionele factoren II, VII, IX en X maakt. Het werkt traag en heeft een lange halfwaardetijd. De dosering wordt via de trombosedienst op geleide van de INR ingesteld. Er zijn veel interacties met voeding en geneesmiddelen; antidotum is vitamine K (en bij ernstige bloeding stollingsfactorconcentraat).</p>","image_url":"","wiki_title":"Phenprocoumon","match":"vitamine k-antagonisten","option_only":true},"aspirine in een lage dosering":{"title":"Acetylsalicylzuur","short":"Acetylsalicylzuur (aspirine) remt onomkeerbaar het enzym cyclo-oxygenase; in lage dosis remt het de bloedplaatjesaggregatie.","definition":"<p><strong>Acetylsalicylzuur</strong> acetyleert en remt <em>onomkeerbaar</em> het enzym cyclo-oxygenase (COX-1 en COX-2). Daardoor worden minder prostaglandinen en tromboxaan A<sub>2</sub> gevormd.</p><p>In lage dosis (80–100 mg) remt het via tromboxaan de bloedplaatjesaggregatie voor de hele levensduur van het plaatje (±7–10 dagen); dit wordt gebruikt ter preventie van hart- en vaatziekten. In hoge dosis werkt het pijnstillend, koortsverlagend en ontstekingsremmend. Bijwerkingen: maagulcera, bloedingen en bij kinderen het syndroom van Reye.</p>","image_url":"","wiki_title":"Aspirin","match":"aspirine in een lage dosering","option_only":true},"sarco&iuml;dose":{"title":"Sarcoïdose","short":"Sarcoïdose is een systemische aandoening van onbekende oorzaak met niet-verkazende granulomen, vooral in longen en lymfeklieren.","definition":"<p>Bij <strong>sarcoïdose</strong> zijn vaak de hilaire lymfeklieren en het longweefsel aangedaan; ook huid (erythema nodosum), ogen (uveïtis), hart en zenuwstelsel kunnen betrokken zijn. Het ACE en calcium kunnen verhoogd zijn. Het syndroom van Löfgren (koorts, erythema nodosum, hilaire klieren, enkelartritis) heeft een goede prognose.</p>","image_url":"","wiki_title":"Sarcoidosis","match":"sarco&iuml;dose","option_only":true},"bacteriële endocarditis met s. aureus":{"title":"Endocarditis","short":"Endocarditis is een infectie van het endocard, meestal van de hartkleppen, met vegetaties, koorts en een nieuw hartgeruis.","definition":"<p>Bij <strong>infectieuze endocarditis</strong> nestelen bacteriën (vaak <em>S. aureus</em>, streptokokken of enterokokken) zich op de hartkleppen en vormen vegetaties van bloedplaatjes, fibrine en micro-organismen.</p><p>Risicofactoren zijn klepafwijkingen, kunstkleppen en intraveneus drugsgebruik. Symptomen: koorts, een nieuw souffle en embolische verschijnselen (splinterbloedingen, Janewaylaesies, Oslernoduli, Rothvlekken). Diagnose via herhaalde bloedkweken en echocardiografie (Duke-criteria).</p>","image_url":"","wiki_title":"Infective endocarditis","match":"bacteriële endocarditis met s. aureus","option_only":true},"endocarditis lenta":{"title":"Endocarditis","short":"Endocarditis is een infectie van het endocard, meestal van de hartkleppen, met vegetaties, koorts en een nieuw hartgeruis.","definition":"<p>Bij <strong>infectieuze endocarditis</strong> nestelen bacteriën (vaak <em>S. aureus</em>, streptokokken of enterokokken) zich op de hartkleppen en vormen vegetaties van bloedplaatjes, fibrine en micro-organismen.</p><p>Risicofactoren zijn klepafwijkingen, kunstkleppen en intraveneus drugsgebruik. Symptomen: koorts, een nieuw souffle en embolische verschijnselen (splinterbloedingen, Janewaylaesies, Oslernoduli, Rothvlekken). Diagnose via herhaalde bloedkweken en echocardiografie (Duke-criteria).</p>","image_url":"","wiki_title":"Infective endocarditis","match":"endocarditis lenta","option_only":true},"glomerulaire filtratiesnelheid":{"title":"Nier","short":"De nieren filteren het bloed en regelen water-, zout- en zuur-base-evenwicht en bloeddruk; ook maken ze hormonen (renine, EPO, actief vitamine D).","definition":"<p>De <strong>nieren</strong> liggen retroperitoneaal aan weerszijden van de wervelkolom. De functionele eenheid is het <em>nefron</em>: glomerulus, proximale tubulus, lis van Henle, distale tubulus en verzamelbuis. Samen filteren de nieren ongeveer 180 liter per dag, waarvan meer dan 99% wordt teruggeresorbeerd.</p><p>Ze scheiden afvalstoffen (ureum, creatinine) en geneesmiddelen uit, regelen het volume en de samenstelling van de lichaamsvloeistoffen en de pH, en maken <em>renine</em> (bloeddruk), <em>erytropoëtine</em> (aanmaak van rode bloedcellen) en <em>calcitriol</em> (actief vitamine D).</p>","image_url":"","wiki_title":"Kidney","match":"glomerulaire filtratiesnelheid","option_only":true},"ernstige sepsis":{"title":"Sepsis","short":"Sepsis is een levensbedreigende orgaandisfunctie door een ontregelde afweerreactie op een infectie.","definition":"<p>Bij <strong>sepsis</strong> leidt de reactie van het lichaam op een infectie tot schade aan de eigen organen: hypotensie, verwardheid, snelle ademhaling, nierfalen, stollingsstoornissen en een verhoogd lactaat. Septische shock is sepsis met hypotensie die vasopressoren vereist. Snelle herkenning (bijv. qSOFA), bloedkweken, antibiotica binnen een uur en vochtresuscitatie zijn essentieel.</p>","image_url":"","wiki_title":"Sepsis","match":"ernstige sepsis","option_only":true},"longontsteking door sars-cov-2":{"title":"COVID-19","short":"COVID-19 is de ziekte veroorzaakt door het coronavirus SARS-CoV-2, met klachten van verkoudheid tot ernstige pneumonie.","definition":"<p><strong>COVID-19</strong> wordt veroorzaakt door <em>SARS-CoV-2</em>, een omhuld RNA-coronavirus dat via het spike-eiwit aan de ACE2-receptor bindt. Overdracht via druppels en aerosolen.</p><p>Het klinisch beeld varieert van geen klachten of verkoudheid tot een virale pneumonie met ARDS. Verlies van reuk en smaak was een opvallend symptoom. Risicofactoren voor een ernstig beloop zijn hoge leeftijd, obesitas en comorbiditeit.</p>","image_url":"","wiki_title":"COVID-19","match":"longontsteking door sars-cov-2","option_only":true},"creatinine kinase (ck)":{"title":"Creatinekinase (CK)","short":"Creatinekinase is een enzym uit spieren; een verhoogde bloedwaarde wijst op spierschade.","definition":"<p><strong>CK</strong> zet creatinefosfaat en ADP om in creatine en ATP. Het stijgt bij spierschade: rabdomyolyse, myositis, spierdystrofieën, na intensieve inspanning, trauma of injecties, en door statines. De CK-MB-vorm werd vroeger gebruikt bij hartinfarcten.</p>","image_url":"","wiki_title":"Creatine kinase","match":"creatinine kinase (ck)","option_only":true},"trigeminus neuralgie":{"title":"Trigeminusneuralgie","short":"Trigeminusneuralgie geeft korte, extreem hevige, schietende pijnaanvallen in een tak van de n. trigeminus, uitgelokt door aanraking, kauwen of praten.","definition":"<p><strong>Trigeminusneuralgie</strong> wordt meestal veroorzaakt door een bloedvat dat de zenuw bij de hersenstam drukt; bij jonge patiënten moet aan MS worden gedacht. Carbamazepine is het middel van eerste keus; bij onvoldoende effect een operatie (microvasculaire decompressie).</p>","image_url":"","wiki_title":"Trigeminal neuralgia","match":"trigeminus neuralgie|trigeminusneuralgie","option_only":true},"acuut leverfalen":{"title":"Acuut leverfalen","short":"Bij acuut leverfalen schiet de leverfunctie binnen enkele weken ernstig tekort, met stollingsstoornis en encefalopathie, zonder eerdere leverziekte.","definition":"<p>Oorzaken van <strong>acuut leverfalen</strong> zijn o.a. paracetamolintoxicatie, virale hepatitis (A, B, E), geneesmiddelen, auto-immuunhepatitis, de ziekte van Wilson en zwangerschapsgerelateerde ziekten. Kenmerken: icterus, een verlengde INR en hepatische encefalopathie. Snelle verwijzing naar een transplantatiecentrum is nodig.</p>","image_url":"","wiki_title":"Acute liver failure","match":"acuut leverfalen|fulminant leverfalen|leverfalen","option_only":true},"systemische lupus erythematosis":{"title":"Systemische lupus erythematosus (SLE)","short":"SLE is een systemische auto-immuunziekte met antinucleaire antistoffen en immuuncomplexen; gewrichten, huid, nieren en bloed kunnen aangedaan zijn.","definition":"<p><strong>Systemische lupus erythematosus</strong> is een chronische auto-immuunziekte die vooral jonge vrouwen treft. Er worden antistoffen gevormd tegen kerncomponenten (ANA, anti-dsDNA, anti-Sm), die met antigenen <em>immuuncomplexen</em> vormen die neerslaan in weefsels (type III-reactie) en complement verbruiken.</p><p>Kenmerken: artralgie/artritis, vlindervormig erytheem in het gezicht, fotosensitiviteit, serositis, nefritis, cytopenieën en neurologische verschijnselen. Behandeling met o.a. hydroxychloroquine, corticosteroïden en immunosuppressiva.</p>","image_url":"","wiki_title":"Systemic lupus erythematosus","match":"systemische lupus erythematosis","option_only":true},"systemisch lupus erythematosus":{"title":"Systemische lupus erythematosus (SLE)","short":"SLE is een systemische auto-immuunziekte met antinucleaire antistoffen en immuuncomplexen; gewrichten, huid, nieren en bloed kunnen aangedaan zijn.","definition":"<p><strong>Systemische lupus erythematosus</strong> is een chronische auto-immuunziekte die vooral jonge vrouwen treft. Er worden antistoffen gevormd tegen kerncomponenten (ANA, anti-dsDNA, anti-Sm), die met antigenen <em>immuuncomplexen</em> vormen die neerslaan in weefsels (type III-reactie) en complement verbruiken.</p><p>Kenmerken: artralgie/artritis, vlindervormig erytheem in het gezicht, fotosensitiviteit, serositis, nefritis, cytopenieën en neurologische verschijnselen. Behandeling met o.a. hydroxychloroquine, corticosteroïden en immunosuppressiva.</p>","image_url":"","wiki_title":"Systemic lupus erythematosus","match":"systemisch lupus erythematosus","option_only":true},"methotrexaat (een immunosuppressivum)":{"title":"Methotrexaat","short":"Methotrexaat is een foliumzuurantagonist; in lage dosis een basismiddel bij reumatoïde artritis en psoriasis, in hoge dosis een cytostaticum.","definition":"<p><strong>Methotrexaat</strong> remt dihydrofolaatreductase. In lage, wekelijkse dosering werkt het ontstekingsremmend (o.a. via adenosine) en is het een hoeksteen bij reumatoïde artritis, psoriasis en IBD; foliumzuur vermindert bijwerkingen. Bijwerkingen: beenmergsuppressie, levertoxiciteit, mucositis en pneumonitis. Het is teratogeen en wordt via de nier uitgescheiden.</p>","image_url":"","wiki_title":"Methotrexate","match":"methotrexaat (een immunosuppressivum)","option_only":true},"een beta-agonist":{"title":"Salbutamol","short":"Salbutamol is een kortwerkende β2-agonist die binnen minuten de luchtwegen verwijdt; gebruikt bij astma- en COPD-aanvallen.","definition":"<p><strong>Salbutamol</strong> ontspant de gladde spier van de bronchi via β2-receptoren en cAMP. Het werkt binnen enkele minuten en ongeveer 4–6 uur. Het wordt via een dosisaerosol met voorzetkamer of als verneveling gegeven. Bijwerkingen: tremor, tachycardie en een daling van het kalium (het wordt daarom ook gebruikt bij hyperkaliëmie).</p>","image_url":"","wiki_title":"Salbutamol","match":"een beta-agonist","option_only":true},"type 2 diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"type 2 diabetes mellitus","option_only":true},"essentiële trombocytose":{"title":"Essentiële trombocytemie","short":"Essentiële trombocytemie is een myeloproliferatieve ziekte met een blijvend sterk verhoogd aantal bloedplaatjes.","definition":"<p>Bij <strong>essentiële trombocytemie</strong> (vaak JAK2-, CALR- of MPL-mutatie) is er een verhoogd risico op trombose en, bij zeer hoge waarden, juist op bloedingen (verworven von Willebrand). Reactieve oorzaken (ijzergebrek, ontsteking, na splenectomie) moeten eerst worden uitgesloten. Behandeling met acetylsalicylzuur en soms hydroxycarbamide.</p>","image_url":"","wiki_title":"Essential thrombocythemia","match":"essentiële trombocytose|essentiële trombocytemie","option_only":true},"levothyroxine":{"title":"Levothyroxine","short":"Levothyroxine is synthetisch T4, gebruikt bij hypothyreoïdie.","definition":"<p><strong>Levothyroxine</strong> wordt nuchter ingenomen, omdat voedsel, calcium, ijzer en PPI's de opname verminderen. De dosis wordt aangepast op het TSH (bij primaire hypothyreoïdie). Overdosering geeft klachten van hyperthyreoïdie en op lange termijn boezemfibrilleren en botverlies.</p>","image_url":"","wiki_title":"Levothyroxine","match":"levothyroxine|thyrax|euthyrox","option_only":true},"een sglt2 remmer":{"title":"SGLT2-remmer","short":"SGLT2-remmers laten de nier glucose uitscheiden; ze verlagen de bloedglucose en beschermen hart en nieren.","definition":"<p><strong>SGLT2-remmers</strong> remmen de glucoseterugresorptie in de proximale tubulus. Naast glucoseverlaging (diabetes type 2) verminderen ze ziekenhuisopnames bij hartfalen en vertragen ze chronische nierschade. Bijwerkingen: genitale schimmelinfecties, volumedepletie en zeldzaam een euglykemische ketoacidose.</p>","image_url":"","wiki_title":"SGLT2 inhibitor","match":"een sglt2 remmer|sglt2-remmer|sglt2 remmer|empagliflozine|dapagliflozine","option_only":true},"fosfolipase a2":{"title":"Fosfolipase A2","short":"Fosfolipase A2 maakt arachidonzuur vrij uit membraanfosfolipiden, het startpunt voor prostaglandinen en leukotriënen.","definition":"<p>Door <strong>fosfolipase A2</strong> komt arachidonzuur beschikbaar voor cyclo-oxygenase (prostaglandinen, tromboxaan) en lipoxygenase (leukotriënen). Corticosteroïden remmen deze stap indirect. Fosfolipase A2-receptorantistoffen (PLA2R) spelen een rol bij membraneuze glomerulopathie.</p>","image_url":"","wiki_title":"Phospholipase A2","match":"fosfolipase a2|pla2","option_only":true},"beta2 glycoproteine 1":{"title":"β2-glycoproteïne I","short":"β2-glycoproteïne I is een plasma-eiwit waartegen bij het antifosfolipidensyndroom antistoffen worden gevormd.","definition":"<p>Antistoffen tegen <strong>β2-glycoproteïne I</strong> horen samen met anticardiolipine en lupus anticoagulans bij de laboratoriumcriteria van het antifosfolipidensyndroom (trombose en zwangerschapscomplicaties).</p>","image_url":"","wiki_title":"Apolipoprotein H","match":"beta2 glycoproteine 1|β2-glycoproteïne i|anti-beta2-glycoproteïne","option_only":true},"geactiveerd proteïne c":{"title":"Geactiveerd proteïne C","short":"Geactiveerd proteïne C is een natuurlijke antistollingsfactor die factor Va en VIIIa afbreekt.","definition":"<p>Proteïne C wordt geactiveerd door trombine gebonden aan trombomoduline op het endotheel; proteïne S is de cofactor. Bij <strong>APC-resistentie</strong> door factor V Leiden kan factor Va niet goed worden afgebroken, met een verhoogd tromboserisico.</p>","image_url":"","wiki_title":"Protein C","match":"geactiveerd proteïne c|apc","option_only":true},"pentasaccharide":{"title":"Fondaparinux (pentasacharide)","short":"Fondaparinux is een synthetisch pentasacharide dat via antitrombine selectief factor Xa remt.","definition":"<p><strong>Fondaparinux</strong> wordt subcutaan gegeven ter preventie en behandeling van trombose. Het geeft vrijwel geen HIT en kan bij een doorgemaakte HIT worden gebruikt. Het wordt via de nier uitgescheiden.</p>","image_url":"","wiki_title":"Fondaparinux","match":"pentasaccharide|pentasacharide|fondaparinux","option_only":true},"ticopidine":{"title":"Ticlopidine","short":"Ticlopidine is een oudere P2Y12-remmer (plaatjesremmer), vervangen door clopidogrel wegens ernstige bijwerkingen.","definition":"<p><strong>Ticlopidine</strong> kon neutropenie, aplastische anemie en TTP veroorzaken en wordt daarom nauwelijks meer gebruikt. Clopidogrel, prasugrel en ticagrelor werken via dezelfde receptor.</p>","image_url":"","wiki_title":"Ticlopidine","match":"ticopidine|ticlopidine","option_only":true},"factor v deficiëntie":{"title":"Factor V-deficiëntie","short":"Factor V-deficiëntie is een zeldzame erfelijke stollingsstoornis met een verlengde PT en APTT en een bloedingsneiging.","definition":"<p>Bij <strong>factor V-deficiëntie</strong> (parahemofilie, autosomaal recessief) zijn er slijmvliesbloedingen en nabloedingen na ingrepen. Het moet niet verward worden met factor V Leiden, waarbij factor V juist minder goed wordt afgebroken en de tromboseneiging is verhoogd.</p>","image_url":"","wiki_title":"Factor V deficiency","match":"factor v deficiëntie|factor v-deficiëntie","option_only":true},"hyperhomocysteïnemie":{"title":"Hyperhomocysteïnemie","short":"Hyperhomocysteïnemie is een verhoogd homocysteïne in het bloed, door een tekort aan B12, foliumzuur of B6 of een erfelijk enzymdefect.","definition":"<p>Een verhoogd <strong>homocysteïne</strong> is geassocieerd met hart- en vaatziekten en trombose. Bij een B12-tekort is daarnaast het methylmalonzuur verhoogd. Homocystinurie (cystathionine-β-synthasedeficiëntie) geeft een Marfan-achtig beeld met lensluxatie naar beneden en trombose.</p>","image_url":"","wiki_title":"Hyperhomocysteinemia","match":"hyperhomocysteïnemie|homocysteïne","option_only":true},"malabsorptie":{"title":"Malabsorptie","short":"Bij malabsorptie worden voedingsstoffen onvoldoende uit de darm opgenomen, met diarree, gewichtsverlies en tekorten.","definition":"<p>Oorzaken van <strong>malabsorptie</strong> zijn o.a. coeliakie, exocriene pancreasinsufficiëntie, galzuurtekort (cholestase, ileumresectie), de ziekte van Crohn, bacteriële overgroei en lactasedeficiëntie. Vetmalabsorptie geeft steatorroe en tekorten aan de vetoplosbare vitamines A, D, E en K.</p>","image_url":"","wiki_title":"Malabsorption","match":"malabsorptie|malabsorptiesyndroom","option_only":true},"waterintoxicatie":{"title":"Waterintoxicatie","short":"Waterintoxicatie is een ernstige hyponatriëmie door het drinken van zeer veel water, met risico op hersenoedeem.","definition":"<p><strong>Waterintoxicatie</strong> komt voor bij psychogene polydipsie, duursporters die veel water drinken, ecstasygebruik (extra ADH) en kinderen die verdunde voeding krijgen. Klachten: hoofdpijn, misselijkheid, verwardheid, insulten en coma.</p>","image_url":"","wiki_title":"Water intoxication","match":"waterintoxicatie|watervergiftiging","option_only":true},"isovolumetrische contractiefase":{"title":"Isovolumetrische contractiefase","short":"In de isovolumetrische contractiefase trekt de ventrikel samen terwijl alle kleppen gesloten zijn: de druk stijgt snel, het volume blijft gelijk.","definition":"<p>Pas als de ventrikeldruk de druk in aorta of a. pulmonalis overstijgt, gaan de semilunaire kleppen open en volgt de ejectiefase.</p>","image_url":"","wiki_title":"Isovolumetric contraction","match":"isovolumetrische contractiefase|isovolumetrische contractie","option_only":true},"pulmonalisklep":{"title":"Pulmonalisklep","short":"De pulmonalisklep ligt tussen de rechterventrikel en de longslagader en heeft drie halvemaanvormige slippen.","definition":"<p>De <strong>pulmonalisklep</strong> sluit aan het begin van de diastole (P2-component van de tweede harttoon). Bij inademing sluit hij iets later, wat een fysiologische splijting van de tweede toon geeft. Aandoeningen zijn pulmonalisstenose (vaak aangeboren) en pulmonalisinsufficiëntie (bijv. na Fallot-correctie of bij pulmonale hypertensie).</p>","image_url":"","wiki_title":"Pulmonary valve","match":"pulmonalisklep|pulmonaalklep","option_only":true},"tricuspidalisklep":{"title":"Tricuspidalisklep","short":"De tricuspidalisklep ligt tussen het rechteratrium en de rechterventrikel en heeft drie slippen.","definition":"<p>Insufficiëntie van de <strong>tricuspidalisklep</strong> komt vaak secundair voor bij verwijding van de rechterventrikel (pulmonale hypertensie, linkszijdig hartfalen). Endocarditis van de tricuspidalisklep komt vooral voor bij intraveneus drugsgebruik. Ebstein-anomalie is een aangeboren afwijking van deze klep.</p>","image_url":"","wiki_title":"Tricuspid valve","match":"tricuspidalisklep","option_only":true},"aortaklep":{"title":"Aortaklep","short":"De aortaklep ligt tussen de linkerventrikel en de aorta en heeft normaal drie halvemaanvormige slippen.","definition":"<p>Vlak boven de <strong>aortaklep</strong> ontspringen de kransslagaders. Bij ongeveer 1–2% van de mensen is de klep bicuspide, wat eerder tot stenose of insufficiëntie leidt en samengaat met verwijding van de aorta ascendens.</p>","image_url":"","wiki_title":"Aortic valve","match":"aortaklep","option_only":true},"ventriculaire extrasystolen":{"title":"Ventriculaire extrasystolen (VES)","short":"Ventriculaire extrasystolen zijn vroegtijdige hartslagen die uit de kamers ontstaan, met een breed QRS-complex.","definition":"<p>Losse <strong>VES</strong> komen bij veel gezonde mensen voor en worden gevoeld als een overgeslagen of harde slag. Uitlokkers zijn cafeïne, alcohol, stress en slaaptekort. Bij veel VES, klachten of onderliggende hartziekte is verder onderzoek nodig; zeer frequente VES kunnen de pompfunctie verminderen.</p>","image_url":"","wiki_title":"Premature ventricular contraction","match":"ventriculaire extrasystolen|ves|ventriculaire extrasystole","option_only":true},"supraventriculaire extrasystolen":{"title":"Supraventriculaire extrasystolen","short":"Supraventriculaire extrasystolen zijn vroegtijdige slagen uit de boezems of AV-knoop, met een vroege P-top en meestal een smal QRS.","definition":"<p><strong>Atriale extrasystolen</strong> zijn meestal onschuldig. Ze kunnen een aanval van boezemfibrilleren of een supraventriculaire tachycardie uitlokken.</p>","image_url":"","wiki_title":"Premature atrial contraction","match":"supraventriculaire extrasystolen|atriale extrasystolen|aes","option_only":true},"av-nodale re-entry tachycardie":{"title":"AV-nodale re-entrytachycardie (AVNRT)","short":"AVNRT is een snelle, regelmatige smalcomplex-tachycardie door een kringstroom in en rond de AV-knoop.","definition":"<p><strong>AVNRT</strong> komt vaker voor bij jonge vrouwen en begint en eindigt plotseling, met hartkloppingen, soms ‘kikkerteken’ (pulsaties in de hals). Vagale manoeuvres of adenosine kunnen de aanval beëindigen; ablatie geneest het meestal.</p>","image_url":"","wiki_title":"AV nodal reentrant tachycardia","match":"av-nodale re-entry tachycardie|avnrt|supraventriculaire tachycardie|svt-aanval","option_only":true},"non-compaction cardiomyopathie (nccmp)":{"title":"Non-compactioncardiomyopathie","short":"Bij non-compactioncardiomyopathie heeft de linkerventrikelwand een sponsachtige laag met diepe trabekels, door een gestoorde ontwikkeling.","definition":"<p><strong>Non-compaction</strong> kan zonder klachten blijven of leiden tot hartfalen, ritmestoornissen en trombo-embolie. Het is vaak erfelijk; familieonderzoek wordt aangeraden. Diagnose met echo of cardiale MRI.</p>","image_url":"","wiki_title":"Left ventricular non-compaction","match":"non-compaction cardiomyopathie (nccmp)|non-compaction cardiomyopathie|nccmp","option_only":true},"granulomatosis met polyangiitis (gpa)":{"title":"Granulomatose met polyangiitis (GPA)","short":"GPA is een ANCA-geassocieerde vasculitis van kleine vaten met granulomen, vooral in bovenste luchtwegen, longen en nieren.","definition":"<p>Bij <strong>GPA</strong> zijn er klachten van neus en bijholten (korsten, bloedingen, zadelneus), longnoduli of -bloedingen en een snel progressieve glomerulonefritis. Meestal zijn er c-ANCA (anti-PR3). Behandeling met hoge dosis corticosteroïden en rituximab of cyclofosfamide.</p>","image_url":"","wiki_title":"Granulomatosis with polyangiitis","match":"granulomatosis met polyangiitis (gpa)|granulomatose met polyangiitis|gpa|ziekte van wegener","option_only":true},"microscopische angiitis (mpa)":{"title":"Microscopische polyangiitis","short":"Microscopische polyangiitis is een ANCA-geassocieerde vasculitis van kleine vaten zonder granulomen, vaak met nier- en longbetrokkenheid.","definition":"<p>Bij <strong>MPA</strong> zijn er meestal p-ANCA (anti-MPO). Klinisch: glomerulonefritis, longbloedingen, mononeuritis multiplex en huidafwijkingen, zonder de KNO-betrokkenheid en granulomen van GPA.</p>","image_url":"","wiki_title":"Microscopic polyangiitis","match":"microscopische angiitis (mpa)|microscopische polyangiitis|mpa","option_only":true},"syndroom van goodpasture":{"title":"Anti-GBM-ziekte (syndroom van Goodpasture)","short":"Bij anti-GBM-ziekte vallen antistoffen tegen collageen type IV de glomerulaire en alveolaire basaalmembraan aan, met glomerulonefritis en longbloedingen.","definition":"<p>Het <strong>syndroom van Goodpasture</strong> geeft een snel progressieve glomerulonefritis en soms hemoptoë. In het nierbiopt is een lineaire IgG-afzetting langs de GBM te zien. Behandeling met plasmaferese, corticosteroïden en cyclofosfamide.</p>","image_url":"","wiki_title":"Anti-glomerular basement membrane disease","match":"syndroom van goodpasture|goodpasture|anti-gbm-ziekte","option_only":true},"vasoconstrictie":{"title":"Vasoconstrictie","short":"Vasoconstrictie is vernauwing van bloedvaten door samentrekking van de gladde spier in de vaatwand.","definition":"<p><strong>Vasoconstrictie</strong> wordt veroorzaakt door o.a. sympathische activatie (α1), angiotensine II, endotheline, vasopressine en kou. Het verhoogt de bloeddruk en stuurt bloed naar vitale organen, bijvoorbeeld bij bloedverlies. In de long trekken vaten juist samen bij hypoxie.</p>","image_url":"","wiki_title":"Vasoconstriction","match":"vasoconstrictie|vaatvernauwing|perifere vasoconstrictie","option_only":true},"crepiteren":{"title":"Crepitaties","short":"Crepitaties zijn fijne of grove knisperende bijgeluiden bij het luisteren naar de longen, vooral tijdens de inademing.","definition":"<p><strong>Fijne crepitaties</strong> (laat-inspiratoir, ‘klittenband’) passen bij longfibrose en beginnend longoedeem; <strong>grovere</strong> bij pneumonie, longoedeem of bronchiëctasieën. Ook bij gewrichten en onderhuids (emfyseem) spreekt men van crepitaties.</p>","image_url":"","wiki_title":"Crackles","match":"crepiteren|crepitaties|crepitatie","option_only":true},"endarteriëctomie":{"title":"Endarteriëctomie","short":"Bij een endarteriëctomie wordt een atherosclerotische plaque uit een slagader verwijderd, bijv. uit de a. carotis interna.","definition":"<p>Een <strong>carotisendarteriëctomie</strong> verlaagt bij een ernstige symptomatische stenose het risico op een nieuw herseninfarct, mits ze snel (binnen twee weken) na de TIA of het infarct wordt uitgevoerd. Een alternatief is het plaatsen van een stent.</p>","image_url":"","wiki_title":"Carotid endarterectomy","match":"endarteriëctomie|carotisendarteriëctomie","option_only":true},"auto immuun hemolytische anemie":{"title":"Auto-immuun hemolytische anemie","short":"Bij AIHA maakt het lichaam antistoffen tegen de eigen rode bloedcellen, die daardoor worden afgebroken; de directe antiglobulinetest (Coombs) is positief.","definition":"<p>Bij <strong>auto-immuun hemolytische anemie</strong> binden auto-antistoffen aan erytrocyten, die vervolgens vooral in de milt worden afgebroken (type II-overgevoeligheid). Bij <em>warme</em> AIHA gaat het om IgG; bij <em>koude</em> AIHA om IgM met complementactivatie.</p><p>Laboratorium: anemie met verhoogde reticulocyten, verhoogd LDH en ongeconjugeerd bilirubine, verlaagd haptoglobine, sferocyten en een positieve directe antiglobulinetest (Coombs). Oorzaken: idiopathisch, lymfoproliferatieve ziekten, SLE, infecties (Mycoplasma, EBV) of geneesmiddelen.</p>","image_url":"","wiki_title":"Autoimmune hemolytic anemia","match":"auto immuun hemolytische anemie","option_only":true},"verhoogd lactaatdehydrogenase (ld)":{"title":"Lactaatdehydrogenase (LDH)","short":"LDH is een enzym in vrijwel alle cellen dat pyruvaat en lactaat in elkaar omzet; een verhoogde bloedwaarde wijst op celschade.","definition":"<p><strong>Lactaatdehydrogenase</strong> zet pyruvaat om in lactaat (en omgekeerd) en regenereert daarbij NAD⁺, wat anaerobe glycolyse mogelijk maakt. In het bloed is LDH een aspecifieke marker van weefselschade: het is verhoogd bij hemolyse, myocardinfarct, leverschade, spierschade en snelgroeiende tumoren zoals lymfomen.</p>","image_url":"","wiki_title":"Lactate dehydrogenase","match":"verhoogd lactaatdehydrogenase (ld)","option_only":true},"proteïne s tekort":{"title":"Proteïne S-deficiëntie","short":"Proteïne S is de cofactor van geactiveerd proteïne C; een tekort geeft een verhoogd risico op veneuze trombose.","definition":"<p>Een <strong>proteïne S-tekort</strong> kan erfelijk zijn of verworven (zwangerschap, oestrogenen, leverziekte, vitamine K-antagonisten). Het hoort bij de erfelijke trombofilieën, samen met proteïne C- en antitrombinedeficiëntie, factor V Leiden en de protrombinemutatie.</p>","image_url":"","wiki_title":"Protein S deficiency","match":"proteïne s tekort|proteine s deficiëntie|proteïne s-deficiëntie","option_only":true},"tetralogie van fallot":{"title":"Tetralogie van Fallot","short":"De tetralogie van Fallot is de meest voorkomende cyanotische aangeboren hartafwijking: VSD, overrijdende aorta, pulmonalisstenose en rechterventrikelhypertrofie.","definition":"<p>Bij <strong>Fallot</strong> stroomt zuurstofarm bloed via het VSD naar de aorta (rechts-linksshunt). Kenmerkend zijn ‘tet spells’ die verbeteren bij hurken en een laarsvormig hart op de X-thorax. Chirurgische correctie gebeurt meestal in het eerste levensjaar.</p>","image_url":"","wiki_title":"Tetralogy of Fallot","match":"tetralogie van fallot|fallot","option_only":true},"feochromocytoom":{"title":"Feochromocytoom","short":"Een feochromocytoom is een catecholamineproducerende tumor van het bijniermerg, met aanvallen van hoofdpijn, zweten en hartkloppingen bij hoge bloeddruk.","definition":"<p>Een <strong>feochromocytoom</strong> geeft paroxismale of aanhoudende hypertensie. Diagnose met metanefrines in plasma of urine, daarna beeldvorming. Vóór de operatie wordt eerst een alfablokker en daarna pas een bètablokker gegeven. Het kan erfelijk zijn (MEN2, VHL, NF1).</p>","image_url":"","wiki_title":"Pheochromocytoma","match":"feochromocytoom|paraganglioom","option_only":true},"subarachnoïdale bloeding":{"title":"Subarachnoïdale bloeding (SAB)","short":"Een subarachnoïdale bloeding is een bloeding tussen de hersenvliezen, meestal door een gescheurd aneurysma, met plotselinge zeer hevige hoofdpijn.","definition":"<p>Een <strong>SAB</strong> geeft binnen seconden de ergste hoofdpijn ooit (‘donderslag’), vaak met braken, nekstijfheid en bewustzijnsdaling. Diagnose met CT, zo nodig gevolgd door een lumbaalpunctie (xanthochromie). Complicaties: nabloeding, vasospasme met infarcten en hydrocefalus. Het aneurysma wordt gecoild of geclipt.</p>","image_url":"","wiki_title":"Subarachnoid hemorrhage","match":"subarachnoïdale bloeding|sab|subarachnoidale bloeding","option_only":true},"berry-aneurysmata":{"title":"Sacculaire (bes)aneurysmata","short":"Besaneurysmata zijn zakvormige uitstulpingen van hersenslagaders, meestal bij vertakkingen van de cirkel van Willis.","definition":"<p><strong>Sacculaire aneurysmata</strong> liggen vaak bij de a. communicans anterior, a. communicans posterior en de splitsing van de a. cerebri media. Risicofactoren zijn roken, hypertensie, familiaire belasting, polycysteuze nierziekte en bindweefselziekten. Ruptuur geeft een subarachnoïdale bloeding; een aneurysma van de a. communicans posterior kan een oculomotoriusparese geven.</p>","image_url":"","wiki_title":"Intracranial aneurysm","match":"berry-aneurysmata|besaneurysma|sacculair aneurysma","option_only":true},"coarctatio aortae":{"title":"Coarctatio aortae","short":"Coarctatio aortae is een aangeboren vernauwing van de aorta, meestal net voorbij de a. subclavia sinistra.","definition":"<p>Bij <strong>coarctatie</strong> is de bloeddruk in de armen hoger dan in de benen, met zwakke of vertraagde liespolsen. Bij oudere kinderen en volwassenen ontstaan collateralen via de intercostale arteriën (ribusuren op de foto). Het komt vaker voor bij het syndroom van Turner en een bicuspide aortaklep.</p>","image_url":"","wiki_title":"Coarctation of the aorta","match":"coarctatio aortae|aortacoarctatie","option_only":true},"mycotisch aneurysma":{"title":"Mycotisch aneurysma","short":"Een mycotisch aneurysma is een aneurysma door een infectie van de vaatwand, meestal bacterieel (bijv. bij endocarditis).","definition":"<p>Ondanks de naam wordt een <strong>mycotisch aneurysma</strong> meestal door bacteriën veroorzaakt, zoals <em>S. aureus</em> en <em>Salmonella</em>. Septische emboli bij endocarditis kunnen in hersenslagaders aneurysmata vormen die kunnen scheuren.</p>","image_url":"","wiki_title":"Mycotic aneurysm","match":"mycotisch aneurysma|infectieus aneurysma","option_only":true},"arterioveneuze fistels":{"title":"Arterioveneuze fistel","short":"Een arterioveneuze fistel is een directe verbinding tussen een slagader en een ader, zonder capillairbed.","definition":"<p>Een <strong>AV-fistel</strong> kan aangeboren zijn (malformatie), door trauma ontstaan of chirurgisch worden aangelegd als toegang voor hemodialyse. Grote shunts kunnen high-output hartfalen geven. Arterioveneuze malformaties in het brein kunnen bloeden of epilepsie veroorzaken.</p>","image_url":"","wiki_title":"Arteriovenous fistula","match":"arterioveneuze fistels|arterioveneuze fistel|av-fistel|arterioveneuze anastomosen|arterioveneuze malformatie","option_only":true},"syndroom van ehlers-danlos":{"title":"Syndroom van Ehlers-Danlos","short":"Het syndroom van Ehlers-Danlos is een groep erfelijke bindweefselziekten met hypermobiele gewrichten, rekbare huid en kwetsbaar weefsel.","definition":"<p>Bij <strong>Ehlers-Danlos</strong> is de collageenvorming of -verwerking gestoord. De hypermobiele vorm is het meest voorkomend; de vasculaire vorm (collageen type III) is het gevaarlijkst, met spontane ruptuur van slagaders, darm of uterus. Klachten: luxaties, snel blauwe plekken en slechte wondgenezing met brede littekens.</p>","image_url":"","wiki_title":"Ehlers–Danlos syndromes","match":"syndroom van ehlers-danlos|ehlers en danlos|ehlers-danlos|één van de ehlers-danlos syndromen (eds)|eds","option_only":true},"endothelinereceptorblokker":{"title":"Endothelinereceptorantagonist","short":"Endothelinereceptorantagonisten (zoals bosentan) blokkeren het vaatvernauwende endotheline en worden gebruikt bij pulmonale arteriële hypertensie.","definition":"<p><strong>Endothelinereceptorblokkers</strong> verlagen de weerstand in de longvaten. Ze zijn teratogeen (betrouwbare anticonceptie nodig) en kunnen leverschade en vochtretentie geven. Andere middelen bij pulmonale arteriële hypertensie zijn PDE5-remmers en prostacycline-analogen.</p>","image_url":"","wiki_title":"Endothelin receptor antagonist","match":"endothelinereceptorblokker|bosentan|macitentan","option_only":true},"epoprostenol (een prostacycline-analoog)":{"title":"Prostacycline-analogen","short":"Prostacycline-analogen zoals epoprostenol verwijden de longvaten en remmen plaatjesaggregatie; gebruikt bij ernstige pulmonale arteriële hypertensie.","definition":"<p><strong>Epoprostenol</strong> heeft een zeer korte halfwaardetijd en moet continu intraveneus worden gegeven via een pomp; plotseling stoppen kan een levensbedreigende terugslag geven. Bijwerkingen: flushing, hoofdpijn, kaakpijn en diarree.</p>","image_url":"","wiki_title":"Prostacyclin","match":"epoprostenol (een prostacycline-analoog)|epoprostenol|prostacycline-analoog","option_only":true},"nicotinezuur":{"title":"Nicotinezuur (niacine)","short":"Nicotinezuur (vitamine B3) is bouwsteen van NAD; in hoge dosis verlaagt het triglyceriden en LDL en verhoogt het HDL.","definition":"<p>Als lipidenverlager werd <strong>niacine</strong> nauwelijks meer gebruikt omdat het in studies geen extra cardiovasculair voordeel gaf en veel bijwerkingen had (flushing, hyperglykemie, jicht). Een tekort aan niacine geeft pellagra: dermatitis, diarree en dementie.</p>","image_url":"","wiki_title":"Niacin","match":"nicotinezuur|niacine|vitamine b3","option_only":true},"evolocumab (een pcsk-9 remmer)":{"title":"PCSK9-remmer","short":"PCSK9-remmers zijn antistoffen die het LDL-cholesterol sterk verlagen door afbraak van LDL-receptoren te voorkomen.","definition":"<p>PCSK9 bevordert de afbraak van de LDL-receptor in de lever. Door <strong>PCSK9-remming</strong> blijven meer receptoren beschikbaar en daalt het LDL met ongeveer 60%. Ze worden subcutaan gegeven bij familiaire hypercholesterolemie of als LDL-streefwaarden met statines en ezetimib niet worden gehaald.</p>","image_url":"","wiki_title":"PCSK9 inhibitor","match":"evolocumab (een pcsk-9 remmer)|evolocumab|pcsk9-remmer|alirocumab","option_only":true},"ezetimib":{"title":"Ezetimib","short":"Ezetimib remt de opname van cholesterol in de dunne darm en verlaagt zo het LDL-cholesterol.","definition":"<p><strong>Ezetimib</strong> blokkeert het transporteiwit NPC1L1 in de darmwand. Het verlaagt het LDL met ongeveer 20% en wordt vaak met een statine gecombineerd. Het wordt goed verdragen.</p>","image_url":"","wiki_title":"Ezetimibe","match":"ezetimib|ezetimibe","option_only":true},"apixaban":{"title":"Apixaban (DOAC)","short":"Apixaban is een direct werkend oraal anticoagulans (DOAC) dat factor Xa remt.","definition":"<p><strong>DOAC's</strong> (factor Xa-remmers apixaban, rivaroxaban en edoxaban, en de trombineremmer dabigatran) worden gebruikt bij boezemfibrilleren en veneuze trombose. Ze hebben een snelle werking, weinig interacties en hoeven niet met INR te worden gecontroleerd. Bij kunstkleppen en ernstige nierfunctiestoornis zijn cumarines de keuze. Antidota: andexanet alfa (Xa-remmers) en idarucizumab (dabigatran).</p>","image_url":"","wiki_title":"Apixaban","match":"apixaban|rivaroxaban|edoxaban|doac|doac's|noac","option_only":true},"gebruik van dabigatran":{"title":"Dabigatran","short":"Dabigatran is een direct werkende trombineremmer (DOAC) die grotendeels via de nier wordt uitgescheiden.","definition":"<p><strong>Dabigatran</strong> wordt gebruikt bij boezemfibrilleren en veneuze trombose. Bij een verminderde nierfunctie hoopt het op, met risico op bloedingen. Het effect kan snel worden opgeheven met het antilichaamfragment idarucizumab.</p>","image_url":"","wiki_title":"Dabigatran","match":"gebruik van dabigatran|dabigatran|overdosering dabigatran","option_only":true},"hypertrofische cardiomyopathie (hcm)":{"title":"Hypertrofische cardiomyopathie (HCM)","short":"HCM is een erfelijke hartspierziekte met abnormaal verdikte linkerventrikelwand, vaak vooral het septum.","definition":"<p>Bij <strong>HCM</strong> (meestal mutaties in sarcomeereiwitten, autosomaal dominant) kan de uitstroombaan van de linkerventrikel vernauwd raken, met een geruis dat toeneemt bij persen of staan. Klachten: kortademigheid, pijn op de borst, syncope; het is een belangrijke oorzaak van plotse dood bij jonge sporters. Familieonderzoek is nodig.</p>","image_url":"","wiki_title":"Hypertrophic cardiomyopathy","match":"hypertrofische cardiomyopathie (hcm)|hypertrofische cardiomyopathie|hcm","option_only":true},"linkerventrikelhypertrofie":{"title":"Linkerventrikelhypertrofie","short":"Linkerventrikelhypertrofie is een verdikking van de wand van de linkerkamer, meestal door langdurige drukbelasting.","definition":"<p><strong>LVH</strong> ontstaat bij hypertensie, aortaklepstenose, HCM en training (sporthart). Ze geeft diastolische disfunctie en is een sterke risicofactor voor hartfalen, ritmestoornissen en plotse dood. Zichtbaar op ECG (verhoogde voltages) en echo.</p>","image_url":"","wiki_title":"Left ventricular hypertrophy","match":"linkerventrikelhypertrofie|lvh","option_only":true},"ventrikelflutter":{"title":"Ventrikelflutter","short":"Ventrikelflutter is een zeer snelle, regelmatige ventriculaire tachycardie (zonder herkenbare QRS-T) die snel overgaat in ventrikelfibrilleren.","definition":"<p>Bij <strong>ventrikelflutter</strong> is er vrijwel geen effectieve circulatie; behandeling zoals bij een circulatiestilstand met defibrillatie. Torsade de pointes is een polymorfe VT bij een verlengd QT-interval, behandeld met magnesium.</p>","image_url":"","wiki_title":"Ventricular flutter","match":"ventrikelflutter|torsade de pointes","option_only":true},"stabiele angina pectoris":{"title":"Stabiele angina pectoris","short":"Bij stabiele angina pectoris ontstaat bij inspanning een drukkende pijn op de borst door een vernauwde kransslagader, die in rust binnen minuten verdwijnt.","definition":"<p><strong>Angina pectoris</strong> ontstaat als het zuurstofaanbod tekortschiet bij een verhoogde vraag. Uitlokkers: inspanning, kou, emoties en maaltijden. Behandeling: nitroglycerine bij een aanval, bètablokkers of calciumantagonisten, acetylsalicylzuur en een statine; bij ernstige klachten een PCI of bypassoperatie. Bij pijn in rust of toenemende klachten spreekt men van instabiele angina.</p>","image_url":"","wiki_title":"Angina","match":"stabiele angina pectoris|angina pectoris","option_only":true},"acuut coronair syndroom":{"title":"Acuut coronair syndroom (ACS)","short":"Het acuut coronair syndroom omvat instabiele angina pectoris, NSTEMI en STEMI, alle door een acute verstoring van de kransslagaderdoorbloeding.","definition":"<p>Bij <strong>ACS</strong> scheurt meestal een atherosclerotische plaque, gevolgd door trombose. Onderscheid op basis van ECG (ST-elevatie of niet) en troponine (wel of geen myocardschade). Behandeling: plaatjesremmers, antistolling en, afhankelijk van het type, spoed- of vroege PCI.</p>","image_url":"","wiki_title":"Acute coronary syndrome","match":"acuut coronair syndroom|acs","option_only":true},"claudicatio intermittens":{"title":"Claudicatio intermittens","short":"Claudicatio intermittens is pijn in de kuit of bil bij lopen die bij stilstaan verdwijnt, door perifeer arterieel vaatlijden.","definition":"<p>Bij <strong>claudicatio</strong> zijn de beenarteriën vernauwd door atherosclerose. De enkel-armindex is verlaagd (&lt;0,9). Behandeling: stoppen met roken, gesuperviseerde looptraining, een plaatjesremmer en statine; bij ernstige klachten of kritieke ischemie (rustpijn, wonden) revascularisatie.</p>","image_url":"","wiki_title":"Intermittent claudication","match":"claudicatio intermittens|etalagebenen|perifeer arterieel vaatlijden","option_only":true},"oligurie":{"title":"Oligurie","short":"Oligurie is een verminderde urineproductie, bij volwassenen minder dan ongeveer 400 ml per dag of 0,5 ml/kg per uur.","definition":"<p><strong>Oligurie</strong> kan prerenaal (ondervulling, shock), renaal (acute tubulusnecrose, glomerulonefritis) of postrenaal (obstructie) zijn. Bij anurie (vrijwel geen urine) moet direct een obstructie, zoals een verstopte katheter, worden uitgesloten.</p>","image_url":"","wiki_title":"Oliguria","match":"oligurie|anurie","option_only":true},"echocardiografie":{"title":"Echocardiografie","short":"Echocardiografie is een echo van het hart, waarmee structuur, kleppen en pompfunctie worden beoordeeld.","definition":"<p>Met <strong>echocardiografie</strong> worden o.a. de ejectiefractie, wanddikte, klepafwijkingen, pericardvocht en aangeboren afwijkingen beoordeeld. Een transoesofageale echo geeft betere beelden van kleppen en het linkerhartoor (endocarditis, stolsels).</p>","image_url":"","wiki_title":"Echocardiography","match":"echocardiografie|echo hart|cardiale echo","option_only":true},"systemische lupus erythematodes (sle)":{"title":"Systemische lupus erythematosus (SLE)","short":"SLE is een systemische auto-immuunziekte met antinucleaire antistoffen en immuuncomplexen; gewrichten, huid, nieren en bloed kunnen aangedaan zijn.","definition":"<p><strong>Systemische lupus erythematosus</strong> is een chronische auto-immuunziekte die vooral jonge vrouwen treft. Er worden antistoffen gevormd tegen kerncomponenten (ANA, anti-dsDNA, anti-Sm), die met antigenen <em>immuuncomplexen</em> vormen die neerslaan in weefsels (type III-reactie) en complement verbruiken.</p><p>Kenmerken: artralgie/artritis, vlindervormig erytheem in het gezicht, fotosensitiviteit, serositis, nefritis, cytopenieën en neurologische verschijnselen. Behandeling met o.a. hydroxychloroquine, corticosteroïden en immunosuppressiva.</p>","image_url":"","wiki_title":"Systemic lupus erythematosus","match":"systemische lupus erythematodes (sle)","option_only":true},"systemische lupus erythematodes":{"title":"Systemische lupus erythematosus (SLE)","short":"SLE is een systemische auto-immuunziekte met antinucleaire antistoffen en immuuncomplexen; gewrichten, huid, nieren en bloed kunnen aangedaan zijn.","definition":"<p><strong>Systemische lupus erythematosus</strong> is een chronische auto-immuunziekte die vooral jonge vrouwen treft. Er worden antistoffen gevormd tegen kerncomponenten (ANA, anti-dsDNA, anti-Sm), die met antigenen <em>immuuncomplexen</em> vormen die neerslaan in weefsels (type III-reactie) en complement verbruiken.</p><p>Kenmerken: artralgie/artritis, vlindervormig erytheem in het gezicht, fotosensitiviteit, serositis, nefritis, cytopenieën en neurologische verschijnselen. Behandeling met o.a. hydroxychloroquine, corticosteroïden en immunosuppressiva.</p>","image_url":"","wiki_title":"Systemic lupus erythematosus","match":"systemische lupus erythematodes","option_only":true},"granulomatosis en polyangiitis":{"title":"Granulomatose met polyangiitis (GPA)","short":"GPA is een ANCA-geassocieerde vasculitis van kleine vaten met granulomen, vooral in bovenste luchtwegen, longen en nieren.","definition":"<p>Bij <strong>GPA</strong> zijn er klachten van neus en bijholten (korsten, bloedingen, zadelneus), longnoduli of -bloedingen en een snel progressieve glomerulonefritis. Meestal zijn er c-ANCA (anti-PR3). Behandeling met hoge dosis corticosteroïden en rituximab of cyclofosfamide.</p>","image_url":"","wiki_title":"Granulomatosis with polyangiitis","match":"granulomatosis en polyangiitis","option_only":true},"reuscelartritis":{"title":"Arteriitis temporalis (reuscelarteriitis)","short":"Arteriitis temporalis is een granulomateuze vasculitis van grote en middelgrote arteriën bij ouderen, met risico op blindheid.","definition":"<p>Bij <strong>reuscelarteriitis</strong> zijn vooral takken van de a. carotis externa (zoals de a. temporalis) en soms de aorta en haar takken ontstoken. Klachten: nieuwe hoofdpijn, gevoelige slaapslagader, kauwclaudicatie, visusstoornissen en algemene malaise, met een sterk verhoogde BSE/CRP. Bij verdenking direct hoge dosis prednison om blindheid te voorkomen; diagnose met echo of biopt.</p>","image_url":"","wiki_title":"Giant cell arteritis","match":"reuscelartritis","option_only":true},"reuscelvasculitis":{"title":"Arteriitis temporalis (reuscelarteriitis)","short":"Arteriitis temporalis is een granulomateuze vasculitis van grote en middelgrote arteriën bij ouderen, met risico op blindheid.","definition":"<p>Bij <strong>reuscelarteriitis</strong> zijn vooral takken van de a. carotis externa (zoals de a. temporalis) en soms de aorta en haar takken ontstoken. Klachten: nieuwe hoofdpijn, gevoelige slaapslagader, kauwclaudicatie, visusstoornissen en algemene malaise, met een sterk verhoogde BSE/CRP. Bij verdenking direct hoge dosis prednison om blindheid te voorkomen; diagnose met echo of biopt.</p>","image_url":"","wiki_title":"Giant cell arteritis","match":"reuscelvasculitis","option_only":true},"bèta-blokkers":{"title":"Bètablokker","short":"Bètablokkers blokkeren bèta-adrenerge receptoren en verlagen hartfrequentie, contractiekracht en reninesecretie.","definition":"<p><strong>Bètablokkers</strong> worden gebruikt bij hypertensie, angina pectoris, na een hartinfarct, bij hartfalen, ritmestoornissen, tremor en migraineprofylaxe. Cardioselectieve middelen (metoprolol, bisoprolol) werken vooral op β1; niet-selectieve (propranolol) ook op β2, wat bronchospasme kan geven. Bijwerkingen: bradycardie, vermoeidheid, koude extremiteiten en het maskeren van hypoglykemieverschijnselen.</p>","image_url":"","wiki_title":"Beta blocker","match":"bèta-blokkers","option_only":true},"decompensatio cordis":{"title":"Hartfalen","short":"Bij hartfalen kan het hart onvoldoende bloed rondpompen voor de behoefte van het lichaam, met kortademigheid, vermoeidheid en vochtophoping.","definition":"<p><strong>Hartfalen</strong> wordt ingedeeld naar ejectiefractie (verminderd, licht verminderd, behouden). Oorzaken zijn o.a. ischemie, hypertensie, klepziekten en cardiomyopathieën. Klachten: inspanningsdyspneu, orthopneu, oedeem, gewichtstoename. Diagnose met NT-proBNP en echocardiografie. Behandeling bij verminderde EF: ACE-remmer/ARNI, bètablokker, MRA, SGLT2-remmer en diuretica bij overvulling.</p>","image_url":"","wiki_title":"Heart failure","match":"decompensatio cordis","option_only":true},"polymyalgia reumatica (pmr)":{"title":"Polymyalgia reumatica","short":"Polymyalgia reumatica is een ontstekingsziekte bij ouderen met pijn en stijfheid in schouder- en heupgordel.","definition":"<p><strong>Polymyalgia reumatica</strong> treft vooral mensen boven de 50, vaker vrouwen. Kenmerkend zijn ochtendstijfheid en pijn in nek, schouders en heupen, met moeite om op te staan of de armen te heffen, en een sterk verhoogde BSE/CRP. Er is geen echte spierzwakte. De ziekte reageert snel op lage dosis prednison en gaat soms samen met reuscelarteriitis.</p>","image_url":"","wiki_title":"Polymyalgia rheumatica","match":"polymyalgia reumatica (pmr)","option_only":true},"familaire hypertriglyceridemie":{"title":"Familiaire hypertriglyceridemie","short":"Familiaire hypertriglyceridemie is een erfelijke stoornis met een verhoogde VLDL-productie en hoge triglyceriden.","definition":"<p>Bij <strong>familiaire hypertriglyceridemie</strong> maakt de lever te veel triglyceriderijke VLDL. Het LDL-cholesterol is meestal niet verhoogd. Overgewicht, alcohol en diabetes verergeren de afwijking. Bij zeer hoge waarden ontstaat risico op acute pancreatitis.</p>","image_url":"","wiki_title":"Hypertriglyceridemia","match":"familaire hypertriglyceridemie","option_only":true},"acuut myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"acuut myocardinfarct","option_only":true},"oesofagusspasmen":{"title":"Slokdarmspasmen","short":"Bij slokdarmspasmen trekt de slokdarm ongecoördineerd en krachtig samen, met slikklachten en retrosternale pijn.","definition":"<p>Bij <strong>distale oesofagusspasmen</strong> zijn de contracties te vroeg of tegelijk in plaats van in een voortschrijdende golf. Klachten: wisselende slikklachten voor vast én vloeibaar voedsel en kramp-achtige pijn achter het borstbeen, die op angina pectoris kan lijken. Diagnose met slokdarmmanometrie; op een slikfoto kan een ‘kurkentrekker’-beeld te zien zijn.</p>","image_url":"","wiki_title":"Diffuse esophageal spasm","match":"oesofagusspasmen","option_only":true},"turner":{"title":"Syndroom van Turner","short":"Het syndroom van Turner (45,X) is een chromosoomafwijking bij meisjes met o.a. kleine lengte en ovariumfalen.","definition":"<p>Bij het <strong>syndroom van Turner</strong> ontbreekt (deels) één X-chromosoom. Kenmerken: kleine lengte, ovariële dysgenesie met uitblijven van de puberteit en onvruchtbaarheid, een brede nek (pterygium colli), lymfoedeem bij de geboorte, een coarctatio aortae of bicuspide aortaklep en nierafwijkingen. De intelligentie is meestal normaal. Behandeling met groeihormoon en oestrogenen.</p>","image_url":"","wiki_title":"Turner syndrome","match":"turner","option_only":true},"crepitaties":{"title":"Crepitaties","short":"Crepitaties zijn fijne of grove knisperende bijgeluiden bij het luisteren naar de longen, vooral tijdens de inademing.","definition":"<p><strong>Fijne crepitaties</strong> (laat-inspiratoir, ‘klittenband’) passen bij longfibrose en beginnend longoedeem; <strong>grovere</strong> bij pneumonie, longoedeem of bronchiëctasieën. Ook bij gewrichten en onderhuids (emfyseem) spreekt men van crepitaties.</p>","image_url":"","wiki_title":"Crackles","match":"crepitaties","option_only":true},"eenzijdig crepiteren":{"title":"Crepitaties","short":"Crepitaties zijn fijne of grove knisperende bijgeluiden bij het luisteren naar de longen, vooral tijdens de inademing.","definition":"<p><strong>Fijne crepitaties</strong> (laat-inspiratoir, ‘klittenband’) passen bij longfibrose en beginnend longoedeem; <strong>grovere</strong> bij pneumonie, longoedeem of bronchiëctasieën. Ook bij gewrichten en onderhuids (emfyseem) spreekt men van crepitaties.</p>","image_url":"","wiki_title":"Crackles","match":"eenzijdig crepiteren","option_only":true},"aortastenose":{"title":"Aortaklepstenose","short":"Bij aortaklepstenose opent de aortaklep onvoldoende, waardoor de linkerventrikel tegen verhoogde weerstand moet pompen.","definition":"<p><strong>Aortaklepstenose</strong> ontstaat meestal door degeneratieve verkalking op oudere leeftijd of bij een aangeboren bicuspide klep. De linkerventrikel hypertrofieert. Bij auscultatie is er een systolisch ejectiegeruis aan de basis, vaak uitstralend naar de carotiden. Klachten (angina, syncope bij inspanning, hartfalen) wijzen op een ernstige stenose; behandeling is klepvervanging (chirurgisch of TAVI).</p>","image_url":"","wiki_title":"Aortic stenosis","match":"aortastenose","option_only":true},"aorta insufficiëntie":{"title":"Aortaklepinsufficiëntie","short":"Bij aortaklepinsufficiëntie sluit de aortaklep niet goed, waardoor bloed in de diastole terugstroomt naar de linkerventrikel.","definition":"<p>Bij <strong>aortaklepinsufficiëntie</strong> ontstaat volumebelasting van de linkerventrikel, die verwijdt. Oorzaken zijn o.a. een bicuspide klep, endocarditis, verwijding van de aortawortel (hypertensie, Marfan, dissectie). Kenmerkend zijn een diastolisch decrescendo-geruis langs de linker sternumrand en een grote polsdruk (snel stijgende en dalende pols).</p>","image_url":"","wiki_title":"Aortic insufficiency","match":"aorta insufficiëntie","option_only":true},"mitralis insufficiëntie":{"title":"Mitralisinsufficiëntie","short":"Bij mitralisinsufficiëntie sluit de mitralisklep onvoldoende, waardoor bloed in de systole terugstroomt naar het linkeratrium.","definition":"<p><strong>Mitralisinsufficiëntie</strong> kan primair zijn (klepprolaps, endocarditis, reumatische klepziekte) of secundair aan verwijding of ischemie van de linkerventrikel. Het linkeratrium raakt overbelast, met risico op boezemfibrilleren en longstuwing. Bij auscultatie hoort men een holosystolisch geruis aan de apex, uitstralend naar de oksel.</p>","image_url":"","wiki_title":"Mitral insufficiency","match":"mitralis insufficiëntie","option_only":true},"conventionele x-thorax":{"title":"X-thorax","short":"Een X-thorax is een röntgenfoto van de borstkas; het eerste beeldvormend onderzoek bij verdenking op longafwijkingen, hartfalen of pneumothorax.","definition":"<p>Een <strong>X-thorax</strong> is een röntgenopname van de borstkas, meestal posterieur-anterieur en lateraal. Lucht is zwart, weke delen grijs en bot wit.</p><p>Het is snel, goedkoop en met een lage stralingsdosis, en wordt gebruikt om o.a. pneumonie (infiltraat), pleuravocht, pneumothorax, longtumoren, hartvergroting en tekenen van hartfalen op te sporen. Kleine of subtiele afwijkingen zijn er minder goed op te zien dan op een CT.</p>","image_url":"","wiki_title":"Chest radiograph","match":"conventionele x-thorax","option_only":true},"factor v-leiden-mutatie":{"title":"Factor V Leiden","short":"Factor V Leiden is een erfelijke mutatie waardoor factor V ongevoelig is voor afbraak door geactiveerd proteïne C, met een verhoogd tromboserisico.","definition":"<p>Bij <strong>factor V Leiden</strong> (een puntmutatie in het F5-gen) kan geactiveerd proteïne C factor Va niet goed inactiveren (APC-resistentie). Het is de meest voorkomende erfelijke trombofilie bij mensen van Europese afkomst. Het verhoogt het risico op veneuze trombose, vooral in combinatie met orale anticonceptie, zwangerschap of immobilisatie.</p>","image_url":"","wiki_title":"Factor V Leiden","match":"factor v-leiden-mutatie","option_only":true},"protrombine-mutatie":{"title":"Protrombinemutatie (factor II G20210A)","short":"De protrombinemutatie verhoogt de protrombinespiegel en daarmee het risico op veneuze trombose.","definition":"<p>De <strong>protrombine-G20210A-mutatie</strong> ligt in het niet-coderende deel van het gen en leidt tot meer aanmaak van protrombine. Na factor V Leiden is het de meest voorkomende erfelijke trombofilie bij mensen van Europese afkomst.</p>","image_url":"","wiki_title":"Prothrombin G20210A","match":"protrombine-mutatie","option_only":true},"antifosfolipide-antistoffen":{"title":"Lupus anticoagulans","short":"Lupus anticoagulans is een antifosfolipide-antistof die in het lab de stolling verlengt, maar in het lichaam juist trombose bevordert.","definition":"<p><strong>Lupus anticoagulans</strong> wordt aangetoond met stollingstests (bijv. een verlengde APTT die niet corrigeert bij menging). Samen met anti-cardiolipine en anti-β2-glycoproteïne I vormt het de basis van het antifosfolipidensyndroom: veneuze en arteriële trombose en zwangerschapscomplicaties (herhaalde miskramen). Het komt voor met of zonder SLE.</p>","image_url":"","wiki_title":"Lupus anticoagulant","match":"antifosfolipide-antistoffen","option_only":true},"endocriene pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"endocriene pancreas","option_only":true},"exocriene pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"exocriene pancreas","option_only":true},"echocardiografie (echo hart)":{"title":"Echocardiografie","short":"Echocardiografie is een echo van het hart, waarmee structuur, kleppen en pompfunctie worden beoordeeld.","definition":"<p>Met <strong>echocardiografie</strong> worden o.a. de ejectiefractie, wanddikte, klepafwijkingen, pericardvocht en aangeboren afwijkingen beoordeeld. Een transoesofageale echo geeft betere beelden van kleppen en het linkerhartoor (endocarditis, stolsels).</p>","image_url":"","wiki_title":"Echocardiography","match":"echocardiografie (echo hart)","option_only":true},"de ziekte van goodpasture":{"title":"Anti-GBM-ziekte (syndroom van Goodpasture)","short":"Bij anti-GBM-ziekte vallen antistoffen tegen collageen type IV de glomerulaire en alveolaire basaalmembraan aan, met glomerulonefritis en longbloedingen.","definition":"<p>Het <strong>syndroom van Goodpasture</strong> geeft een snel progressieve glomerulonefritis en soms hemoptoë. In het nierbiopt is een lineaire IgG-afzetting langs de GBM te zien. Behandeling met plasmaferese, corticosteroïden en cyclofosfamide.</p>","image_url":"","wiki_title":"Anti-glomerular basement membrane disease","match":"de ziekte van goodpasture","option_only":true},"ruptuur aneurysma aortae, abdominaal":{"title":"Aneurysma van de aorta abdominalis (AAA)","short":"Een AAA is een verwijding van de buikslagader tot meer dan 3 cm; bij ruptuur is het levensbedreigend.","definition":"<p>Een <strong>AAA</strong> komt vooral voor bij oudere mannen die roken, met hypertensie en familiaire belasting. Meestal geeft het geen klachten; soms voelt men een pulserende zwelling. Een ruptuur geeft plotseling buik- of rugpijn en shock. Electieve behandeling (open of endovasculair) vanaf ongeveer 5,5 cm bij mannen.</p>","image_url":"","wiki_title":"Abdominal aortic aneurysm","match":"ruptuur aneurysma aortae, abdominaal","option_only":true},"aangeboren hemofilie a":{"title":"Hemofilie A","short":"Hemofilie A is een X-gebonden erfelijk tekort aan stollingsfactor VIII, met gewrichts- en spierbloedingen, vooral bij jongens.","definition":"<p><strong>Hemofilie A</strong> is een geslachtsgebonden recessieve aandoening (X-chromosoom) met een tekort aan <em>factor VIII</em>; hemofilie B is een tekort aan factor IX. Vooral jongens/mannen zijn aangedaan; vrouwen zijn meestal draagster.</p><p>Omdat de secundaire hemostase (fibrinevorming) tekortschiet, ontstaan diepe bloedingen: in gewrichten (hemartros), spieren en na trauma of ingrepen. De APTT is verlengd, PT en bloedplaatjes zijn normaal. Behandeling met factor VIII-concentraat of emicizumab.</p>","image_url":"","wiki_title":"Haemophilia A","match":"aangeboren hemofilie a","option_only":true},"infectie met epstein-barrvirus":{"title":"Epstein-Barrvirus (EBV)","short":"EBV is een herpesvirus dat B-cellen infecteert; het veroorzaakt de ziekte van Pfeiffer en is geassocieerd met enkele kankers.","definition":"<p>Het <strong>Epstein-Barrvirus</strong> wordt via speeksel overgedragen. Op jonge leeftijd verloopt infectie vaak ongemerkt; bij adolescenten geeft het vaak mononucleosis infectiosa. Het virus blijft levenslang latent in B-cellen. EBV is geassocieerd met o.a. het Burkittlymfoom, het nasofarynxcarcinoom, sommige Hodgkinlymfomen en posttransplantatie-lymfoproliferatieve ziekte.</p>","image_url":"","wiki_title":"Epstein–Barr virus","match":"infectie met epstein-barrvirus","option_only":true},"trombocyt-aggregatieremmers":{"title":"Clopidogrel","short":"Clopidogrel is een plaatjesremmer die de ADP-receptor P2Y12 op bloedplaatjes onomkeerbaar blokkeert.","definition":"<p><strong>Clopidogrel</strong> is een prodrug die via CYP2C19 in de lever wordt geactiveerd. De actieve metaboliet blokkeert de P2Y12-receptor, zodat ADP de plaatjes niet meer kan activeren. Het wordt gebruikt na een acuut coronair syndroom en stentplaatsing (vaak samen met acetylsalicylzuur) en bij herseninfarct en perifeer vaatlijden. Bijwerking: bloedingen.</p>","image_url":"","wiki_title":"Clopidogrel","match":"trombocyt-aggregatieremmers","option_only":true},"thiazide-diuretica":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"thiazide-diuretica","option_only":true},"calciumantagonisten":{"title":"Amlodipine","short":"Amlodipine is een langwerkende dihydropyridine-calciumantagonist die de arteriën verwijdt; gebruikt bij hypertensie en angina.","definition":"<p><strong>Dihydropyridines</strong> (amlodipine, nifedipine) blokkeren L-type calciumkanalen vooral in vasculaire gladde spier en hebben weinig effect op het hart. Bijwerkingen zijn enkeloedeem (door precapillaire vaatverwijding), hoofdpijn, flushing en tandvleeshyperplasie. Non-dihydropyridines (verapamil, diltiazem) werken juist meer op hart en AV-knoop.</p>","image_url":"","wiki_title":"Amlodipine","match":"calciumantagonisten","option_only":true},"hypertrofie van het hart":{"title":"Linkerventrikelhypertrofie","short":"Linkerventrikelhypertrofie is een verdikking van de wand van de linkerkamer, meestal door langdurige drukbelasting.","definition":"<p><strong>LVH</strong> ontstaat bij hypertensie, aortaklepstenose, HCM en training (sporthart). Ze geeft diastolische disfunctie en is een sterke risicofactor voor hartfalen, ritmestoornissen en plotse dood. Zichtbaar op ECG (verhoogde voltages) en echo.</p>","image_url":"","wiki_title":"Left ventricular hypertrophy","match":"hypertrofie van het hart","option_only":true},"psychogene polidipsie":{"title":"Polydipsie","short":"Polydipsie is overmatige dorst en vochtinname.","definition":"<p><strong>Polydipsie</strong> gaat vaak samen met polyurie. Oorzaken zijn o.a. diabetes mellitus (osmotische diurese), diabetes insipidus (centraal of nefrogeen), hypercalciëmie, diuretica en primaire (psychogene) polydipsie. Een dorstproef kan helpen deze oorzaken te onderscheiden.</p>","image_url":"","wiki_title":"Polydipsia","match":"psychogene polidipsie","option_only":true},"angina abdominalis bij atherosclerose":{"title":"Angina abdominalis (chronische mesenteriale ischemie)","short":"Bij angina abdominalis ontstaat buikpijn na de maaltijd door vernauwing van de darmslagaders, met angst om te eten en gewichtsverlies.","definition":"<p>Bij <strong>chronische mesenteriale ischemie</strong> zijn meestal twee of drie darmslagaders (truncus coeliacus, a. mesenterica superior en inferior) vernauwd door atherosclerose. Behandeling met revascularisatie (stent of bypass).</p>","image_url":"","wiki_title":"Chronic mesenteric ischemia","match":"angina abdominalis bij atherosclerose|angina abdominalis","option_only":true},"antitrombine deficientie":{"title":"Antitrombinedeficiëntie","short":"Antitrombine remt trombine en factor Xa; een erfelijk tekort geeft een hoog risico op veneuze trombose.","definition":"<p><strong>Antitrombine</strong> wordt in de lever gemaakt; heparine versterkt de werking ervan sterk. Bij een tekort (erfelijk, of verworven bij nefrotisch syndroom, leverziekte of DIS) werkt heparine minder goed.</p>","image_url":"","wiki_title":"Antithrombin III deficiency","match":"antitrombine deficientie|antitrombinedeficiëntie|antitrombine","option_only":true},"mibi-scan voor ischemiedetectie":{"title":"Myocardperfusiescintigrafie (MIBI-scan)","short":"Een MIBI-scan brengt met een radioactieve stof de doorbloeding van de hartspier in rust en bij inspanning in beeld.","definition":"<p>Bij een <strong>myocardperfusiescintigrafie</strong> wijst een perfusiedefect bij inspanning dat in rust verdwijnt op ischemie; een defect in rust en bij inspanning op een litteken. Inspanning kan ook farmacologisch worden nagebootst (adenosine, dobutamine).</p>","image_url":"","wiki_title":"Myocardial perfusion imaging","match":"mibi-scan voor ischemiedetectie|mibi-scan|myocardperfusiescintigrafie","option_only":true},"thromboflebitis":{"title":"Tromboflebitis","short":"Bij tromboflebitis is een oppervlakkige ader ontstoken met een stolsel, met een pijnlijke, rode, harde streng onder de huid.","definition":"<p>Een <strong>oppervlakkige tromboflebitis</strong> komt voor bij varices, na een infuus en bij hypercoagulabiliteit. Bij uitbreiding tot vlak bij de liesovergang of bij een recidiverend migrerend beeld (soms bij kanker) is verder onderzoek nodig.</p>","image_url":"","wiki_title":"Thrombophlebitis","match":"thromboflebitis|tromboflebitis|oppervlakkige tromboflebitis","option_only":true},"renografie":{"title":"Renografie (MAG3-scan)","short":"Bij renografie wordt met een radioactieve stof gemeten hoe de nieren de stof opnemen en uitscheiden, om obstructie en de verdeling van de nierfunctie te beoordelen.","definition":"<p>Een <strong>MAG3-renogram</strong> wordt o.a. gebruikt bij hydronefrose, om te onderscheiden of er een echte afvoerbelemmering is, en om de bijdrage van elke nier te bepalen.</p>","image_url":"","wiki_title":"Renal scintigraphy","match":"renografie|renogram|mag3","option_only":true},"metacommunicatie":{"title":"Metacommunicatie","short":"Metacommunicatie is communiceren over de communicatie zelf: benoemen wat er in het gesprek gebeurt.","definition":"<p>Bij <strong>metacommunicatie</strong> stapt de arts even uit de inhoud (‘ik merk dat we langs elkaar heen praten’). Het helpt bij weerstand, irritatie of een vastgelopen gesprek. Een voorbeeld is de hier-en-nu-opmerking.</p>","image_url":"","wiki_title":"Metacommunication","match":"metacommunicatie","option_only":true},"polyangiitis nodosa (pan)":{"title":"Polyarteriitis nodosa","short":"Polyarteriitis nodosa is een necrotiserende vasculitis van middelgrote arteriën, zonder ANCA en zonder glomerulonefritis.","definition":"<p>Bij <strong>polyarteriitis nodosa</strong> raken middelgrote spierarteriën ontstoken, met microaneurysmata en infarcten in o.a. nieren (hypertensie), darm (buikpijn), huid (livedo, ulcera) en zenuwen (mononeuritis multiplex). Een deel van de gevallen hangt samen met hepatitis B. De longen zijn meestal niet aangedaan.</p>","image_url":"","wiki_title":"Polyarteritis nodosa","match":"polyangiitis nodosa (pan)","option_only":true},"ischemische cardiomyopathie":{"title":"Gedilateerde cardiomyopathie","short":"Bij gedilateerde cardiomyopathie is de linkerventrikel verwijd en pompt hij slecht, met hartfalen en ritmestoornissen.","definition":"<p>Oorzaken van <strong>gedilateerde cardiomyopathie</strong> zijn erfelijk (o.a. titine- en lamine-mutaties), myocarditis, alcohol, chemotherapie (antracyclines), tachycardie en zwangerschap (peripartum). Het geeft hartfalen met een verminderde ejectiefractie, ventriculaire aritmieën en trombo-embolie.</p>","image_url":"","wiki_title":"Dilated cardiomyopathy","match":"ischemische cardiomyopathie","option_only":true},"auto-immuunhemolyse":{"title":"Auto-immuun hemolytische anemie","short":"Bij AIHA maakt het lichaam antistoffen tegen de eigen rode bloedcellen, die daardoor worden afgebroken; de directe antiglobulinetest (Coombs) is positief.","definition":"<p>Bij <strong>auto-immuun hemolytische anemie</strong> binden auto-antistoffen aan erytrocyten, die vervolgens vooral in de milt worden afgebroken (type II-overgevoeligheid). Bij <em>warme</em> AIHA gaat het om IgG; bij <em>koude</em> AIHA om IgM met complementactivatie.</p><p>Laboratorium: anemie met verhoogde reticulocyten, verhoogd LDH en ongeconjugeerd bilirubine, verlaagd haptoglobine, sferocyten en een positieve directe antiglobulinetest (Coombs). Oorzaken: idiopathisch, lymfoproliferatieve ziekten, SLE, infecties (Mycoplasma, EBV) of geneesmiddelen.</p>","image_url":"","wiki_title":"Autoimmune hemolytic anemia","match":"auto-immuunhemolyse","option_only":true},"hemolyse door auto-antistoffen":{"title":"Auto-immuun hemolytische anemie","short":"Bij AIHA maakt het lichaam antistoffen tegen de eigen rode bloedcellen, die daardoor worden afgebroken; de directe antiglobulinetest (Coombs) is positief.","definition":"<p>Bij <strong>auto-immuun hemolytische anemie</strong> binden auto-antistoffen aan erytrocyten, die vervolgens vooral in de milt worden afgebroken (type II-overgevoeligheid). Bij <em>warme</em> AIHA gaat het om IgG; bij <em>koude</em> AIHA om IgM met complementactivatie.</p><p>Laboratorium: anemie met verhoogde reticulocyten, verhoogd LDH en ongeconjugeerd bilirubine, verlaagd haptoglobine, sferocyten en een positieve directe antiglobulinetest (Coombs). Oorzaken: idiopathisch, lymfoproliferatieve ziekten, SLE, infecties (Mycoplasma, EBV) of geneesmiddelen.</p>","image_url":"","wiki_title":"Autoimmune hemolytic anemia","match":"hemolyse door auto-antistoffen","option_only":true},"tuberculose (mycobacterium tuberculosis)":{"title":"Tuberculose","short":"Tuberculose is een infectie met Mycobacterium tuberculosis, meestal in de longen, met langdurig hoesten, nachtzweten, gewichtsverlies en granulomen.","definition":"<p><strong>Tuberculose</strong> wordt veroorzaakt door <em>Mycobacterium tuberculosis</em> en verspreidt zich via aerosolen. Na infectie wordt de bacterie meestal ingekapseld in granulomen (latente tbc); bij verminderde afweer kan actieve ziekte ontstaan.</p><p>Longtuberculose geeft langdurig hoesten (soms met bloed), koorts, nachtzweten en gewichtsverlies; typisch zijn holtevorming in de longtoppen en granulomen met centrale <em>verkazing</em>. Behandeling met een combinatie van tuberculostatica gedurende minstens 6 maanden.</p>","image_url":"","wiki_title":"Tuberculosis","match":"tuberculose (mycobacterium tuberculosis)","option_only":true},"coronair angiogram":{"title":"Coronairangiografie","short":"Bij coronairangiografie worden de kransslagaders met contrast en röntgen in beeld gebracht via een katheter in de pols of lies.","definition":"<p>Een <strong>CAG</strong> toont vernauwingen in de kransslagaders en wordt vaak direct gecombineerd met een PCI (dotteren en stenten). Complicaties zijn bloedingen op de punctieplaats, contrastnefropathie en zelden een beroerte of infarct.</p>","image_url":"","wiki_title":"Coronary catheterization","match":"coronair angiogram","option_only":true},"een beta-2-sympaticomimeticum":{"title":"Salbutamol","short":"Salbutamol is een kortwerkende β2-agonist die binnen minuten de luchtwegen verwijdt; gebruikt bij astma- en COPD-aanvallen.","definition":"<p><strong>Salbutamol</strong> ontspant de gladde spier van de bronchi via β2-receptoren en cAMP. Het werkt binnen enkele minuten en ongeveer 4–6 uur. Het wordt via een dosisaerosol met voorzetkamer of als verneveling gegeven. Bijwerkingen: tremor, tachycardie en een daling van het kalium (het wordt daarom ook gebruikt bij hyperkaliëmie).</p>","image_url":"","wiki_title":"Salbutamol","match":"een beta-2-sympaticomimeticum","option_only":true},"kortwerkend beta-2-ympaticomimeticum":{"title":"Salbutamol","short":"Salbutamol is een kortwerkende β2-agonist die binnen minuten de luchtwegen verwijdt; gebruikt bij astma- en COPD-aanvallen.","definition":"<p><strong>Salbutamol</strong> ontspant de gladde spier van de bronchi via β2-receptoren en cAMP. Het werkt binnen enkele minuten en ongeveer 4–6 uur. Het wordt via een dosisaerosol met voorzetkamer of als verneveling gegeven. Bijwerkingen: tremor, tachycardie en een daling van het kalium (het wordt daarom ook gebruikt bij hyperkaliëmie).</p>","image_url":"","wiki_title":"Salbutamol","match":"kortwerkend beta-2-ympaticomimeticum","option_only":true},"chronisch veneuze insufficiëntie":{"title":"Chronische veneuze insufficiëntie","short":"Bij chronische veneuze insufficiëntie werkt de veneuze terugstroom uit de benen slecht, met oedeem, huidverkleuring en uiteindelijk ulcera.","definition":"<p>Door lekkende kleppen of een doorgemaakte trombose (posttrombotisch syndroom) stijgt de veneuze druk in de benen. Gevolgen: varices, oedeem, hyperpigmentatie (hemosiderine), eczeem, lipodermatosclerose, atrophie blanche en een ulcus cruris venosum, typisch rond de mediale enkel. Behandeling met compressietherapie.</p>","image_url":"","wiki_title":"Chronic venous insufficiency","match":"chronisch veneuze insufficiëntie","option_only":true},"dapagliflozine (sglt2 remmer)":{"title":"SGLT2-remmer","short":"SGLT2-remmers laten de nier glucose uitscheiden; ze verlagen de bloedglucose en beschermen hart en nieren.","definition":"<p><strong>SGLT2-remmers</strong> remmen de glucoseterugresorptie in de proximale tubulus. Naast glucoseverlaging (diabetes type 2) verminderen ze ziekenhuisopnames bij hartfalen en vertragen ze chronische nierschade. Bijwerkingen: genitale schimmelinfecties, volumedepletie en zeldzaam een euglykemische ketoacidose.</p>","image_url":"","wiki_title":"SGLT2 inhibitor","match":"dapagliflozine (sglt2 remmer)","option_only":true},"methotrexaat (foliumzuurantagonist)":{"title":"Methotrexaat","short":"Methotrexaat is een foliumzuurantagonist; in lage dosis een basismiddel bij reumatoïde artritis en psoriasis, in hoge dosis een cytostaticum.","definition":"<p><strong>Methotrexaat</strong> remt dihydrofolaatreductase. In lage, wekelijkse dosering werkt het ontstekingsremmend (o.a. via adenosine) en is het een hoeksteen bij reumatoïde artritis, psoriasis en IBD; foliumzuur vermindert bijwerkingen. Bijwerkingen: beenmergsuppressie, levertoxiciteit, mucositis en pneumonitis. Het is teratogeen en wordt via de nier uitgescheiden.</p>","image_url":"","wiki_title":"Methotrexate","match":"methotrexaat (foliumzuurantagonist)","option_only":true},"vasculaire claudicatio intermittens":{"title":"Claudicatio intermittens","short":"Claudicatio intermittens is pijn in de kuit of bil bij lopen die bij stilstaan verdwijnt, door perifeer arterieel vaatlijden.","definition":"<p>Bij <strong>claudicatio</strong> zijn de beenarteriën vernauwd door atherosclerose. De enkel-armindex is verlaagd (&lt;0,9). Behandeling: stoppen met roken, gesuperviseerde looptraining, een plaatjesremmer en statine; bij ernstige klachten of kritieke ischemie (rustpijn, wonden) revascularisatie.</p>","image_url":"","wiki_title":"Intermittent claudication","match":"vasculaire claudicatio intermittens","option_only":true},"anti-dsdna":{"title":"Anti-dsDNA-antistoffen","short":"Anti-dsDNA-antistoffen zijn auto-antistoffen tegen dubbelstrengs DNA en zeer specifiek voor systemische lupus erythematodes (SLE).","definition":"<p>De titer van <strong>anti-dsDNA</strong> stijgt vaak bij ziekteactiviteit, vooral bij lupusnefritis, samen met een daling van complement (C3, C4). Een positieve ANA is gevoelig maar weinig specifiek; anti-dsDNA en anti-Sm zijn juist specifiek.</p>","image_url":"","wiki_title":"Anti-dsDNA antibodies","match":"anti-dsdna|anti-dubbelstrengs dna antistoffen|anti-dsdna-antistoffen","option_only":true},"anca":{"title":"ANCA","short":"ANCA zijn auto-antistoffen tegen eiwitten in neutrofielen (PR3, MPO) die horen bij kleinevatenvasculitis.","definition":"<p><strong>PR3-ANCA</strong> (c-ANCA) past vooral bij granulomatose met polyangiitis; <strong>MPO-ANCA</strong> (p-ANCA) bij microscopische polyangiitis en EGPA. ANCA-vasculitis kan snel progressieve glomerulonefritis en longbloedingen geven.</p>","image_url":"","wiki_title":"Anti-neutrophil cytoplasmic antibody","match":"anca|anca antistoffen|c-anca|p-anca|anti-pr3|anti-mpo","option_only":true},"anca antistoffen":{"title":"ANCA","short":"ANCA zijn auto-antistoffen tegen eiwitten in neutrofielen (PR3, MPO) die horen bij kleinevatenvasculitis.","definition":"<p><strong>PR3-ANCA</strong> (c-ANCA) past vooral bij granulomatose met polyangiitis; <strong>MPO-ANCA</strong> (p-ANCA) bij microscopische polyangiitis en EGPA. ANCA-vasculitis kan snel progressieve glomerulonefritis en longbloedingen geven.</p>","image_url":"","wiki_title":"Anti-neutrophil cytoplasmic antibody","match":"anca antistoffen","option_only":true},"granulomatose met polyangiitis (gpa, wegener)":{"title":"Granulomatose met polyangiitis (GPA)","short":"GPA is een ANCA-geassocieerde vasculitis van kleine vaten met granulomen, vooral in bovenste luchtwegen, longen en nieren.","definition":"<p>Bij <strong>GPA</strong> zijn er klachten van neus en bijholten (korsten, bloedingen, zadelneus), longnoduli of -bloedingen en een snel progressieve glomerulonefritis. Meestal zijn er c-ANCA (anti-PR3). Behandeling met hoge dosis corticosteroïden en rituximab of cyclofosfamide.</p>","image_url":"","wiki_title":"Granulomatosis with polyangiitis","match":"granulomatose met polyangiitis (gpa, wegener)","option_only":true},"thrombangiitis obliterans (de ziekte van bürger)":{"title":"Thrombangiitis obliterans (ziekte van Bürger)","short":"Ontsteking en trombose van kleine en middelgrote arteriën en venen, sterk gerelateerd aan roken.","definition":"<p>De ziekte van Bürger treft vooral jonge, hevige rokers en geeft ischemie van vingers en tenen met normale ontstekingsparameters (BSE, ANA). Stoppen met roken is essentieel.</p>","image_url":"","wiki_title":"Thromboangiitis obliterans","match":"thrombangiitis obliterans (de ziekte van bürger)","option_only":true},"migraine":{"title":"Migraine","short":"Aanvalsgewijze, vaak eenzijdige kloppende hoofdpijn met misselijkheid, foto- en fonofobie, soms met aura. Duurt uren tot een dag.","definition":"<p><b>Migraine</b>-aanvallen worden verergerd door inspanning; de patiënt zoekt rust in een donkere kamer. Aanvalsbehandeling met triptanen bij onvoldoende effect van NSAID's.</p>","image_url":"","wiki_title":"Migraine","match":"migraine","option_only":true},"aritmogene rechterventrikel cardiomyopathie (arvc)":{"title":"ARVC","short":"Aritmogene rechterventrikelcardiomyopathie: erfelijke aandoening met vervanging van hartspier door vet/bindweefsel en ritmestoornissen.","definition":"<p><b>ARVC</b> (aritmogene rechterventrikelcardiomyopathie) is een erfelijke cardiomyopathie waarbij myocard wordt vervangen door vet- en bindweefsel, vooral in de rechterventrikel. Het geeft ventriculaire ritmestoornissen en risico op plotse hartdood.</p>","image_url":"","wiki_title":"Arrhythmogenic cardiomyopathy","match":"aritmogene rechterventrikel cardiomyopathie (arvc)","option_only":true},"angiotensine converting enzyme remmers (ace-remmers)":{"title":"ACE-remmers","short":"Bloeddrukverlagers die ook de intraglomerulaire druk verlagen en proteïnurie verminderen.","definition":"<p><b>ACE-remmers</b> remmen het angiotensine-converting enzyme, waardoor minder angiotensine II wordt gevormd. Ze geven vasodilatatie van vooral de efferente arteriole en verlagen de systemische bloeddruk; beide verlagen de intraglomerulaire druk, wat de proteïnurie vermindert en nefroprotectief werkt.</p>","image_url":"","wiki_title":"ACE inhibitor","match":"angiotensine converting enzyme remmers (ace-remmers)","option_only":true},"immuungemediëerde trombocytopenische purpura (itp)":{"title":"ITP","short":"Immuungemediëerde afbraak van trombocyten, met een laag trombocytengetal en huidbloedingen (petechiën/purpura).","definition":"<p><b>Immuungemediëerde trombocytopenische purpura (ITP)</b> is een auto-immuunziekte waarbij antistoffen tegen trombocyten leiden tot versnelde afbraak. Gevolg: trombocytopenie met petechiën en purpura (gestoorde primaire hemostase).</p>","image_url":"","wiki_title":"Immune thrombocytopenic purpura","match":"immuungemediëerde trombocytopenische purpura (itp)","option_only":true},"high density lipoprotein (hdl) cholesterol":{"title":"HDL","short":"High-density lipoprotein; voert cholesterol vanuit perifere weefsels terug naar de lever (‘goede cholesterol’).","definition":"<p><b>HDL</b> verzorgt het omgekeerde cholesteroltransport: opname uit o.a. de vaatwand en terugvoer naar de lever.</p>","image_url":"","wiki_title":"High-density lipoprotein","match":"high density lipoprotein (hdl) cholesterol","option_only":true},"sterk verhoogd c-reactief proteïne (crp)":{"title":"CRP","short":"C-reactief proteïne; ontstekingseiwit in het bloed dat helpt de kans op een gecompliceerde infectie in te schatten.","definition":"<p>Het CRP stijgt bij ontsteking of infectie; in de huisartsenpraktijk stuurt het het antibioticabeleid bij luchtweginfecties.</p>","image_url":"","wiki_title":"C-reactive_protein","match":"sterk verhoogd c-reactief proteïne (crp)","option_only":true},"syndrome of inappropriate adh-secretion (siadh)":{"title":"SIADH","short":"Syndroom van inadequate ADH-secretie: te veel antidiuretisch hormoon geeft waterretentie en verdunningshyponatriëmie.","definition":"<p><b>SIADH</b> (syndrome of inappropriate ADH secretion) is een overmatige, niet-fysiologische afgifte van antidiuretisch hormoon, met waterretentie en een verdunningshyponatriëmie. Medicamenteuze oorzaak o.a. SSRI's zoals citalopram.</p>","image_url":"","wiki_title":"Syndrome of inappropriate antidiuretic hormone secretion","match":"syndrome of inappropriate adh-secretion (siadh)","option_only":true},"erysipelas":{"title":"Erysipelas","short":"Wondroos: een scherp begrensde, oppervlakkige huidinfectie (dermis) meestal door streptokokken. Geeft een rode, warme, pijnlijke huid vaak met koorts.","definition":"<p><strong>Erysipelas</strong> (wondroos) is een acute infectie van de bovenste dermis en oppervlakkige lymfevaten, meestal door groep A-streptokokken. Kenmerkend zijn een scherp begrensde felrode zwelling, koorts en algemeen ziek-zijn; het is een belangrijke differentiaaldiagnose van DVT.</p>","image_url":"","wiki_title":"Erysipelas","match":"erysipelas","option_only":true},"non-steroïdale anti-inflammatoire drugs (nsaids)":{"title":"NSAID","short":"Non-steroidal anti-inflammatory drug (aspirine, ibuprofen); remt COX-enzymen en daarmee ontsteking en plaatjesaggregatie.","definition":"<p><b>NSAID's</b> remmen cyclo-oxygenase: ontstekingsremmend en pijnstillend, maar met bloedingsrisico en maagslijmvliesschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"non-steroïdale anti-inflammatoire drugs (nsaids)","option_only":true},"arteriolen (diameter <500 micron)":{"title":"Arteriolen","short":"Arteriolen zijn de kleinste arteriën met een spierwand; ze bepalen het grootste deel van de perifere vaatweerstand.","definition":"<p>In <strong>arteriolen</strong> daalt de bloeddruk het sterkst. Door samen te trekken of te verwijden regelen ze de doorbloeding van weefsels (autoregulatie, sympathische invloed, lokale metabolieten) en daarmee de bloeddruk. Bij langdurige hypertensie of diabetes ontstaat arteriolosclerose (hyaliene verdikking).</p>","image_url":"","wiki_title":"Arteriole","match":"arteriolen (diameter <500 micron)","option_only":true},"reuscelvasculitis (arteriitis gigantocellularis of arteriitis temporalis)":{"title":"Arteriitis temporalis (reuscelarteriitis)","short":"Arteriitis temporalis is een granulomateuze vasculitis van grote en middelgrote arteriën bij ouderen, met risico op blindheid.","definition":"<p>Bij <strong>reuscelarteriitis</strong> zijn vooral takken van de a. carotis externa (zoals de a. temporalis) en soms de aorta en haar takken ontstoken. Klachten: nieuwe hoofdpijn, gevoelige slaapslagader, kauwclaudicatie, visusstoornissen en algemene malaise, met een sterk verhoogde BSE/CRP. Bij verdenking direct hoge dosis prednison om blindheid te voorkomen; diagnose met echo of biopt.</p>","image_url":"","wiki_title":"Giant cell arteritis","match":"reuscelvasculitis (arteriitis gigantocellularis of arteriitis temporalis)","option_only":true},"ziekte van conn (primair hyperaldosteronisme)":{"title":"Ziekte van Conn","short":"Primair hyperaldosteronisme: overproductie van aldosteron met hypertensie, hypokaliëmie en onderdrukte renine.","definition":"<p>Bij de ziekte van Conn produceert de bijnier autonoom te veel aldosteron. Kenmerkend zijn een hoge aldosteronconcentratie met sterk onderdrukte plasmarenine en hypokaliëmie.</p>","image_url":"","wiki_title":"Primary aldosteronism","match":"ziekte van conn (primair hyperaldosteronisme)","option_only":true},"ziekte van addison (primair hypocortisolisme)":{"title":"Ziekte van Addison","short":"De ziekte van Addison is een primaire bijnierschorsinsufficiëntie met tekort aan cortisol en aldosteron.","definition":"<p>De <b>ziekte van Addison</b> is een primaire bijnierschorsinsufficiëntie, meestal door auto-immuundestructie (of bijv. tuberculose) van de bijnierschors, met tekort aan cortisol en aldosteron. Microscopisch: sterk gereduceerd aantal corticale cellen in bindweefsel.</p>","image_url":"","wiki_title":"Addison's disease","match":"ziekte van addison (primair hypocortisolisme)","option_only":true},"trombo-embolectomie":{"title":"Trombo-embolectomie","short":"Chirurgische verwijdering van een stolsel (embolus) uit een bloedvat om de doorbloeding te herstellen.","definition":"<p>Bij acute arteriële afsluiting van een been kan een trombo-embolectomie (verwijdering van het stolsel) de perfusie herstellen, naast trombolyse.</p>","image_url":"","wiki_title":"Embolectomy","match":"trombo-embolectomie","option_only":true},"high density lipoprotein (hdl)":{"title":"HDL-cholesterol","short":"'Gunstig' lipoproteïne dat cholesterol van de weefsels terug naar de lever transporteert (revers cholesteroltransport).","definition":"<p><b>High density lipoprotein (HDL)</b> neemt cholesterol op uit perifere weefsels en brengt het terug naar de lever (revers cholesteroltransport). Een hoog HDL is geassocieerd met een lager cardiovasculair risico.</p>","image_url":"","wiki_title":"High-density lipoprotein","match":"high density lipoprotein (hdl)","option_only":true},"very low density lipoprotein (vldl)":{"title":"VLDL","short":"VLDL is een triglyceriderijk lipoproteïne dat door de lever wordt gemaakt en vetten naar de weefsels vervoert.","definition":"<p>Na afgifte van triglyceriden via lipoproteïnelipase wordt <strong>VLDL</strong> omgezet in IDL en vervolgens LDL. Verhoogde VLDL-productie (bij obesitas, insulineresistentie, alcohol) geeft hypertriglyceridemie.</p>","image_url":"","wiki_title":"Very-low-density lipoprotein","match":"very low density lipoprotein (vldl)","option_only":true},"cholecalciferol":{"title":"Cholecalciferol (vitamine D3)","short":"Cholecalciferol is de inactieve voorloper van vitamine D die in de huid en via voeding wordt verkregen.","definition":"<p><b>Cholecalciferol</b> (vitamine D3) is een inactieve vorm van vitamine D die nog in lever (25-hydroxylatie) en nier (1-hydroxylatie) moet worden geactiveerd tot calcitriol.</p>","image_url":"","wiki_title":"Cholecalciferol","match":"cholecalciferol","option_only":true},"von willebrand factor":{"title":"Von Willebrandfactor","short":"Plasma-eiwit dat trombocyten aan beschadigd endotheel laat hechten en factor VIII stabiliseert; centraal in de primaire hemostase.","definition":"<p><b>Von Willebrandfactor (vWF)</b> mediëert de adhesie van trombocyten aan subendotheliaal collageen (via GPIb) en draagt factor VIII. Bij de ziekte van Von Willebrand of vWF-defecten ontstaat een bloedingsneiging van het primaire-hemostasetype.</p>","image_url":"","wiki_title":"Von Willebrand factor","match":"von willebrand factor","option_only":true},"autoimmuun trombocytopenische purpura (aitp)":{"title":"Auto-immuun trombocytopenische purpura (ITP)","short":"Verworven trombocytopenie door antistoffen tegen trombocyten, met petechiën en hematomen bij overigens normale milt.","definition":"<p>ITP (ook AITP) is een diagnose per exclusie: geïsoleerde trombocytopenie zonder splenomegalie of andere oorzaak. Normale PT/aPTT.</p>","image_url":"","wiki_title":"Immune thrombocytopenic purpura","match":"autoimmuun trombocytopenische purpura (aitp)","option_only":true},"coronairlijden":{"title":"Coronairlijden","short":"Vernauwing van de kransslagaders door atherosclerose, met kans op angina pectoris en myocardinfarct.","definition":"<p><b>Coronairlijden</b> (coronaire hartziekte) beperkt de bloedtoevoer naar het myocard; de voorafkans wordt bepaald door het klachtenpatroon en risicofactoren.</p>","image_url":"","wiki_title":"Coronary artery disease","match":"coronairlijden","option_only":true},"protrombinetijd (pt), uitgedrukt in inr":{"title":"PT (INR)","short":"Protrombinetijd, uitgedrukt in International Normalised Ratio; test de extrinsieke stollingsroute.","definition":"<p>De <b>protrombinetijd</b> (PT/INR) meet de extrinsieke en gemeenschappelijke stollingsroute. Gebruikt om vitamine K-antagonisten te monitoren.</p>","image_url":"","wiki_title":"Prothrombin time","match":"protrombinetijd (pt), uitgedrukt in inr","option_only":true},"syndrome of inappropriate adh secretion (siadh)":{"title":"SIADH","short":"Syndroom van inadequate ADH-secretie: te veel antidiuretisch hormoon geeft waterretentie en verdunningshyponatriëmie.","definition":"<p><b>SIADH</b> (syndrome of inappropriate ADH secretion) is een overmatige, niet-fysiologische afgifte van antidiuretisch hormoon, met waterretentie en een verdunningshyponatriëmie. Medicamenteuze oorzaak o.a. SSRI's zoals citalopram.</p>","image_url":"","wiki_title":"Syndrome of inappropriate antidiuretic hormone secretion","match":"syndrome of inappropriate adh secretion (siadh)","option_only":true},"shock":{"title":"Shock","short":"Shock is een levensbedreigend tekort aan weefselperfusie en zuurstoftoevoer; hoofdvormen zijn hypovolemisch, cardiogeen, obstructief en distributief (o.a. septisch).","definition":"<p><strong>Shock</strong> is een toestand van onvoldoende weefseldoorbloeding. Bij <em>distributieve/septische</em> shock zorgt uitgebreide vasodilatatie voor warme extremiteiten ('warme shock'), terwijl hypovolemische en cardiogene shock juist koude, klamme acra geven door vasoconstrictie. Herkenning van het type stuurt de behandeling.</p>","image_url":"","wiki_title":"Shock (circulatory)","match":"shock","option_only":true},"petechiën":{"title":"Petechiën","short":"Speldenknopgrote huidbloedinkjes, kenmerkend voor een stoornis in de primaire hemostase (trombocyten).","definition":"<p>Petechiën ontstaan bij trombocytopenie of trombocytopathie en wijken niet weg op druk (niet-blancheerbaar).</p>","image_url":"","wiki_title":"Petechia","match":"petechiën","option_only":true},"micro-angiopathische hemolyse":{"title":"Micro-angiopathische hemolyse","short":"Mechanische afbraak van erytrocyten in beschadigde kleine bloedvaten, met fragmentocyten in het bloed.","definition":"<p>Micro-angiopathische hemolytische anemie ontstaat als erytrocyten kapotgaan langs fibrinestrengen in kleine vaten (bv. bij TTP of DIS); kenmerkend zijn schistocyten/fragmentocyten.</p>","image_url":"","wiki_title":"Microangiopathic hemolytic anemia","match":"micro-angiopathische hemolyse","option_only":true},"monocyten":{"title":"Monocyt","short":"Grootste witte bloedcel; verlaat het bloed en rijpt in de weefsels uit tot macrofaag of dendritische cel.","definition":"<p>De <b>monocyt</b> is de grootste circulerende leukocyt, met een niervormige kern. Hij circuleert enkele dagen en migreert dan de weefsels in.</p><p>Daar differentieert hij tot macrofaag of dendritische cel, die pathogenen fagocyteren en antigenen presenteren.</p>","image_url":"","wiki_title":"Monocyte","match":"monocyten","option_only":true},"na⁺":{"title":"Natrium","short":"Natrium is het belangrijkste kation buiten de cel; het bepaalt grotendeels het extracellulaire volume en de osmolaliteit.","definition":"<p><strong>Natrium</strong> wordt door de Na⁺/K⁺-ATPase buiten de cel gehouden, waardoor een gradiënt ontstaat die nodig is voor actiepotentialen en secundair actief transport. De hoeveelheid natrium in het lichaam bepaalt het extracellulaire volume (via RAAS en natriuretische peptiden); de natriumconcentratie weerspiegelt vooral de waterbalans (via ADH en dorst).</p>","image_url":"","wiki_title":"Sodium in biology","match":"na⁺","option_only":true},"turner syndroom":{"title":"Syndroom van Turner","short":"Het syndroom van Turner (45,X) is een chromosoomafwijking bij meisjes met o.a. kleine lengte en ovariumfalen.","definition":"<p>Bij het <strong>syndroom van Turner</strong> ontbreekt (deels) één X-chromosoom. Kenmerken: kleine lengte, ovariële dysgenesie met uitblijven van de puberteit en onvruchtbaarheid, een brede nek (pterygium colli), lymfoedeem bij de geboorte, een coarctatio aortae of bicuspide aortaklep en nierafwijkingen. De intelligentie is meestal normaal. Behandeling met groeihormoon en oestrogenen.</p>","image_url":"","wiki_title":"Turner syndrome","match":"turner syndroom","option_only":true},"d-dimeer":{"title":"D-dimeer","short":"Afbraakproduct van fibrine; een normale waarde sluit bij lage verdenking een trombose/longembolie vrijwel uit.","definition":"<p>D-dimeer is een fibrinolyse-afbraakproduct. Een normale waarde bij lage klinische verdenking sluit een longembolie uit; een verhoogde waarde is aspecifiek en vereist beeldvorming.</p>","image_url":"","wiki_title":"","match":"d-dimeer","option_only":true},"hemoptoë":{"title":"Hemoptoë","short":"Het ophoesten van bloed uit de lagere luchtwegen; kan een symptoom zijn van een pulmonaal-renaal syndroom.","definition":"<p><b>Hemoptoë</b> is het ophoesten van bloed afkomstig uit de longen of lagere luchtwegen. In combinatie met nierinsufficiëntie kan het wijzen op een pulmonaal-renaal syndroom (anti-GBM-ziekte of ANCA-vasculitis).</p>","image_url":"","wiki_title":"Hemoptysis","match":"hemoptoë","option_only":true},"bloedonderzoek (calcium)":{"title":"Calcium","short":"Mineraal dat essentieel is voor botmineralisatie, spiercontractie en zenuwgeleiding. Opname in de darm wordt bevorderd door 1,25-OH-vitamine D (calcitriol).","definition":"<p><strong>Calcium</strong> wordt in de dunne darm actief opgenomen onder invloed van 1,25-dihydroxyvitamine D. Het grootste deel van het lichaamscalcium ligt opgeslagen in het skelet als hydroxyapatiet.</p>","image_url":"","wiki_title":"Calcium in biology","match":"bloedonderzoek (calcium)","option_only":true},"plasmaferese":{"title":"Plasmaferese","short":"Techniek waarbij plasma van de patiënt wordt gescheiden en vervangen; gebruikt bij o.a. TTP.","definition":"<p>Bij plasmaferese wordt patiëntenplasma verwijderd en vervangen door donorplasma; essentieel bij trombotische trombocytopenische purpura (aanvulling van ADAMTS-13).</p>","image_url":"","wiki_title":"Plasmapheresis","match":"plasmaferese","option_only":true},"bumetanide":{"title":"Lisdiureticum","short":"Lisdiuretica remmen de NKCC2-cotransporter in de lis van Henle en zijn de krachtigste plasmiddelen.","definition":"<p><strong>Lisdiuretica</strong> zoals furosemide remmen de Na⁺/K⁺/2Cl⁻-cotransporter in het dikke opstijgende deel van de lis van Henle. Ze worden gebruikt bij oedeem door hartfalen, nierziekte of levercirrose en bij longoedeem. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, metabole alkalose, uitdroging en ototoxiciteit; anders dan thiaziden verhogen ze de calciumuitscheiding.</p>","image_url":"","wiki_title":"Loop diuretic","match":"bumetanide","option_only":true},"aortaklep stenose":{"title":"Aortaklepstenose","short":"Bij aortaklepstenose opent de aortaklep onvoldoende, waardoor de linkerventrikel tegen verhoogde weerstand moet pompen.","definition":"<p><strong>Aortaklepstenose</strong> ontstaat meestal door degeneratieve verkalking op oudere leeftijd of bij een aangeboren bicuspide klep. De linkerventrikel hypertrofieert. Bij auscultatie is er een systolisch ejectiegeruis aan de basis, vaak uitstralend naar de carotiden. Klachten (angina, syncope bij inspanning, hartfalen) wijzen op een ernstige stenose; behandeling is klepvervanging (chirurgisch of TAVI).</p>","image_url":"","wiki_title":"Aortic stenosis","match":"aortaklep stenose","option_only":true},"aortaklep insufficiëntie":{"title":"Aortaklepinsufficiëntie","short":"Bij aortaklepinsufficiëntie sluit de aortaklep niet goed, waardoor bloed in de diastole terugstroomt naar de linkerventrikel.","definition":"<p>Bij <strong>aortaklepinsufficiëntie</strong> ontstaat volumebelasting van de linkerventrikel, die verwijdt. Oorzaken zijn o.a. een bicuspide klep, endocarditis, verwijding van de aortawortel (hypertensie, Marfan, dissectie). Kenmerkend zijn een diastolisch decrescendo-geruis langs de linker sternumrand en een grote polsdruk (snel stijgende en dalende pols).</p>","image_url":"","wiki_title":"Aortic insufficiency","match":"aortaklep insufficiëntie","option_only":true},"mitralisklep insufficiëntie":{"title":"Mitralisinsufficiëntie","short":"Bij mitralisinsufficiëntie sluit de mitralisklep onvoldoende, waardoor bloed in de systole terugstroomt naar het linkeratrium.","definition":"<p><strong>Mitralisinsufficiëntie</strong> kan primair zijn (klepprolaps, endocarditis, reumatische klepziekte) of secundair aan verwijding of ischemie van de linkerventrikel. Het linkeratrium raakt overbelast, met risico op boezemfibrilleren en longstuwing. Bij auscultatie hoort men een holosystolisch geruis aan de apex, uitstralend naar de oksel.</p>","image_url":"","wiki_title":"Mitral insufficiency","match":"mitralisklep insufficiëntie","option_only":true},"pulmonalisklep insufficiëntie":{"title":"Pulmonalisklepinsufficiëntie","short":"Bij pulmonalisklepinsufficiëntie lekt bloed in de diastole terug van de longslagader naar de rechterventrikel.","definition":"<p>Een lichte lekkage is vaak fysiologisch. Ernstige <strong>pulmonalisinsufficiëntie</strong> komt vooral voor na chirurgische correctie van een tetralogie van Fallot en bij pulmonale hypertensie; het kan leiden tot verwijding en falen van de rechterventrikel.</p>","image_url":"","wiki_title":"Pulmonary valve insufficiency","match":"pulmonalisklep insufficiëntie","option_only":true},"thiazidediureticum":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"thiazidediureticum","option_only":true},"diuretica":{"title":"Diuretica","short":"Plasmiddelen die de urineproductie verhogen; gebruikt bij overvulling, hartfalen en hypertensie.","definition":"<p>Diuretica verhogen de uitscheiding van water en zouten door de nier. Ze worden gebruikt bij hartfalen, hypertensie en oedeem. Staken kan de bloeddruk en GFR doen stijgen, maar geeft bij hartfalen risico op longstuwing en overvulling.</p>","image_url":"","wiki_title":"Diuretic","match":"diuretica","option_only":true},"trombotische trombocytopenische purpura":{"title":"Trombotische trombocytopenische purpura (TTP)","short":"Levensbedreigende microangiopathie met trombocytopenie, hemolytische anemie en neurologische verschijnselen.","definition":"<p>TTP berust op ADAMTS13-deficiëntie met microtrombi. Kenmerken zijn anemie met sterk verhoogd LDH, trombocytopenie en verwardheid; het vereist directe verwijzing en plasmaferese.</p>","image_url":"","wiki_title":"Thrombotic thrombocytopenic purpura","match":"trombotische trombocytopenische purpura","option_only":true},"betablokkers":{"title":"Bètablokker","short":"Bètablokkers blokkeren bèta-adrenerge receptoren en verlagen hartfrequentie, contractiekracht en reninesecretie.","definition":"<p><strong>Bètablokkers</strong> worden gebruikt bij hypertensie, angina pectoris, na een hartinfarct, bij hartfalen, ritmestoornissen, tremor en migraineprofylaxe. Cardioselectieve middelen (metoprolol, bisoprolol) werken vooral op β1; niet-selectieve (propranolol) ook op β2, wat bronchospasme kan geven. Bijwerkingen: bradycardie, vermoeidheid, koude extremiteiten en het maskeren van hypoglykemieverschijnselen.</p>","image_url":"","wiki_title":"Beta blocker","match":"betablokkers","option_only":true},"bèta-blokker":{"title":"Bètablokker","short":"Bètablokkers blokkeren bèta-adrenerge receptoren en verlagen hartfrequentie, contractiekracht en reninesecretie.","definition":"<p><strong>Bètablokkers</strong> worden gebruikt bij hypertensie, angina pectoris, na een hartinfarct, bij hartfalen, ritmestoornissen, tremor en migraineprofylaxe. Cardioselectieve middelen (metoprolol, bisoprolol) werken vooral op β1; niet-selectieve (propranolol) ook op β2, wat bronchospasme kan geven. Bijwerkingen: bradycardie, vermoeidheid, koude extremiteiten en het maskeren van hypoglykemieverschijnselen.</p>","image_url":"","wiki_title":"Beta blocker","match":"bèta-blokker","option_only":true},"pre- eclampsie":{"title":"Pre-eclampsie","short":"Zwangerschapshypertensie ná 20 weken mét proteïnurie of orgaanschade. Kan overgaan in eclampsie (convulsies).","definition":"<p><strong>Pre-eclampsie</strong> is een zwangerschapscomplicatie met nieuw ontstane hypertensie na 20 weken samen met proteïnurie of tekenen van orgaanschade. Onbehandeld kan het leiden tot eclampsie (insulten) en HELLP-syndroom.</p>","image_url":"","wiki_title":"Pre-eclampsia","match":"pre- eclampsie","option_only":true},"asat":{"title":"ASAT en ALAT","short":"ASAT en ALAT zijn enzymen die vrijkomen bij beschadiging van levercellen; ALAT is specifieker voor de lever.","definition":"<p>Zeer hoge <strong>transaminasen</strong> (&gt; 1000) passen bij virale hepatitis, ischemische hepatitis en paracetamolvergiftiging. Een ASAT/ALAT-ratio boven 2 past bij alcoholische leverziekte. ASAT komt ook vrij bij spier- en hartspierschade.</p>","image_url":"","wiki_title":"Aspartate transaminase","match":"asat|alat|transaminasen|levertransaminasen","option_only":true},"d-dimeer bepalen":{"title":"D-dimeer","short":"D-dimeer is een afbraakproduct van fibrine; een normale waarde maakt trombose of longembolie onwaarschijnlijk bij een laag klinisch risico.","definition":"<p><strong>D-dimeer</strong> is gevoelig maar niet specifiek: het is ook verhoogd na operaties, bij infecties, kanker, zwangerschap en ouderdom. Daarom wordt het alleen gebruikt in combinatie met een beslisregel (Wells, YEARS).</p>","image_url":"","wiki_title":"D-dimer","match":"d-dimeer bepalen|d-dimeer|d-dimeren","option_only":true},"arterosclerose":{"title":"Atherosclerose","short":"Atherosclerose is een chronisch ontstekingsproces in de vaatwand waarbij plaques met vet, ontstekingscellen en bindweefsel ontstaan.","definition":"<p>Bij <strong>atherosclerose</strong> dringt LDL de intima binnen en wordt het geoxideerd; monocyten worden macrofagen en schuimcellen (fatty streak). Gladde spiercellen migreren en vormen een fibreuze kap over een lipidenkern. Scheuren van een plaque met trombose veroorzaakt een acuut coronair syndroom of herseninfarct. Risicofactoren: roken, hypertensie, LDL, diabetes, leeftijd en familiaire belasting.</p>","image_url":"","wiki_title":"Atherosclerosis","match":"arterosclerose","option_only":true},"syntax":{"title":"Risicoscores in de cardiologie","short":"Er zijn verschillende risicoscores: de SYNTAX-score (complexiteit van coronairlijden), de HEART-score (pijn op de borst op de SEH) en de Framingham-score (10-jaarsrisico op hart- en vaatziekten).","definition":"<p>De <strong>HEART-score</strong> gebruikt anamnese, ECG, leeftijd, risicofactoren en troponine. De <strong>SYNTAX-score</strong> helpt kiezen tussen PCI en bypasschirurgie. In Nederland wordt voor het 10-jaarsrisico vaak SCORE2 gebruikt in plaats van Framingham.</p>","image_url":"","wiki_title":"","match":"syntax|syntax-score|heart|heart-score|framingham|framingham-risicoscore","option_only":true},"diastolische bloeddruk":{"title":"Bloeddrukwaarden","short":"De diastolische bloeddruk is de laagste druk in de slagaders tijdens de ontspanning van het hart; de gemiddelde arteriële druk (MAP) is de gemiddelde druk over een hele hartcyclus.","definition":"<p>De <strong>MAP</strong> is ongeveer de diastolische druk plus een derde van de polsdruk, en bepaalt de doorbloeding van de organen; op de IC wordt vaak gestreefd naar een MAP van minimaal 65 mmHg.</p>","image_url":"","wiki_title":"Mean arterial pressure","match":"diastolische bloeddruk|gemiddelde bloeddruk|mean arterial pressure|map","option_only":true}};
